def _mpesa_savings_prepare_positions(
    current_savings: pd.DataFrame | None,
    fixed_savings: pd.DataFrame | None,
    *,
    as_of_date: Any,
    annual_interest_rate_pct: float | None,
) -> pd.DataFrame:
    """Prepare la position epargne/DAT actuelle sans inventer d'historique."""

    parts: list[pd.DataFrame] = []
    for family, source in [
        ("Compte ouvert", current_savings),
        ("DAT", fixed_savings),
    ]:
        if not isinstance(source, pd.DataFrame) or source.empty:
            continue
        frame = source.copy()
        frame["famille_epargne"] = family
        for column in [
            "id", "savings_id", "customer_id", "Nom_client", "msisdn", "msisdn1",
            "product_id", "product_name", "product_description", "account_type",
            "currency_code", "balance", "status", "date_closed", "date_approved",
            "date_activated", "maturity_date", "is_interest_calculated",
            "last_interest_calculation_date", "next_interest_calculation_date",
            "interest_earned", "voda_interest", "fees_due", "locked_balance",
            "date_locked", "created_at", "updated_at",
            "fichier_source_epargne_turbo", "fichiers_sources_epargne_turbo",
            "source_savings_account_complete",
        ]:
            if column not in frame.columns:
                frame[column] = pd.NA
        parts.append(frame)

    if not parts:
        return pd.DataFrame()

    frame = concat_frames_stable(parts).reset_index(drop=True)
    frame["savings_id"] = clean_identifier(frame["savings_id"]).where(
        clean_identifier(frame["savings_id"]).ne(""),
        clean_identifier(frame["id"]),
    )
    frame["customer_id"] = clean_identifier(frame["customer_id"])
    frame["Nom_client"] = clean_text(frame["Nom_client"])
    frame["msisdn"] = normalize_phone(
        frame["msisdn"].where(frame["msisdn"].notna(), frame["msisdn1"])
    )
    frame["msisdn1"] = normalize_phone(frame["msisdn1"])
    frame["currency_code"] = clean_text(frame["currency_code"]).str.upper().replace("", "NON RENSEIGNEE")
    for column in ["product_id", "product_name", "product_description", "account_type", "status", "is_interest_calculated"]:
        frame[column] = clean_text(frame[column])
    for column in ["balance", "interest_earned", "voda_interest", "fees_due", "locked_balance"]:
        frame[column] = pd.to_numeric(frame[column], errors="coerce").fillna(0.0)
    for column in [
        "date_closed", "date_approved", "date_activated", "maturity_date",
        "last_interest_calculation_date", "next_interest_calculation_date",
        "date_locked", "created_at", "updated_at",
    ]:
        frame[column] = pd.to_datetime(frame[column], errors="coerce")

    frame["date_creation_compte"] = frame["created_at"].combine_first(
        frame["date_approved"]
    ).combine_first(frame["date_activated"])
    frame["solde_positif"] = frame["balance"].gt(0)
    frame["solde_nul"] = frame["balance"].le(0)
    frame["date_situation"] = pd.Timestamp(pd.to_datetime(as_of_date, errors="coerce")).normalize()
    frame["jours_avant_echeance"] = (
        frame["maturity_date"].dt.normalize() - frame["date_situation"]
    ).dt.days
    frame["duree_contractuelle_jours"] = (
        frame["maturity_date"].dt.normalize() - frame["date_approved"].dt.normalize()
    ).dt.days
    interest_rate = pd.to_numeric(
        pd.Series([annual_interest_rate_pct]), errors="coerce"
    ).iloc[0]
    interest_enabled = pd.notna(interest_rate) and float(interest_rate) > 0
    frame["taux_interet_annuel_pct"] = float(interest_rate) if interest_enabled else np.nan
    valid_duration = frame["famille_epargne"].eq("DAT") & frame["duree_contractuelle_jours"].ge(0)
    frame["interet_estime"] = np.nan
    if interest_enabled:
        frame.loc[valid_duration, "interet_estime"] = (
            frame.loc[valid_duration, "balance"]
            * float(interest_rate)
            / 100
            * frame.loc[valid_duration, "duree_contractuelle_jours"]
            / 365
        )
    frame["capital_plus_interet_estime"] = frame["balance"] + frame["interet_estime"]
    frame["tranche_echeance"] = np.select(
        [
            frame["famille_epargne"].ne("DAT"),
            frame["maturity_date"].isna(),
            frame["jours_avant_echeance"].lt(0),
            frame["jours_avant_echeance"].eq(0),
            frame["jours_avant_echeance"].le(7),
            frame["jours_avant_echeance"].le(30),
            frame["jours_avant_echeance"].le(60),
            frame["jours_avant_echeance"].le(90),
        ],
        [
            "Non applicable",
            "Date manquante",
            "Echu",
            "Aujourd'hui",
            "0-7 jours",
            "8-30 jours",
            "31-60 jours",
            "61-90 jours",
        ],
        default="> 90 jours",
    )
    frame["source_position"] = np.where(
        frame["famille_epargne"].eq("DAT"),
        "Savings Account - FIXED SAVINGS",
        "Savings Account - NORMAL SAVINGS",
    )
    return frame.reset_index(drop=True)


def build_mpesa_savings_cockpit(
    prepared: MpesaPreparedData,
    *,
    date_start: Any | None = None,
    date_end: Any | None = None,
    frequency: str = "Mois",
    annual_interest_rate_pct: float | None = DEFAULT_DAT_ANNUAL_INTEREST_RATE_PCT,
    inactivity_threshold_days: int = 30,
    maturity_horizon_days: int = DEFAULT_DAT_REPAYMENT_PREPARATION_HORIZON_DAYS,
    large_savings_thresholds: dict[str, float] | None = None,
    turbo_events: pd.DataFrame | None = None,
    turbo_transaction_lines: pd.DataFrame | None = None,
) -> dict[str, Any]:
    """Construit le cockpit Epargnes depuis Savings Account et Transactions.

    ``Savings Account`` porte la position actuelle. ``Transactions`` porte les
    flux observes sur la periode. G2 ne modifie aucun montant.
    """

    transactions = prepared.transactions if isinstance(prepared.transactions, pd.DataFrame) else pd.DataFrame()
    transaction_dates = (
        pd.to_datetime(transactions["created_at"], errors="coerce").dropna()
        if not transactions.empty and "created_at" in transactions.columns
        else pd.Series(dtype="datetime64[ns]")
    )
    fallback_end = _mpesa_analysis_date(prepared, date_end)
    end_date = pd.Timestamp(fallback_end).normalize()
    if date_start is not None and pd.notna(pd.to_datetime(date_start, errors="coerce")):
        start_date = pd.Timestamp(pd.to_datetime(date_start, errors="coerce")).normalize()
    elif not transaction_dates.empty:
        start_date = pd.Timestamp(transaction_dates.min()).normalize()
    else:
        start_date = end_date
    if start_date > end_date:
        start_date, end_date = end_date, start_date
    period_end_exclusive = end_date + pd.Timedelta(days=1)

    result = _mpesa_savings_empty_cockpit()
    result["periode"] = pd.DataFrame(
        [
            {
                "date_debut": start_date,
                "date_fin": end_date,
                "frequence": frequency,
                "taux_interet_annuel_dat_pct": annual_interest_rate_pct,
                "horizon_echeance_dat_jours": maturity_horizon_days,
                "seuil_inactivite_observee_jours": inactivity_threshold_days,
            }
        ]
    )

    positions = _mpesa_savings_prepare_positions(
        prepared.current_savings,
        prepared.fixed_savings,
        as_of_date=end_date,
        annual_interest_rate_pct=annual_interest_rate_pct,
    )
    if not positions.empty:
        snapshot_mask = _mpesa_statistics_snapshot_mask(
            positions,
            as_of_date=end_date,
            creation_columns=(
                "date_creation_compte",
                "created_at",
                "date_approved",
                "date_activated",
            ),
            closed_column="date_closed",
            status_column="status",
        )
        positions = positions.loc[snapshot_mask].copy().reset_index(drop=True)
    result["portefeuille_detail"] = positions
    if positions.empty:
        result["qualite_donnees"] = pd.DataFrame(
            [
                {
                    "controle": "Savings Account",
                    "valeur": 0,
                    "statut": "A verifier",
                    "detail": "Aucun fichier Savings Account exploitable pour construire le cockpit epargne.",
                }
            ]
        )
        result["catalogue_kpi"] = pd.DataFrame(MPESA_SAVINGS_DATA_GAPS)
        return result

    result["comptes_courants_detail"] = positions.loc[
        positions["famille_epargne"].eq("Compte ouvert")
    ].reset_index(drop=True)
    result["dat_detail"] = positions.loc[positions["famille_epargne"].eq("DAT")].reset_index(drop=True)

    def _nunique_clients(values: pd.Series) -> int:
        return int(clean_identifier(values).replace("", pd.NA).nunique())

    result["portefeuille_synthese"] = (
        positions.groupby(["currency_code", "famille_epargne"], as_index=False, dropna=False)
        .agg(
            nombre_comptes=("savings_id", "nunique"),
            nombre_clients=("customer_id", _nunique_clients),
            comptes_solde_positif=("solde_positif", "sum"),
            comptes_solde_nul=("solde_nul", "sum"),
            encours_actuel=("balance", "sum"),
            solde_moyen=("balance", "mean"),
            solde_median=("balance", "median"),
            interet_constate=("interest_earned", lambda values: values.sum(min_count=1)),
            interet_vodacom=("voda_interest", lambda values: values.sum(min_count=1)),
            frais_a_payer=("fees_due", lambda values: values.sum(min_count=1)),
            solde_bloque_technique=("locked_balance", lambda values: values.sum(min_count=1)),
        )
        .sort_values(["currency_code", "famille_epargne"])
        .reset_index(drop=True)
    )

    dat_maturity = build_mpesa_dat_maturity_analysis(
        result["dat_detail"],
        as_of_date=end_date,
        annual_interest_rate_pct=annual_interest_rate_pct,
        preparation_horizon_days=maturity_horizon_days,
    )
    result["dat_echeances_synthese"] = dat_maturity.get("synthese", pd.DataFrame())
    result["dat_echeances_detail"] = dat_maturity.get("detail", pd.DataFrame())

    events_source = turbo_events if isinstance(turbo_events, pd.DataFrame) else pd.DataFrame()
    activity_start = min(
        start_date,
        end_date - pd.Timedelta(days=max(int(inactivity_threshold_days) * 3, 1)),
    )
    if events_source.empty and not transactions.empty:
        scoped_transactions = transactions
        if "created_at" in transactions.columns:
            scoped_dates = pd.to_datetime(transactions["created_at"], errors="coerce")
            scoped_transactions = transactions.loc[
                scoped_dates.notna()
                & scoped_dates.ge(activity_start)
                & scoped_dates.lt(period_end_exclusive)
            ].copy()
        events_source = build_turbo_operation_events(scoped_transactions).get("events", pd.DataFrame())
    savings_events = pd.DataFrame()
    activity_savings_events = pd.DataFrame()
    if isinstance(events_source, pd.DataFrame) and not events_source.empty:
        events_source = events_source.copy()
        events_source["created_at"] = pd.to_datetime(events_source["created_at"], errors="coerce")
        savings_operation_types = [
            "Sortie M-PESA_Turbo vers epargne",
            "Sortie M-PESA_Turbo vers DAT",
            "Entree M-PESA_Turbo depuis epargne",
            "Transfert DAT vers epargne courante",
            "Remboursement de credit",
            "Remboursement avec penalite",
        ]
        typed_events = events_source.loc[
            events_source["created_at"].ge(activity_start)
            & events_source["created_at"].lt(period_end_exclusive)
            & clean_text(events_source["type_operation"]).isin(savings_operation_types)
        ].copy()
        activity_savings_events = typed_events.copy()
        savings_events = typed_events.loc[typed_events["created_at"].ge(start_date)].copy()

    if not activity_savings_events.empty:
        for column in [
            "event_key", "customer_id", "telephone", "Nom_client", "currency_code",
            "type_operation", "montant_operation", "remboursement_compte_ouvert",
            "created_at", "event_reference",
        ]:
            if column not in activity_savings_events.columns:
                activity_savings_events[column] = pd.NA
        activity_savings_events["currency_code"] = clean_text(activity_savings_events["currency_code"]).str.upper().replace("", "NON RENSEIGNEE")
        activity_savings_events["montant_operation"] = pd.to_numeric(
            activity_savings_events["montant_operation"], errors="coerce"
        ).fillna(0.0)
        activity_savings_events["remboursement_compte_ouvert"] = pd.to_numeric(
            activity_savings_events["remboursement_compte_ouvert"], errors="coerce"
        ).fillna(0.0)
        operation_type = clean_text(activity_savings_events["type_operation"])
        activity_savings_events["montant_depot_compte_ouvert"] = activity_savings_events["montant_operation"].where(
            operation_type.eq("Sortie M-PESA_Turbo vers epargne"), 0.0
        )
        activity_savings_events["montant_depot_dat"] = activity_savings_events["montant_operation"].where(
            operation_type.eq("Sortie M-PESA_Turbo vers DAT"), 0.0
        )
        activity_savings_events["montant_retrait_compte_ouvert"] = activity_savings_events["montant_operation"].where(
            operation_type.eq("Entree M-PESA_Turbo depuis epargne"), 0.0
        )
        activity_savings_events["montant_retour_dat"] = activity_savings_events["montant_operation"].where(
            operation_type.eq("Transfert DAT vers epargne courante"), 0.0
        )
        activity_savings_events["montant_remboursement_depuis_compte_ouvert"] = activity_savings_events["remboursement_compte_ouvert"].where(
            operation_type.isin(["Remboursement de credit", "Remboursement avec penalite"]),
            0.0,
        )
        savings_events = activity_savings_events.loc[
            activity_savings_events["created_at"].ge(start_date)
        ].copy()

    if not savings_events.empty:
        operation_type = clean_text(savings_events["type_operation"])
        savings_events["periode"] = _turbo_period_bucket(savings_events["created_at"], frequency)
        deposits_mask = operation_type.isin(["Sortie M-PESA_Turbo vers epargne", "Sortie M-PESA_Turbo vers DAT"])
        withdrawals_mask = operation_type.eq("Entree M-PESA_Turbo depuis epargne")
        repayments_open_mask = savings_events["montant_remboursement_depuis_compte_ouvert"].gt(0)
        flow_summary = (
            savings_events.groupby("currency_code", as_index=False, dropna=False)
            .agg(
                nombre_depots=("event_key", lambda values: int(values.loc[deposits_mask.loc[values.index]].nunique())),
                clients_depots=("customer_id", lambda values: _nunique_clients(values.loc[deposits_mask.loc[values.index]])),
                montant_depots_compte_ouvert=("montant_depot_compte_ouvert", "sum"),
                montant_depots_dat=("montant_depot_dat", "sum"),
                nombre_retraits=("event_key", lambda values: int(values.loc[withdrawals_mask.loc[values.index]].nunique())),
                clients_retraits=("customer_id", lambda values: _nunique_clients(values.loc[withdrawals_mask.loc[values.index]])),
                montant_retraits=("montant_retrait_compte_ouvert", "sum"),
                nombre_remboursements_depuis_compte_ouvert=("event_key", lambda values: int(values.loc[repayments_open_mask.loc[values.index]].nunique())),
                montant_remboursements_depuis_compte_ouvert=("montant_remboursement_depuis_compte_ouvert", "sum"),
                retours_dat=("montant_retour_dat", "sum"),
                nombre_operations_epargne=("event_key", "nunique"),
                clients_actifs_observes=("customer_id", _nunique_clients),
            )
        )
        flow_summary["montant_depots_total"] = (
            flow_summary["montant_depots_compte_ouvert"] + flow_summary["montant_depots_dat"]
        )
        flow_summary["depot_moyen"] = flow_summary["montant_depots_total"].div(
            flow_summary["nombre_depots"].replace(0, pd.NA)
        )
        flow_summary["retrait_moyen"] = flow_summary["montant_retraits"].div(
            flow_summary["nombre_retraits"].replace(0, pd.NA)
        )
        flow_summary["flux_net_epargne"] = (
            flow_summary["montant_depots_compte_ouvert"]
            + flow_summary["montant_depots_dat"]
            + flow_summary["retours_dat"]
            - flow_summary["montant_retraits"]
            - flow_summary["montant_remboursements_depuis_compte_ouvert"]
        )
        result["flux_synthese"] = flow_summary.sort_values("currency_code").reset_index(drop=True)
        result["activite_clients"] = (
            activity_savings_events.groupby(
                ["currency_code", "customer_id"], as_index=False, dropna=False
            )
            .agg(
                telephone=("telephone", concat_unique),
                Nom_client=("Nom_client", concat_unique),
                nombre_operations=("event_key", "nunique"),
                depots_epargne_courante=("montant_depot_compte_ouvert", "sum"),
                depots_dat=("montant_depot_dat", "sum"),
                retraits_epargne=("montant_retrait_compte_ouvert", "sum"),
                retours_dat=("montant_retour_dat", "sum"),
                remboursements_depuis_compte_ouvert=("montant_remboursement_depuis_compte_ouvert", "sum"),
                premiere_operation=("created_at", "min"),
                derniere_operation=("created_at", "max"),
            )
            .sort_values(["currency_code", "derniere_operation"])
            .reset_index(drop=True)
        )
        result["activite_clients"]["flux_net_epargne"] = (
            result["activite_clients"]["depots_epargne_courante"]
            + result["activite_clients"]["depots_dat"]
            + result["activite_clients"]["retours_dat"]
            - result["activite_clients"]["retraits_epargne"]
            - result["activite_clients"]["remboursements_depuis_compte_ouvert"]
        )
        result["flux_evolution"] = (
            savings_events.groupby(["periode", "currency_code"], as_index=False, dropna=False)
            .agg(
                montant_depots_compte_ouvert=("montant_depot_compte_ouvert", "sum"),
                montant_depots_dat=("montant_depot_dat", "sum"),
                montant_retraits=("montant_retrait_compte_ouvert", "sum"),
                montant_remboursements_depuis_compte_ouvert=("montant_remboursement_depuis_compte_ouvert", "sum"),
                nombre_operations=("event_key", "nunique"),
                clients_actifs=("customer_id", _nunique_clients),
            )
            .sort_values(["currency_code", "periode"])
            .reset_index(drop=True)
        )
    else:
        result["flux_synthese"] = pd.DataFrame(
            columns=[
                "currency_code", "nombre_depots", "clients_depots",
                "montant_depots_compte_ouvert", "montant_depots_dat",
                "nombre_retraits", "clients_retraits", "montant_retraits",
                "nombre_remboursements_depuis_compte_ouvert",
                "montant_remboursements_depuis_compte_ouvert", "retours_dat",
                "nombre_operations_epargne", "clients_actifs_observes",
                "montant_depots_total", "depot_moyen", "retrait_moyen",
                "flux_net_epargne",
            ]
        )

    if result["activite_clients"].empty and not activity_savings_events.empty:
        result["activite_clients"] = (
            activity_savings_events.groupby(
                ["currency_code", "customer_id"], as_index=False, dropna=False
            )
            .agg(
                telephone=("telephone", concat_unique),
                Nom_client=("Nom_client", concat_unique),
                nombre_operations=("event_key", "nunique"),
                depots_epargne_courante=("montant_depot_compte_ouvert", "sum"),
                depots_dat=("montant_depot_dat", "sum"),
                retraits_epargne=("montant_retrait_compte_ouvert", "sum"),
                retours_dat=("montant_retour_dat", "sum"),
                remboursements_depuis_compte_ouvert=("montant_remboursement_depuis_compte_ouvert", "sum"),
                premiere_operation=("created_at", "min"),
                derniere_operation=("created_at", "max"),
            )
            .sort_values(["currency_code", "derniere_operation"])
            .reset_index(drop=True)
        )
        result["activite_clients"]["flux_net_epargne"] = (
            result["activite_clients"]["depots_epargne_courante"]
            + result["activite_clients"]["depots_dat"]
            + result["activite_clients"]["retours_dat"]
            - result["activite_clients"]["retraits_epargne"]
            - result["activite_clients"]["remboursements_depuis_compte_ouvert"]
        )

    if not result["activite_clients"].empty:
        activity = result["activite_clients"].copy()
        activity["customer_id"] = clean_identifier(activity.get("customer_id", pd.Series("", index=activity.index)))
        activity["currency_code"] = clean_text(activity.get("currency_code", pd.Series("", index=activity.index))).str.upper().replace("", "NON RENSEIGNEE")
        activity["derniere_operation"] = pd.to_datetime(activity.get("derniere_operation"), errors="coerce")
        active_keys = activity.loc[
            activity["derniere_operation"].notna(), ["customer_id", "currency_code", "derniere_operation"]
        ].drop_duplicates(["customer_id", "currency_code"])
        account_activity = positions.merge(active_keys, on=["customer_id", "currency_code"], how="left")
    else:
        account_activity = positions.copy()
        account_activity["derniere_operation"] = pd.NaT
    account_activity["jours_inactivite_observee"] = (
        end_date - pd.to_datetime(account_activity["derniere_operation"], errors="coerce").dt.normalize()
    ).dt.days
    account_activity["statut_activite_observee"] = np.select(
        [
            account_activity["derniere_operation"].notna() & account_activity["jours_inactivite_observee"].le(inactivity_threshold_days),
            account_activity["derniere_operation"].notna() & account_activity["jours_inactivite_observee"].le(inactivity_threshold_days * 3),
            account_activity["derniere_operation"].notna(),
        ],
        ["actif", "a_surveille", "inactif_observe"],
        default="historique_insuffisant",
    )
    result["activite_comptes"] = account_activity.sort_values(
        ["currency_code", "famille_epargne", "statut_activite_observee", "balance"],
        ascending=[True, True, True, False],
    ).reset_index(drop=True)

    result["nouveaux_comptes"] = (
        positions.loc[
            positions["date_creation_compte"].notna()
            & positions["date_creation_compte"].ge(start_date)
            & positions["date_creation_compte"].lt(period_end_exclusive)
        ]
        .groupby(["currency_code", "famille_epargne"], as_index=False, dropna=False)
        .agg(
            nouveaux_comptes=("savings_id", "nunique"),
            nouveaux_clients=("customer_id", _nunique_clients),
            comptes_actives=("date_activated", lambda values: int(pd.to_datetime(values, errors="coerce").notna().sum())),
            encours_actuel_nouveaux_comptes=("balance", "sum"),
        )
        .sort_values(["currency_code", "famille_epargne"])
        .reset_index(drop=True)
    )
    if not result["nouveaux_comptes"].empty:
        result["nouveaux_comptes"]["taux_activation_nouveaux_comptes_pct"] = (
            result["nouveaux_comptes"]["comptes_actives"]
            .div(result["nouveaux_comptes"]["nouveaux_comptes"].replace(0, pd.NA))
            .mul(100)
        )

    result["produits_synthese"] = (
        positions.groupby(
            ["currency_code", "famille_epargne", "product_id", "product_name"],
            as_index=False,
            dropna=False,
        )
        .agg(
            nombre_comptes=("savings_id", "nunique"),
            nombre_clients=("customer_id", _nunique_clients),
            encours_actuel=("balance", "sum"),
            comptes_solde_positif=("solde_positif", "sum"),
            comptes_solde_nul=("solde_nul", "sum"),
        )
        .sort_values(["currency_code", "famille_epargne", "encours_actuel"], ascending=[True, True, False])
        .reset_index(drop=True)
    )

    client_balances = (
        positions.groupby(["currency_code", "famille_epargne", "customer_id"], as_index=False, dropna=False)
        .agg(
            Nom_client=("Nom_client", concat_unique),
            telephone=("msisdn", concat_unique),
            nombre_comptes=("savings_id", "nunique"),
            encours_actuel=("balance", "sum"),
            produits=("product_name", concat_unique),
        )
        .sort_values(["currency_code", "famille_epargne", "encours_actuel"], ascending=[True, True, False])
        .reset_index(drop=True)
    )
    client_balances["rang_client"] = client_balances.groupby(
        ["currency_code", "famille_epargne"]
    )["encours_actuel"].rank(method="first", ascending=False).astype(int)
    client_balances = _add_turbo_amount_band_column(
        client_balances,
        amount_column="encours_actuel",
    )
    result["concentration_clients"] = client_balances
    result["concentration_comptes"] = positions.sort_values(
        ["currency_code", "famille_epargne", "balance"],
        ascending=[True, True, False],
    ).reset_index(drop=True)
    concentration_rows: list[dict[str, Any]] = []
    for (currency, family), group in client_balances.groupby(["currency_code", "famille_epargne"], dropna=False):
        ordered = group.sort_values("encours_actuel", ascending=False)
        total = float(pd.to_numeric(ordered["encours_actuel"], errors="coerce").sum())
        concentration_rows.append(
            {
                "currency_code": currency,
                "famille_epargne": family,
                "nombre_clients": int(len(ordered)),
                "encours_actuel": total,
                "part_top_5_clients_pct": float(ordered.head(5)["encours_actuel"].sum() / total * 100) if total else np.nan,
                "part_top_10_clients_pct": float(ordered.head(10)["encours_actuel"].sum() / total * 100) if total else np.nan,
                "part_top_20_clients_pct": float(ordered.head(20)["encours_actuel"].sum() / total * 100) if total else np.nan,
            }
        )
    result["concentration_synthese"] = pd.DataFrame(concentration_rows)
    result["concentration_tranches"] = (
        client_balances.groupby(["currency_code", "famille_epargne", "tranche_encours"], as_index=False, dropna=False)
        .agg(
            nombre_clients=("customer_id", "nunique"),
            nombre_comptes=("nombre_comptes", "sum"),
            encours_actuel=("encours_actuel", "sum"),
        )
        .sort_values(["currency_code", "famille_epargne", "encours_actuel"], ascending=[True, True, False])
        .reset_index(drop=True)
    )
    if not result["concentration_tranches"].empty:
        totals = result["concentration_tranches"].groupby(
            ["currency_code", "famille_epargne"]
        )["encours_actuel"].transform("sum")
        result["concentration_tranches"]["part_encours_pct"] = np.where(
            totals.ne(0),
            result["concentration_tranches"]["encours_actuel"].div(totals).mul(100),
            np.nan,
        )

    dat_positive = result["dat_detail"].loc[result["dat_detail"]["balance"].gt(0)].copy()
    if not dat_positive.empty:
        result["dat_synthese"] = (
            dat_positive.groupby(["currency_code", "tranche_echeance"], as_index=False, dropna=False)
            .agg(
                nombre_dat=("savings_id", "nunique"),
                nombre_clients=("customer_id", _nunique_clients),
                capital_bloque=("balance", "sum"),
                interet_estime=("interet_estime", lambda values: values.sum(min_count=1)),
                capital_plus_interet_estime=("capital_plus_interet_estime", lambda values: values.sum(min_count=1)),
            )
            .sort_values(["currency_code", "tranche_echeance"])
            .reset_index(drop=True)
        )

    opportunities: list[pd.DataFrame] = []
    thresholds = large_savings_thresholds or {"USD": 100.0, "CDF": 500_000.0}
    active_credit = pd.DataFrame(columns=["customer_id", "currency_code", "credit_actif"])
    if isinstance(prepared.loans, pd.DataFrame) and not prepared.loans.empty:
        loans = _mpesa_credit_prepare_portfolio_detail(prepared.loans, as_of_date=end_date)
        active_credit = loans.loc[loans["pret_actif"], ["customer_id", "currency_code"]].drop_duplicates()
        active_credit["credit_actif"] = True
    if not dat_positive.empty:
        dat_without_credit = dat_positive.merge(
            active_credit,
            on=["customer_id", "currency_code"],
            how="left",
        )
        dat_without_credit = dat_without_credit.loc[
            dat_without_credit["credit_actif"].isna()
        ].drop(columns=["credit_actif"], errors="ignore")
    else:
        dat_without_credit = pd.DataFrame()
    if not dat_without_credit.empty:
        dat_without_credit["opportunite"] = "dat_sans_credit_actif"
        dat_without_credit["lecture"] = "Potentiel commercial a analyser, pas une eligibilite automatique."
        opportunities.append(dat_without_credit)
    strong_savings = client_balances.copy()
    strong_savings["seuil_forte_epargne"] = strong_savings["currency_code"].map(thresholds)
    strong_savings = strong_savings.merge(active_credit, on=["customer_id", "currency_code"], how="left")
    strong_savings = strong_savings.loc[
        strong_savings["seuil_forte_epargne"].notna()
        & strong_savings["encours_actuel"].ge(strong_savings["seuil_forte_epargne"])
        & strong_savings["credit_actif"].isna()
    ].copy()
    if not strong_savings.empty:
        strong_savings["opportunite"] = "forte_epargne_sans_credit"
        strong_savings["lecture"] = "Client a contacter selon le seuil expose, sans conclure a l'eligibilite."
        opportunities.append(strong_savings)
    result["opportunites"] = concat_frames_stable(opportunities).reset_index(drop=True)

    active_account = result["activite_comptes"]["statut_activite_observee"].eq("actif")
    zero_accounts = positions.loc[positions["solde_nul"]].copy()
    new_not_activated = positions.loc[
        positions["date_creation_compte"].notna()
        & positions["date_creation_compte"].ge(start_date)
        & positions["date_creation_compte"].lt(period_end_exclusive)
        & positions["date_activated"].isna()
    ].copy()
    dat_30 = dat_positive.loc[
        dat_positive["jours_avant_echeance"].ge(0)
        & dat_positive["jours_avant_echeance"].le(maturity_horizon_days)
    ].copy()
    dat_expired = dat_positive.loc[dat_positive["jours_avant_echeance"].lt(0)].copy()
    result["listes_action"] = {
        "comptes_positifs_sans_mouvement_recent": result["activite_comptes"].loc[
            result["activite_comptes"]["solde_positif"] & ~active_account
        ].copy(),
        "comptes_solde_nul": zero_accounts,
        "nouveaux_comptes_non_actives": new_not_activated,
        "gros_deposants": client_balances.sort_values(
            ["currency_code", "encours_actuel"], ascending=[True, False]
        ).groupby("currency_code", as_index=False, group_keys=False).head(20).reset_index(drop=True),
        "dat_echeance_horizon": dat_30,
        "dat_echus_a_rembourser": dat_expired,
        "dat_sans_credit_actif": dat_without_credit,
        "forte_epargne_sans_credit": strong_savings,
        "comptes_qualite_a_revoir": positions.loc[
            positions["customer_id"].eq("")
            | positions["currency_code"].eq("NON RENSEIGNEE")
            | positions["savings_id"].eq("")
        ].copy(),
    }

    overview_rows: list[dict[str, Any]] = []
    portfolio = result["portefeuille_synthese"]
    flows = result["flux_synthese"]
    currencies = sorted(
        set(portfolio.get("currency_code", pd.Series(dtype=str)).dropna().astype(str))
        | set(flows.get("currency_code", pd.Series(dtype=str)).dropna().astype(str))
    )
    for currency in currencies:
        current_row = portfolio.loc[
            portfolio["currency_code"].astype(str).eq(currency)
            & portfolio["famille_epargne"].astype(str).eq("Compte ouvert")
        ].head(1)
        dat_row = portfolio.loc[
            portfolio["currency_code"].astype(str).eq(currency)
            & portfolio["famille_epargne"].astype(str).eq("DAT")
        ].head(1)
        flow_row = flows.loc[flows["currency_code"].astype(str).eq(currency)].head(1) if "currency_code" in flows.columns else pd.DataFrame()
        overview_rows.extend(
            [
                {"bloc": "Stock actuel", "indicateur": "encours_epargne_courante", "currency_code": currency, "valeur": float(current_row.iloc[0].get("encours_actuel", 0)) if not current_row.empty else 0.0, "unite": "montant"},
                {"bloc": "Stock actuel", "indicateur": "encours_dat", "currency_code": currency, "valeur": float(dat_row.iloc[0].get("encours_actuel", 0)) if not dat_row.empty else 0.0, "unite": "montant"},
                {"bloc": "Stock actuel", "indicateur": "clients_epargnants", "currency_code": currency, "valeur": float(positions.loc[positions["currency_code"].astype(str).eq(currency), "customer_id"].replace("", pd.NA).nunique()), "unite": "nombre"},
                {"bloc": "Stock actuel", "indicateur": "comptes_courants", "currency_code": currency, "valeur": float(current_row.iloc[0].get("nombre_comptes", 0)) if not current_row.empty else 0.0, "unite": "nombre"},
                {"bloc": "Stock actuel", "indicateur": "dat_positifs", "currency_code": currency, "valeur": float(dat_row.iloc[0].get("comptes_solde_positif", 0)) if not dat_row.empty else 0.0, "unite": "nombre"},
                {"bloc": "Flux periode", "indicateur": "depots_periode", "currency_code": currency, "valeur": float(flow_row.iloc[0].get("montant_depots_total", 0)) if not flow_row.empty else 0.0, "unite": "montant"},
                {"bloc": "Flux periode", "indicateur": "retraits_periode", "currency_code": currency, "valeur": float(flow_row.iloc[0].get("montant_retraits", 0)) if not flow_row.empty else 0.0, "unite": "montant"},
                {"bloc": "Flux periode", "indicateur": "flux_net_epargne_observe", "currency_code": currency, "valeur": float(flow_row.iloc[0].get("flux_net_epargne", 0)) if not flow_row.empty else 0.0, "unite": "montant"},
                {"bloc": "Activite observee", "indicateur": "comptes_actifs_observes", "currency_code": currency, "valeur": float(result["activite_comptes"].loc[result["activite_comptes"]["currency_code"].astype(str).eq(currency) & result["activite_comptes"]["statut_activite_observee"].eq("actif"), "savings_id"].nunique()), "unite": "nombre"},
                {"bloc": "DAT", "indicateur": f"dat_echeance_{maturity_horizon_days}j", "currency_code": currency, "valeur": float(dat_30.loc[dat_30["currency_code"].astype(str).eq(currency), "savings_id"].nunique()), "unite": "nombre"},
            ]
        )
    result["vue_ensemble"] = pd.DataFrame(overview_rows)

    quality_rows = [
        {
            "controle": "Savings Account charge",
            "valeur": int(len(positions)),
            "statut": "OK",
            "detail": "Position actuelle des comptes ouverts et DAT.",
        },
        {
            "controle": "Comptes sans numero",
            "valeur": int(positions["savings_id"].eq("").sum()),
            "statut": "A verifier" if int(positions["savings_id"].eq("").sum()) else "OK",
            "detail": "savings_id ou id manquant.",
        },
        {
            "controle": "Comptes sans devise",
            "valeur": int(positions["currency_code"].eq("NON RENSEIGNEE").sum()),
            "statut": "A verifier" if int(positions["currency_code"].eq("NON RENSEIGNEE").sum()) else "OK",
            "detail": "Les montants doivent rester separes par devise.",
        },
        {
            "controle": "Transactions potentiellement plafonnees",
            "valeur": int(len(transactions)),
            "statut": "A verifier" if len(transactions) >= 100_000 else "OK",
            "detail": "historique_transactions_potentiellement_plafonne si le fichier atteint 100 000 lignes.",
        },
        {
            "controle": "Historique d'inactivite",
            "valeur": int((result["activite_comptes"]["statut_activite_observee"].eq("historique_insuffisant")).sum()),
            "statut": "Information",
            "detail": "Une absence de mouvement observe ne suffit pas a certifier une dormance reglementaire.",
        },
        {
            "controle": "G2",
            "valeur": int(len(prepared.g2_transactions)) if isinstance(prepared.g2_transactions, pd.DataFrame) else 0,
            "statut": "Information",
            "detail": "G2 sert au controle et a l'identite; il ne modifie pas les KPI d'epargne.",
        },
    ]
    invalid_dat_dates = positions.loc[
        positions["famille_epargne"].eq("DAT")
        & positions["date_approved"].notna()
        & positions["maturity_date"].notna()
        & positions["maturity_date"].lt(positions["date_approved"])
    ]
    quality_rows.append(
        {
            "controle": "Dates DAT incoherentes",
            "valeur": int(len(invalid_dat_dates)),
            "statut": "A verifier" if len(invalid_dat_dates) else "OK",
            "detail": "maturity_date anterieure a date_approved.",
        }
    )
    result["qualite_donnees"] = pd.DataFrame(quality_rows)

    implemented_catalogue = pd.DataFrame(
        [
            {
                "kpi": "encours_epargne_courante",
                "definition": "Solde actuel des comptes NORMAL SAVINGS.",
                "formule": "Somme balance des comptes ouverts",
                "source": "Savings Account",
                "grain": "compte x devise",
                "devise": "oui",
                "type_mesure": "stock_actuel",
                "statut": "implemente",
                "limite": "Position instantanee, pas historique.",
            },
            {
                "kpi": "encours_dat",
                "definition": "Solde actuel des comptes FIXED SAVINGS.",
                "formule": "Somme balance des DAT",
                "source": "Savings Account",
                "grain": "DAT x devise",
                "devise": "oui",
                "type_mesure": "stock_actuel",
                "statut": "implemente",
                "limite": "Position instantanee.",
            },
            {
                "kpi": "flux_net_epargne_observe",
                "definition": "Flux net observe sur les comptes d'epargne pendant la periode.",
                "formule": "depots compte ouvert + depots DAT + retours DAT - retraits - remboursements depuis compte ouvert",
                "source": "Transactions",
                "grain": "periode x devise",
                "devise": "oui",
                "type_mesure": "flux_periode",
                "statut": "implemente",
                "limite": "Flux observe; ne pas le confondre avec la collecte externe nette institutionnelle.",
            },
            {
                "kpi": "interet_estime_dat",
                "definition": "Estimation de preparation du remboursement DAT.",
                "formule": "capital * taux annuel / 100 * duree contractuelle jours / 365",
                "source": "Savings Account",
                "grain": "DAT",
                "devise": "oui",
                "type_mesure": "estimation",
                "statut": "implemente",
                "limite": "Ce n'est pas une ecriture comptable officielle.",
            },
        ]
    )
    result["catalogue_kpi"] = concat_frames_stable(
        [implemented_catalogue, pd.DataFrame(MPESA_SAVINGS_DATA_GAPS)]
    )
    return result


def _build_customer_observed_positions(
    prepared: MpesaPreparedData,
    transaction_lines: pd.DataFrame,
    customer_id: object,
    *,
    comparison_allowed: bool,
) -> pd.DataFrame:
    position_columns = [
        "customer_id", "currency_code", "famille_position", "source_observation",
        "solde_transactions_observe", "date_derniere_ecriture", "nombre_comptes_observes",
        "references_ambigues", "source_solde_reference", "solde_reference",
        "nombre_comptes_reference", "ecart_reference", "statut_rapprochement_solde",
    ]
    lines = transaction_lines.loc[
        transaction_lines.get("account_type", pd.Series("", index=transaction_lines.index)).isin(
            CUSTOMER_POSITION_ACCOUNT_LABELS
        )
    ].copy()
    if not lines.empty:
        normalized_description = lines.get(
            "description", pd.Series("", index=lines.index)
        ).apply(normalize_label)
        if "event_key" in lines.columns:
            open_repayment_events = set(
                lines.loc[
                    lines["account_type"].eq("NORMAL SAVINGS")
                    & normalized_description.str.contains(
                        r"remboursement.*compte|compte.*remboursement",
                        regex=True,
                        na=False,
                    ),
                    "event_key",
                ].astype(str)
            )
            # Certains remboursements depuis le compte ouvert portent aussi
            # une ligne technique FIXED SAVINGS. Elle ne constitue pas une
            # sortie du DAT et ne doit pas écraser sa dernière position réelle.
            technical_fixed_repayment = (
                lines["account_type"].eq("FIXED SAVINGS")
                & lines["event_key"].astype(str).isin(open_repayment_events)
                & normalized_description.str.contains(
                    r"remboursement.*compte|compte.*remboursement",
                    regex=True,
                    na=False,
                )
            )
            lines = lines.loc[~technical_fixed_repayment].copy()
            normalized_description = normalized_description.loc[lines.index]
        principle_lines = lines["account_type"].eq("PRINCIPLE")
        valid_principle_position = (
            normalized_description.str.contains("montant principal", na=False)
            & numeric_column(lines, "dr").gt(0)
        ) | (
            normalized_description.str.contains("remboursement du principal", na=False)
            & numeric_column(lines, "cr").gt(0)
        )
        lines = lines.loc[~principle_lines | valid_principle_position].copy()
    observed = pd.DataFrame()
    if not lines.empty:
        lines["reference_id"] = clean_text(lines.get("reference_id", pd.Series("", index=lines.index)))
        lines["customer_id"] = clean_identifier(lines["customer_id"])
        lines["currency_code"] = clean_text(lines["currency_code"]).str.upper().replace("", "NON RENSEIGNEE")
        lines["created_at"] = pd.to_datetime(lines["created_at"], errors="coerce")
        lines["bal_after"] = numeric_column(lines, "bal_after")
        grouping = ["customer_id", "currency_code", "account_type"]
        known_references = {
            key: [value for value in values if value]
            for key, values in lines.groupby(grouping, dropna=False)["reference_id"].apply(
                lambda values: list(dict.fromkeys(clean_text(values).replace("", pd.NA).dropna().tolist()))
            ).items()
        }

        def resolved_account(row: pd.Series) -> str:
            reference = str(row.get("reference_id", "")).strip()
            if reference:
                return reference
            known = known_references.get((row["customer_id"], row["currency_code"], row["account_type"]), [])
            if len(known) == 1:
                return known[0]
            if not known:
                return "SANS_REFERENCE"
            return "REFERENCE_AMBIGUE"

        lines["__account_key"] = lines.apply(resolved_account, axis=1)
        ambiguous = (
            lines.loc[lines["__account_key"].eq("REFERENCE_AMBIGUE")]
            .groupby(["currency_code", "account_type"], as_index=False)
            .size()
            .rename(columns={"size": "references_ambigues"})
        )
        usable = lines.loc[~lines["__account_key"].eq("REFERENCE_AMBIGUE")].copy()
        latest = (
            usable.sort_values(["created_at", "__row_order"], na_position="first")
            .drop_duplicates(["currency_code", "account_type", "__account_key"], keep="last")
        )
        if not latest.empty:
            observed = (
                latest.groupby(["currency_code", "account_type"], as_index=False, dropna=False)
                .agg(
                    solde_transactions_observe=("bal_after", "sum"),
                    date_derniere_ecriture=("created_at", "max"),
                    nombre_comptes_observes=("__account_key", "nunique"),
                )
            )
            observed = observed.merge(ambiguous, on=["currency_code", "account_type"], how="left")
            observed["references_ambigues"] = numeric_column(observed, "references_ambigues").astype(int)
            observed["famille_position"] = observed["account_type"].map(CUSTOMER_POSITION_ACCOUNT_LABELS)
            observed["source_observation"] = "Transactions - dernier bal_after observe"
            observed = observed.drop(columns="account_type")

    customer_key = str(customer_id).strip()
    reference_blocks: list[pd.DataFrame] = []

    def reference_block(
        source: pd.DataFrame,
        *,
        family: str,
        source_label: str,
        balance_column: str,
        account_column: str | None = None,
    ) -> None:
        if not isinstance(source, pd.DataFrame) or source.empty or "customer_id" not in source.columns:
            return
        block = source.loc[clean_identifier(source["customer_id"]).eq(customer_key)].copy()
        if block.empty or "currency_code" not in block.columns or balance_column not in block.columns:
            return
        block["currency_code"] = clean_text(block["currency_code"]).str.upper().replace("", "NON RENSEIGNEE")
        block[balance_column] = numeric_column(block, balance_column)
        if account_column and account_column in block.columns:
            account_values = clean_identifier(block[account_column])
            account_count = lambda values: int(clean_identifier(values).replace("", pd.NA).nunique())
            account_source = account_column
        else:
            block["__account_row"] = np.arange(len(block))
            account_count = "size"
            account_source = "__account_row"
        aggregation: dict[str, tuple[str, object]] = {
            "solde_reference": (balance_column, "sum"),
            "nombre_comptes_reference": (account_source, account_count),
        }
        reference = block.groupby("currency_code", as_index=False, dropna=False).agg(**aggregation)
        reference["famille_position"] = family
        reference["source_solde_reference"] = source_label
        reference_blocks.append(reference)

    reference_block(
        prepared.current_savings,
        family="Epargne courante",
        source_label="Epargne courante (Current Savings)",
        balance_column="balance",
    )
    reference_block(
        prepared.fixed_savings,
        family="DAT",
        source_label="DAT (Fixed Savings)",
        balance_column="balance",
    )
    reference_block(
        prepared.loans,
        family="Credit",
        source_label="Credits (Loans)",
        balance_column="loan_balance",
        account_column="loan_id",
    )
    reference = concat_frames_stable(reference_blocks)
    if observed.empty and reference.empty:
        return pd.DataFrame(columns=position_columns)
    if observed.empty:
        positions = reference.copy()
        positions["source_observation"] = pd.NA
        positions["solde_transactions_observe"] = np.nan
        positions["date_derniere_ecriture"] = pd.NaT
        positions["nombre_comptes_observes"] = 0
        positions["references_ambigues"] = 0
    elif reference.empty:
        positions = observed.copy()
        positions["source_solde_reference"] = pd.NA
        positions["solde_reference"] = np.nan
        positions["nombre_comptes_reference"] = 0
    else:
        positions = observed.merge(
            reference,
            on=["currency_code", "famille_position"],
            how="outer",
        )
    positions["customer_id"] = customer_key
    for column in ["nombre_comptes_observes", "references_ambigues", "nombre_comptes_reference"]:
        if column not in positions.columns:
            positions[column] = 0
        positions[column] = pd.to_numeric(positions[column], errors="coerce").fillna(0).astype(int)
    positions["ecart_reference"] = np.where(
        positions["solde_transactions_observe"].notna() & positions["solde_reference"].notna(),
        positions["solde_transactions_observe"] - positions["solde_reference"],
        np.nan,
    )

    def position_status(row: pd.Series) -> str:
        observed_value = row.get("solde_transactions_observe")
        reference_value = row.get("solde_reference")
        if pd.isna(observed_value):
            return "Non observe dans Transactions"
        if pd.isna(reference_value):
            return "Solde observe uniquement - fichier de reference absent"
        if not comparison_allowed:
            return "Non comparable - derniere operation hors perimetre"
        tolerance = max(0.01, max(abs(float(observed_value)), abs(float(reference_value))) * 1e-6)
        return "Conforme" if abs(float(observed_value) - float(reference_value)) <= tolerance else "Ecart a expliquer"

    positions["statut_rapprochement_solde"] = positions.apply(position_status, axis=1)
    positions["source_observation"] = positions.get("source_observation", pd.Series(pd.NA, index=positions.index)).fillna(
        "Transactions - aucune ecriture observee"
    )
    positions["source_solde_reference"] = positions.get(
        "source_solde_reference", pd.Series(pd.NA, index=positions.index)
    ).fillna("Fichier de reference non charge")
    return positions[position_columns].sort_values(["currency_code", "famille_position"]).reset_index(drop=True)


def _build_customer_behavior(events: pd.DataFrame) -> pd.DataFrame:
    columns = [
        "currency_code", "nombre_operations", "jours_actifs", "premiere_operation", "derniere_operation",
        "operations_par_jour_actif", "montant_moyen", "montant_median", "plus_forte_operation",
        "jour_semaine_frequent", "heure_frequente", "type_operation_frequent",
        "intervalle_median_heures", "plus_longue_inactivite_jours",
    ]
    if not isinstance(events, pd.DataFrame) or events.empty:
        return pd.DataFrame(columns=columns)
    french_weekdays = {
        0: "Lundi", 1: "Mardi", 2: "Mercredi", 3: "Jeudi",
        4: "Vendredi", 5: "Samedi", 6: "Dimanche",
    }
    rows: list[dict[str, object]] = []
    for currency, group in events.groupby("currency_code", sort=True, dropna=False):
        group = group.sort_values("created_at").copy()
        dates = pd.to_datetime(group["created_at"], errors="coerce").dropna()
        amounts = pd.to_numeric(group["montant_operation"], errors="coerce").dropna()
        active_days = int(dates.dt.date.nunique()) if not dates.empty else 0
        intervals = dates.diff().dropna().dt.total_seconds().div(3600)
        weekday_counts = dates.dt.dayofweek.value_counts()
        hour_counts = dates.dt.hour.value_counts()
        type_counts = clean_text(group["type_operation"]).replace("", pd.NA).dropna().value_counts()
        rows.append(
            {
                "currency_code": currency,
                "nombre_operations": int(len(group)),
                "jours_actifs": active_days,
                "premiere_operation": dates.min() if not dates.empty else pd.NaT,
                "derniere_operation": dates.max() if not dates.empty else pd.NaT,
                "operations_par_jour_actif": len(group) / active_days if active_days else np.nan,
                "montant_moyen": float(amounts.mean()) if not amounts.empty else np.nan,
                "montant_median": float(amounts.median()) if not amounts.empty else np.nan,
                "plus_forte_operation": float(amounts.max()) if not amounts.empty else np.nan,
                "jour_semaine_frequent": french_weekdays.get(int(weekday_counts.index[0]), "-") if not weekday_counts.empty else "-",
                "heure_frequente": f"{int(hour_counts.index[0]):02d}h" if not hour_counts.empty else "-",
                "type_operation_frequent": str(type_counts.index[0]) if not type_counts.empty else "-",
                "intervalle_median_heures": float(intervals.median()) if not intervals.empty else np.nan,
                "plus_longue_inactivite_jours": float(intervals.max() / 24) if not intervals.empty else np.nan,
            }
        )
    return pd.DataFrame(rows, columns=columns)


def build_customer_matured_dat_interest_entries(
    fixed_savings: pd.DataFrame | None,
    transactions: pd.DataFrame | None,
    customer_id: object,
    *,
    as_of_date: object | None = None,
    date_start: object | None = None,
    date_end: object | None = None,
    currency: object | None = None,
    reference_query: object = "",
    annual_interest_rate_pct: float = DEFAULT_DAT_ANNUAL_INTEREST_RATE_PCT,
) -> pd.DataFrame:
    """Restitue les interets constates des DAT echus sans modifier le solde M-PESA.

    ``interest_earned`` provient de la position ``Savings Account``. Une ligne
    n'est retenue que si le DAT est arrive a echeance, porte un interet positif
    et presente un statut de denouement. La presence d'une ecriture de sortie
    portant le meme ``savings_id`` sert uniquement a qualifier la tracabilite.
    """
    empty = pd.DataFrame(columns=CUSTOMER_DAT_INTEREST_COLUMNS)
    if not isinstance(fixed_savings, pd.DataFrame) or fixed_savings.empty:
        return empty
    if "customer_id" not in fixed_savings.columns:
        return empty

    customer_key = str(customer_id).strip()
    frame = fixed_savings.loc[
        clean_identifier(fixed_savings["customer_id"]).eq(customer_key)
    ].copy()
    if frame.empty:
        return empty

    for column in [
        "savings_id",
        "msisdn",
        "msisdn1",
        "currency_code",
        "product_name",
        "status",
        "balance",
        "date_approved",
        "maturity_date",
        "interest_earned",
        "voda_interest",
    ]:
        if column not in frame.columns:
            frame[column] = pd.NA
    frame["savings_id"] = clean_identifier(frame["savings_id"])
    frame["customer_id"] = clean_identifier(frame["customer_id"])
    frame["currency_code"] = clean_text(frame["currency_code"]).str.upper()
    frame["msisdn"] = normalize_phone(frame["msisdn"].where(frame["msisdn"].notna(), frame["msisdn1"]))
    frame["date_approved"] = pd.to_datetime(frame["date_approved"], errors="coerce")
    frame["maturity_date"] = pd.to_datetime(frame["maturity_date"], errors="coerce")
    frame["balance"] = pd.to_numeric(frame["balance"], errors="coerce").fillna(0.0)
    frame["interest_earned"] = pd.to_numeric(frame["interest_earned"], errors="coerce").fillna(0.0)
    frame["voda_interest"] = pd.to_numeric(frame["voda_interest"], errors="coerce").fillna(0.0)

    transaction_dates = pd.Series(dtype="datetime64[ns]")
    if isinstance(transactions, pd.DataFrame) and not transactions.empty and "created_at" in transactions.columns:
        transaction_dates = pd.to_datetime(transactions["created_at"], errors="coerce").dropna()
    effective_end = pd.to_datetime(
        date_end if date_end is not None else as_of_date,
        errors="coerce",
    )
    if pd.isna(effective_end):
        effective_end = transaction_dates.max() if not transaction_dates.empty else pd.Timestamp.now()
    if pd.Timestamp(effective_end) == pd.Timestamp(effective_end).normalize():
        effective_end = _timestamp_plus(effective_end, days=1, microseconds=-1)

    normalized_status = frame["status"].apply(normalize_label)
    settled_status = normalized_status.str.contains(
        r"withdraw|mature|closed|clotur|retir",
        regex=True,
        na=False,
    )
    legacy_settled = normalized_status.eq("") & frame["balance"].le(0)
    frame = frame.loc[
        frame["maturity_date"].notna()
        & frame["maturity_date"].le(effective_end)
        & frame["interest_earned"].gt(0)
        & (settled_status | legacy_settled)
    ].copy()
    if frame.empty:
        return empty

    start = pd.to_datetime(date_start, errors="coerce") if date_start is not None else pd.NaT
    if pd.notna(start):
        frame = frame.loc[frame["maturity_date"].ge(start)].copy()
    end = pd.to_datetime(date_end, errors="coerce") if date_end is not None else pd.NaT
    if pd.notna(end):
        if pd.Timestamp(end) == pd.Timestamp(end).normalize():
            end = _timestamp_plus(end, days=1, microseconds=-1)
        frame = frame.loc[frame["maturity_date"].le(end)].copy()
    currency_text = str(currency).strip().upper() if currency is not None else ""
    if currency_text and currency_text not in {"TOUTES", "ALL"}:
        frame = frame.loc[frame["currency_code"].eq(currency_text)].copy()
    if frame.empty:
        return empty

    transaction_summary = pd.DataFrame(
        columns=[
            "savings_id",
            "capital_place",
            "reference_transaction_turbo",
            "date_ecriture_turbo",
        ]
    )
    if isinstance(transactions, pd.DataFrame) and not transactions.empty:
        if "customer_id" in transactions.columns:
            tx = transactions.loc[
                clean_identifier(transactions["customer_id"]).eq(customer_key)
            ].copy()
        else:
            tx = pd.DataFrame()
        for column in [
            "customer_id",
            "currency_code",
            "account_type",
            "reference_id",
            "ref_no",
            "description",
            "created_at",
            "dr",
            "cr",
        ]:
            if column not in tx.columns:
                tx[column] = pd.NA
        tx["customer_id"] = clean_identifier(tx["customer_id"])
        tx["currency_code"] = clean_text(tx["currency_code"]).str.upper()
        tx["account_type"] = clean_text(tx["account_type"]).str.upper()
        tx["reference_id"] = clean_identifier(tx["reference_id"])
        tx["ref_no"] = clean_identifier(tx["ref_no"])
        tx["created_at"] = pd.to_datetime(tx["created_at"], errors="coerce")
        tx["dr"] = pd.to_numeric(tx["dr"], errors="coerce").fillna(0.0)
        tx["cr"] = pd.to_numeric(tx["cr"], errors="coerce").fillna(0.0)
        savings_ids = set(frame["savings_id"].loc[frame["savings_id"].ne("")].tolist())
        fixed_tx = tx.loc[
            tx["customer_id"].eq(customer_key)
            & tx["account_type"].eq("FIXED SAVINGS")
            & tx["reference_id"].isin(savings_ids)
            & (tx["created_at"].isna() | tx["created_at"].le(effective_end))
        ].copy()
        if not fixed_tx.empty:
            capital = (
                fixed_tx.groupby("reference_id", as_index=False, dropna=False)["cr"]
                .sum()
                .rename(columns={"reference_id": "savings_id", "cr": "capital_place"})
            )
            settlement_description = fixed_tx["description"].apply(normalize_label)
            settlement = fixed_tx.loc[
                fixed_tx["dr"].gt(0)
                & settlement_description.str.contains(
                    r"retrait|withdraw|remboursement.*compte|fixed savings",
                    regex=True,
                    na=False,
                )
            ].copy()
            if not settlement.empty:
                settlement["reference_transaction_turbo"] = settlement["ref_no"].where(
                    settlement["ref_no"].ne(""), settlement["reference_id"]
                )
                traced = settlement.groupby("reference_id", as_index=False, dropna=False).agg(
                    reference_transaction_turbo=("reference_transaction_turbo", concat_unique),
                    date_ecriture_turbo=("created_at", "max"),
                ).rename(columns={"reference_id": "savings_id"})
                transaction_summary = capital.merge(traced, on="savings_id", how="left")
            else:
                transaction_summary = capital
                transaction_summary["reference_transaction_turbo"] = ""
                transaction_summary["date_ecriture_turbo"] = pd.NaT

    frame = frame.merge(transaction_summary, on="savings_id", how="left")
    frame["capital_place"] = pd.to_numeric(frame["capital_place"], errors="coerce")
    frame.loc[frame["capital_place"].le(0), "capital_place"] = np.nan
    frame["taux_interet_annuel_pct"] = float(annual_interest_rate_pct)
    frame["interet_client_constate"] = frame["interest_earned"]
    frame["montant_echeance_client"] = frame["capital_place"] + frame["interet_client_constate"]
    frame["reference_transaction_turbo"] = clean_text(
        frame.get("reference_transaction_turbo", pd.Series("", index=frame.index))
    )
    frame["date_ecriture_turbo"] = pd.to_datetime(
        frame.get("date_ecriture_turbo", pd.Series(pd.NaT, index=frame.index)),
        errors="coerce",
    )
    traced = frame["date_ecriture_turbo"].notna()
    frame["statut_tracabilite"] = np.where(
        traced,
        "Comptabilise et trace dans Transactions",
        "Constate dans Savings Account - ecriture detaillee absente",
    )
    frame["source_interet"] = "Savings Account - interest_earned"
    frame["impact_solde_mpesa"] = "Hors solde M-PESA - versement en epargne courante"

    query = str(reference_query).strip()
    if query:
        query_mask = pd.Series(False, index=frame.index)
        for column in ["savings_id", "reference_transaction_turbo"]:
            query_mask |= frame[column].astype("string").str.contains(
                query, case=False, regex=False, na=False
            )
        frame = frame.loc[query_mask].copy()
    if frame.empty:
        return empty
    return (
        frame[CUSTOMER_DAT_INTEREST_COLUMNS]
        .sort_values(["maturity_date", "currency_code", "savings_id"])
        .reset_index(drop=True)
    )


def build_customer_active_dat_positions(
    fixed_savings: pd.DataFrame | None,
    transactions: pd.DataFrame | None,
    customer_id: object,
    *,
    currency: object | None = None,
    annual_interest_rate_pct: float = DEFAULT_DAT_ANNUAL_INTEREST_RATE_PCT,
) -> pd.DataFrame:
    """Construit la position courante des DAT positifs d'un client depuis la Solution Numérique.

    La date de situation vient d'abord de ``Savings Account`` puis, à défaut,
    de la dernière transaction du client. G2 n'intervient ni dans le
    périmètre, ni dans les montants, ni dans l'estimation des intérêts.
    """
    empty = pd.DataFrame(columns=CUSTOMER_ACTIVE_DAT_COLUMNS)
    if not isinstance(fixed_savings, pd.DataFrame) or fixed_savings.empty:
        return empty
    if "customer_id" not in fixed_savings.columns:
        return empty

    customer_key = clean_identifier(pd.Series([customer_id])).iloc[0]
    customer_dat = fixed_savings.loc[
        clean_identifier(fixed_savings["customer_id"]).eq(customer_key)
    ].copy()
    if customer_dat.empty:
        return empty

    snapshot_candidates: list[pd.Series] = []
    for column in ["updated_at", "date_locked"]:
        if column in customer_dat.columns:
            values = pd.to_datetime(customer_dat[column], errors="coerce").dropna()
            if not values.empty:
                snapshot_candidates.append(values)
                break
    if (
        not snapshot_candidates
        and isinstance(transactions, pd.DataFrame)
        and not transactions.empty
        and {"customer_id", "created_at"}.issubset(transactions.columns)
    ):
        tx_dates = pd.to_datetime(
            transactions.loc[
                clean_identifier(transactions["customer_id"]).eq(customer_key),
                "created_at",
            ],
            errors="coerce",
        ).dropna()
        if not tx_dates.empty:
            snapshot_candidates.append(tx_dates)
    if not snapshot_candidates:
        for column in ["created_at", "date_approved"]:
            if column in customer_dat.columns:
                values = pd.to_datetime(customer_dat[column], errors="coerce").dropna()
                if not values.empty:
                    snapshot_candidates.append(values)
                    break
    situation_date = (
        pd.Timestamp(pd.concat(snapshot_candidates, ignore_index=True).max()).normalize()
        if snapshot_candidates
        else pd.Timestamp.now().normalize()
    )

    maturity = build_mpesa_dat_maturity_analysis(
        customer_dat,
        as_of_date=situation_date,
        annual_interest_rate_pct=annual_interest_rate_pct,
        preparation_horizon_days=DEFAULT_DAT_REPAYMENT_PREPARATION_HORIZON_DAYS,
    )
    detail = maturity.get("detail", pd.DataFrame()).copy()
    if detail.empty:
        return empty

    currency_text = str(currency).strip().upper() if currency is not None else ""
    if currency_text and currency_text not in {"TOUTES", "ALL"}:
        detail = detail.loc[detail["currency_code"].eq(currency_text)].copy()
    if detail.empty:
        return empty

    days = pd.to_numeric(detail["jours_avant_echeance"], errors="coerce")
    detail["situation_dat_client"] = np.select(
        [
            days.isna(),
            days.lt(0),
            days.eq(0),
            days.le(DEFAULT_DAT_REPAYMENT_PREPARATION_HORIZON_DAYS),
        ],
        [
            "Date d'échéance à compléter",
            "Échu à rembourser",
            "Échéance aujourd'hui",
            "Échéance proche",
        ],
        default="En cours",
    )
    detail["date_situation"] = situation_date
    detail["savings_id"] = clean_identifier(detail["savings_id"])
    detail["customer_id"] = clean_identifier(detail["customer_id"])
    detail["msisdn"] = normalize_phone(detail["msisdn"])
    detail["balance"] = pd.to_numeric(detail["balance"], errors="coerce")
    detail["interet_estime_echeance"] = pd.to_numeric(
        detail["interet_estime_echeance"], errors="coerce"
    )
    detail["capital_plus_interet_estime"] = pd.to_numeric(
        detail["capital_plus_interet_estime"], errors="coerce"
    )
    detail["__ordre_situation"] = np.select(
        [days.lt(0), days.eq(0), days.le(DEFAULT_DAT_REPAYMENT_PREPARATION_HORIZON_DAYS)],
        [0, 1, 2],
        default=3,
    )
    return (
        detail.sort_values(
            ["currency_code", "__ordre_situation", "maturity_date", "savings_id"],
            na_position="last",
        )[CUSTOMER_ACTIVE_DAT_COLUMNS]
        .reset_index(drop=True)
    )


def build_customer_statement_elements(
    events: pd.DataFrame | None,
    dat_interest_entries: pd.DataFrame | None = None,
) -> dict[str, pd.DataFrame]:
    """Construit les sept familles d'operations attendues dans l'extrait client.

    Les mouvements M-PESA, les remboursements et les retours de capital DAT
    viennent exclusivement de Transactions Turbo. Les interets DAT constates
    viennent de ``Savings Account.interest_earned`` et restent hors du solde
    M-PESA afin de ne pas transformer une position Turbo en ecriture inventee.
    """
    detail_parts: list[pd.DataFrame] = []
    event_frame = events.copy() if isinstance(events, pd.DataFrame) else pd.DataFrame()
    if not event_frame.empty:
        for column in [
            "created_at",
            "customer_id",
            "currency_code",
            "event_reference",
            "type_operation",
            "montant_operation",
            "remboursement_compte_ouvert",
            "remboursement_mpesa",
            "origine_remboursement_observee",
        ]:
            if column not in event_frame.columns:
                event_frame[column] = pd.NA
        event_frame["created_at"] = pd.to_datetime(event_frame["created_at"], errors="coerce")
        event_frame["currency_code"] = clean_text(event_frame["currency_code"]).str.upper()
        event_frame["montant_operation"] = pd.to_numeric(
            event_frame["montant_operation"], errors="coerce"
        ).fillna(0.0)
        event_frame["remboursement_compte_ouvert"] = pd.to_numeric(
            event_frame["remboursement_compte_ouvert"], errors="coerce"
        ).fillna(0.0)
        event_frame["remboursement_mpesa"] = pd.to_numeric(
            event_frame["remboursement_mpesa"], errors="coerce"
        ).fillna(0.0)

        def append_events(
            mask: pd.Series,
            *,
            label: str,
            origin: str,
            impact: str,
            amount_column: str = "montant_operation",
        ) -> None:
            selected = event_frame.loc[mask.fillna(False)].copy()
            if selected.empty:
                return
            selected["date_operation"] = selected["created_at"]
            selected["type_element_extrait"] = label
            selected["reference_turbo"] = clean_text(selected["event_reference"])
            selected["montant_observe"] = pd.to_numeric(
                selected[amount_column], errors="coerce"
            ).fillna(0.0)
            selected["origine_operation"] = origin
            selected["source_turbo"] = "Transactions"
            selected["impact_solde_mpesa"] = impact
            detail_parts.append(selected[CUSTOMER_STATEMENT_ELEMENT_COLUMNS])

        operation_type = clean_text(event_frame["type_operation"])
        append_events(
            operation_type.eq("Sortie M-PESA_Turbo vers epargne"),
            label="Depot normal",
            origin="Compte M-PESA",
            impact="Entree Bisou Bisou - compte 1441",
        )
        append_events(
            operation_type.eq("Sortie M-PESA_Turbo vers DAT"),
            label="Dépôt à terme (DAT)",
            origin="Compte M-PESA vers DAT",
            impact="Entree Bisou Bisou - capital bloque en DAT",
        )
        append_events(
            operation_type.eq("Entree M-PESA_Turbo depuis epargne"),
            label="Retrait",
            origin="Compte ouvert",
            impact="Sortie Bisou Bisou - compte 15558",
        )
        repayment = operation_type.isin(
            ["Remboursement de credit", "Remboursement avec penalite"]
        )
        from_open_account = repayment & event_frame["remboursement_compte_ouvert"].gt(0)
        append_events(
            from_open_account,
            label="Remboursement d'un credit depuis le compte ouvert",
            origin="Compte ouvert",
            impact="Entree Bisou Bisou - remboursement du credit",
            amount_column="remboursement_compte_ouvert",
        )
        from_mpesa = (
            repayment
            & ~from_open_account
            & event_frame["remboursement_mpesa"].gt(0)
        )
        append_events(
            from_mpesa,
            label="Remboursement d'un credit depuis le compte M-PESA",
            origin="Compte M-PESA",
            impact="Entree Bisou Bisou - compte 1441",
            amount_column="remboursement_mpesa",
        )
        append_events(
            operation_type.eq("Transfert DAT vers epargne courante"),
            label="Retour du capital mis en DAT",
            origin="DAT vers compte ouvert",
            impact="Hors solde M-PESA - transfert interne",
        )

    interest_frame = (
        dat_interest_entries.copy()
        if isinstance(dat_interest_entries, pd.DataFrame)
        else pd.DataFrame()
    )
    if not interest_frame.empty:
        for column in [
            "maturity_date",
            "date_ecriture_turbo",
            "customer_id",
            "currency_code",
            "savings_id",
            "reference_transaction_turbo",
            "interet_client_constate",
        ]:
            if column not in interest_frame.columns:
                interest_frame[column] = pd.NA
        interest_frame["date_operation"] = pd.to_datetime(
            interest_frame["date_ecriture_turbo"], errors="coerce"
        ).where(
            pd.to_datetime(interest_frame["date_ecriture_turbo"], errors="coerce").notna(),
            pd.to_datetime(interest_frame["maturity_date"], errors="coerce"),
        )
        interest_frame["currency_code"] = clean_text(
            interest_frame["currency_code"]
        ).str.upper()
        interest_frame["type_element_extrait"] = (
            "Entree des interets du capital mis en DAT"
        )
        interest_frame["reference_turbo"] = clean_text(
            interest_frame["reference_transaction_turbo"]
        ).where(
            clean_text(interest_frame["reference_transaction_turbo"]).ne(""),
            clean_text(interest_frame["savings_id"]),
        )
        interest_frame["montant_observe"] = pd.to_numeric(
            interest_frame["interet_client_constate"], errors="coerce"
        ).fillna(0.0)
        interest_frame["origine_operation"] = "DAT"
        interest_frame["source_turbo"] = "Savings Account - interest_earned"
        interest_frame["impact_solde_mpesa"] = (
            "Hors solde M-PESA - entree du compte ouvert"
        )
        detail_parts.append(interest_frame[CUSTOMER_STATEMENT_ELEMENT_COLUMNS])

    detail = (
        pd.concat(detail_parts, ignore_index=True, sort=False)
        if detail_parts
        else pd.DataFrame(columns=CUSTOMER_STATEMENT_ELEMENT_COLUMNS)
    )
    if not detail.empty:
        detail["date_operation"] = pd.to_datetime(detail["date_operation"], errors="coerce")
        detail["montant_observe"] = pd.to_numeric(
            detail["montant_observe"], errors="coerce"
        ).fillna(0.0)
        detail = detail.sort_values(
            ["date_operation", "currency_code", "type_element_extrait"],
            na_position="last",
        ).reset_index(drop=True)

    currencies = sorted(
        value
        for value in clean_text(
            detail.get("currency_code", pd.Series(dtype="string"))
        ).unique()
        if value
    )
    summary_rows: list[dict[str, object]] = []
    source_by_label = {
        "Depot normal": "Transactions",
        "Dépôt à terme (DAT)": "Transactions",
        "Retrait": "Transactions",
        "Remboursement d'un credit depuis le compte M-PESA": "Transactions",
        "Remboursement d'un credit depuis le compte ouvert": "Transactions",
        "Retour du capital mis en DAT": "Transactions",
        "Entree des interets du capital mis en DAT": "Savings Account",
    }
    for currency_code in currencies:
        currency_detail = detail.loc[detail["currency_code"].eq(currency_code)]
        for label in CUSTOMER_STATEMENT_ELEMENT_LABELS:
            rows = currency_detail.loc[
                currency_detail["type_element_extrait"].eq(label)
            ]
            summary_rows.append(
                {
                    "currency_code": currency_code,
                    "type_element_extrait": label,
                    "nombre_operations": int(len(rows)),
                    "montant_total_observe": float(rows["montant_observe"].sum()),
                    "source_turbo": source_by_label[label],
                    "statut_periode": (
                        "Present dans la periode" if not rows.empty else "Aucun mouvement"
                    ),
                }
            )
    summary = pd.DataFrame(
        summary_rows,
        columns=[
            "currency_code",
            "type_element_extrait",
            "nombre_operations",
            "montant_total_observe",
            "source_turbo",
            "statut_periode",
        ],
    )
    return {"detail": detail, "synthese": summary}


def _enrich_customer_dat_return_dates(
    internal_returns: pd.DataFrame,
    transaction_lines: pd.DataFrame,
    fixed_savings: pd.DataFrame,
    *,
    customer_id: object,
) -> pd.DataFrame:
    """Ajoute le cycle de vie du DAT aux retours de capital observés.

    La référence du DAT est l'identifiant porté par la ligne ``FIXED SAVINGS``
    de l'événement de retour. La date de création vient d'abord du compte
    ``Savings Account`` correspondant, puis du dépôt bloqué Turbo portant la
    même référence. Un repli sur Savings Account n'est accepté que lorsqu'un
    seul DAT du client et de la devise peut correspondre.
    """
    result = (
        internal_returns.copy()
        if isinstance(internal_returns, pd.DataFrame)
        else pd.DataFrame()
    )
    result["date_creation_dat"] = pd.NaT
    result["date_fin_dat"] = pd.to_datetime(
        result.get("created_at", pd.Series(pd.NaT, index=result.index)),
        errors="coerce",
    )
    result["reference_dat"] = ""
    if result.empty:
        return result

    lines = (
        transaction_lines.copy()
        if isinstance(transaction_lines, pd.DataFrame)
        else pd.DataFrame()
    )
    if not lines.empty:
        lines["created_at"] = pd.to_datetime(
            lines.get("created_at", pd.Series(pd.NaT, index=lines.index)),
            errors="coerce",
        )
        lines["account_type"] = clean_text(
            lines.get("account_type", pd.Series("", index=lines.index))
        ).str.upper()
        lines["reference_id"] = clean_identifier(
            lines.get("reference_id", pd.Series("", index=lines.index))
        )

    savings = (
        fixed_savings.copy()
        if isinstance(fixed_savings, pd.DataFrame)
        else pd.DataFrame()
    )
    if not savings.empty:
        if "customer_id" in savings.columns:
            savings = savings.loc[
                clean_identifier(savings["customer_id"]).eq(str(customer_id).strip())
            ].copy()
        savings["currency_code"] = clean_text(
            savings.get("currency_code", pd.Series("", index=savings.index))
        ).str.upper()
        reference_columns = [
            column
            for column in ["savings_id", "id"]
            if column in savings.columns
        ]
        for column in reference_columns:
            savings[column] = clean_identifier(savings[column])

    def first_savings_creation(frame: pd.DataFrame) -> pd.Timestamp | pd.NaT:
        for column in ["created_at", "date_approved", "date_activated"]:
            if column not in frame.columns:
                continue
            values = pd.to_datetime(frame[column], errors="coerce").dropna()
            if not values.empty:
                return pd.Timestamp(values.min())
        return pd.NaT

    for index, return_row in result.iterrows():
        finish = pd.to_datetime(return_row.get("created_at"), errors="coerce")
        currency_code = str(return_row.get("currency_code", "")).strip().upper()
        event_key = str(return_row.get("event_key", "")).strip()
        event_lines = lines
        if not lines.empty and event_key and "event_key" in lines.columns:
            event_lines = lines.loc[lines["event_key"].astype(str).eq(event_key)].copy()
        fixed_event_lines = (
            event_lines.loc[event_lines["account_type"].eq("FIXED SAVINGS")].copy()
            if not event_lines.empty and "account_type" in event_lines.columns
            else pd.DataFrame()
        )
        dat_references = (
            fixed_event_lines["reference_id"].replace("", pd.NA).dropna().astype(str).unique().tolist()
            if not fixed_event_lines.empty and "reference_id" in fixed_event_lines.columns
            else []
        )
        result.at[index, "reference_dat"] = " | ".join(dat_references)

        creation = pd.NaT
        scoped_savings = savings
        if not scoped_savings.empty and currency_code:
            scoped_savings = scoped_savings.loc[
                scoped_savings["currency_code"].eq(currency_code)
            ].copy()
        if not scoped_savings.empty and dat_references:
            exact_savings_mask = pd.Series(False, index=scoped_savings.index)
            for column in ["savings_id", "id"]:
                if column in scoped_savings.columns:
                    exact_savings_mask |= scoped_savings[column].isin(dat_references)
            exact_savings = scoped_savings.loc[exact_savings_mask].copy()
            if not exact_savings.empty:
                creation = first_savings_creation(exact_savings)

        if pd.isna(creation) and not lines.empty and dat_references:
            prior_fixed = lines.loc[
                lines["account_type"].eq("FIXED SAVINGS")
                & lines["reference_id"].isin(dat_references)
            ].copy()
            if pd.notna(finish):
                prior_fixed = prior_fixed.loc[prior_fixed["created_at"].le(finish)].copy()
            deposit_component = pd.to_numeric(
                prior_fixed.get(
                    "depot_dat_compte",
                    pd.Series(0.0, index=prior_fixed.index),
                ),
                errors="coerce",
            ).fillna(0.0)
            credit_amount = pd.to_numeric(
                prior_fixed.get("cr", pd.Series(0.0, index=prior_fixed.index)),
                errors="coerce",
            ).fillna(0.0)
            descriptions = clean_text(
                prior_fixed.get("description", pd.Series("", index=prior_fixed.index))
            ).map(normalize_label)
            prior_fixed = prior_fixed.loc[
                deposit_component.gt(0)
                | (
                    credit_amount.gt(0)
                    & descriptions.str.contains("depot bloque", na=False)
                )
            ].copy()
            prior_dates = pd.to_datetime(
                prior_fixed.get("created_at", pd.Series(pd.NaT, index=prior_fixed.index)),
                errors="coerce",
            ).dropna()
            if not prior_dates.empty:
                creation = pd.Timestamp(prior_dates.min())

        if pd.isna(creation) and len(scoped_savings) == 1:
            creation = first_savings_creation(scoped_savings)

        result.at[index, "date_creation_dat"] = creation

    result["date_creation_dat"] = pd.to_datetime(
        result["date_creation_dat"], errors="coerce"
    )
    result["date_fin_dat"] = pd.to_datetime(result["date_fin_dat"], errors="coerce")
    return result


UPCOMING_REPAYMENT_COLUMNS = [
    "customer_id",
    "loan_id",
    "due_date",
    "currency_code",
    "loan_amount",
    "loan_balance",
    "outstanding_principle",
    "outstanding_interest",
    "outstanding_setup_fees",
    "outstanding_penalty_fees",
    "montant_a_rembourser",
    "status_name",
]


def build_customer_upcoming_repayments(
    loans: pd.DataFrame,
    customer_id: object,
    *,
    date_start: object | None = None,
    date_end: object | None = None,
    currency: object | None = None,
) -> pd.DataFrame:
    """Liste les prochaines echeances de credit du client sur la periode."""
    result = pd.DataFrame(columns=UPCOMING_REPAYMENT_COLUMNS)
    if not isinstance(loans, pd.DataFrame) or loans.empty or "customer_id" not in loans.columns:
        return result
    frame = loans.copy()
    frame = frame.loc[
        clean_identifier(frame["customer_id"]).eq(str(customer_id).strip())
    ].copy()
    if frame.empty:
        return result
    if "currency_code" not in frame.columns:
        frame["currency_code"] = ""
    frame["currency_code"] = clean_text(frame["currency_code"]).str.upper()
    currency_text = str(currency).strip().upper() if currency is not None else ""
    if currency_text and currency_text not in {"TOUTES", "TOUS", "ALL", "CDF + USD"}:
        frame = frame.loc[frame["currency_code"].eq(currency_text)].copy()
    if frame.empty:
        return result
    if "due_date" not in frame.columns:
        return result
    frame["due_date"] = pd.to_datetime(frame["due_date"], errors="coerce")
    frame = frame.dropna(subset=["due_date"]).copy()
    if frame.empty:
        return result
    start = pd.to_datetime(date_start, errors="coerce") if date_start is not None else pd.NaT
    end = pd.to_datetime(date_end, errors="coerce") if date_end is not None else pd.NaT
    if pd.notna(start):
        frame = frame.loc[frame["due_date"].ge(pd.Timestamp(start))].copy()
    if pd.notna(end):
        end_timestamp = pd.Timestamp(end)
        if end_timestamp == end_timestamp.normalize():
            end_timestamp = _timestamp_plus(end_timestamp, days=1, microseconds=-1)
        frame = frame.loc[frame["due_date"].le(end_timestamp)].copy()
    if frame.empty:
        return result
    for column in [
        "loan_amount",
        "loan_balance",
        "outstanding_principle",
        "outstanding_interest",
        "outstanding_setup_fees",
        "outstanding_penalty_fees",
    ]:
        if column not in frame.columns:
            frame[column] = 0.0
        frame[column] = pd.to_numeric(frame[column], errors="coerce").fillna(0.0)
    frame["montant_a_rembourser"] = frame[
        [
            "outstanding_principle",
            "outstanding_interest",
            "outstanding_setup_fees",
            "outstanding_penalty_fees",
        ]
    ].sum(axis=1)
    frame["montant_a_rembourser"] = frame["montant_a_rembourser"].where(
        frame["montant_a_rembourser"].gt(0),
        frame["loan_balance"],
    )
    for column in ["loan_id", "status_name"]:
        if column not in frame.columns:
            frame[column] = ""
        frame[column] = clean_text(frame[column])
    for column in UPCOMING_REPAYMENT_COLUMNS:
        if column not in frame.columns:
            frame[column] = pd.NA
    return (
        frame[UPCOMING_REPAYMENT_COLUMNS]
        .sort_values(["due_date", "currency_code", "loan_id"])
        .reset_index(drop=True)
    )


def build_customer_transaction_analysis(
    prepared: MpesaPreparedData,
    customer_id: object,
    *,
    currency: object | None = None,
    operation_types: Iterable[object] | None = None,
    date_start: object | None = None,
    date_end: object | None = None,
    reference_query: object = "",
    annual_interest_rate_pct: float = DEFAULT_DAT_ANNUAL_INTEREST_RATE_PCT,
) -> dict[str, pd.DataFrame]:
    """Construit les analyses client disponibles dans Transactions."""
    dat_interest_entries = build_customer_matured_dat_interest_entries(
        prepared.fixed_savings,
        prepared.transactions,
        customer_id,
        date_start=date_start,
        date_end=date_end,
        currency=currency,
        reference_query=reference_query,
        annual_interest_rate_pct=annual_interest_rate_pct,
    )
    upcoming_repayments = build_customer_upcoming_repayments(
        prepared.loans,
        customer_id,
        date_start=date_start,
        date_end=date_end,
        currency=currency,
    )
    statement_elements = build_customer_statement_elements(
        pd.DataFrame(),
        dat_interest_entries,
    )
    empty = {
        "parcours_turbo": pd.DataFrame(),
        "jalons_turbo": pd.DataFrame(),
        "credit_turbo_synthese_client": pd.DataFrame(),
        "credit_turbo_detail_client": pd.DataFrame(),
        "remboursements_turbo_synthese_client": pd.DataFrame(),
        "remboursements_turbo_detail_client": pd.DataFrame(),
        "positions_turbo": pd.DataFrame(),
        "comportement_turbo": pd.DataFrame(),
        "mouvements_internes_turbo": pd.DataFrame(),
        "prochains_remboursements_client": upcoming_repayments,
        "controles_client_turbo": pd.DataFrame(),
        "elements_extrait_client_turbo": statement_elements["detail"],
        "elements_extrait_client_synthese": statement_elements["synthese"],
        "interets_dat_credites_client": dat_interest_entries,
        "dat_en_cours_client": build_customer_active_dat_positions(
            prepared.fixed_savings,
            prepared.transactions,
            customer_id,
            currency=currency,
            annual_interest_rate_pct=annual_interest_rate_pct,
        ),
    }
    events, lines = _build_customer_turbo_events(prepared.transactions, customer_id)
    if events.empty:
        return empty
    full_customer_latest = pd.to_datetime(events["created_at"], errors="coerce").max()
    base = events.copy()
    currency_text = str(currency).strip().upper() if currency is not None else ""
    if currency_text and currency_text not in {"TOUTES", "ALL"}:
        base = base.loc[base["currency_code"].eq(currency_text)].copy()
    start = pd.to_datetime(date_start, errors="coerce") if date_start is not None else pd.NaT
    end = pd.to_datetime(date_end, errors="coerce") if date_end is not None else pd.NaT
    if pd.notna(start):
        base = base.loc[pd.to_datetime(base["created_at"], errors="coerce").ge(start)].copy()
    if pd.notna(end):
        if not hasattr(date_end, "hour"):
            end = _timestamp_plus(end, days=1, microseconds=-1)
        base = base.loc[pd.to_datetime(base["created_at"], errors="coerce").le(end)].copy()
    query = str(reference_query).strip()
    if query:
        reference_mask = pd.Series(False, index=base.index)
        for column in ["event_reference", "ref_no", "reference_ids"]:
            reference_mask |= base[column].astype("string").str.contains(query, case=False, regex=False, na=False)
        base = base.loc[reference_mask].copy()
    if base.empty:
        return empty

    base_event_keys = set(base["event_key"].astype(str))
    base_lines = lines.loc[lines["event_key"].astype(str).isin(base_event_keys)].copy()
    internal = base.loc[base["type_operation"].eq("Transfert DAT vers epargne courante")].copy()
    internal = _enrich_customer_dat_return_dates(
        internal,
        lines,
        prepared.fixed_savings,
        customer_id=customer_id,
    )

    selected_types = [str(value) for value in (operation_types or []) if str(value).strip()]
    scoped = base.loc[base["type_operation"].isin(selected_types)].copy() if selected_types else base.copy()
    element_events = pd.concat([scoped, internal], ignore_index=True, sort=False)
    if "event_key" in element_events.columns:
        element_events = element_events.drop_duplicates("event_key", keep="first")
    statement_elements = build_customer_statement_elements(
        element_events,
        dat_interest_entries,
    )
    if scoped.empty:
        positions = _build_customer_observed_positions(
            prepared,
            base_lines,
            customer_id,
            comparison_allowed=False,
        )
        result = dict(empty)
        result["positions_turbo"] = positions
        result["mouvements_internes_turbo"] = internal
        result["elements_extrait_client_turbo"] = statement_elements["detail"]
        result["elements_extrait_client_synthese"] = statement_elements["synthese"]
        return result

    latest_in_scope = pd.to_datetime(base["created_at"], errors="coerce").max()
    comparison_allowed = (
        not query
        and pd.notna(latest_in_scope)
        and pd.notna(full_customer_latest)
        and pd.Timestamp(latest_in_scope) >= pd.Timestamp(full_customer_latest)
    )
    positions = _build_customer_observed_positions(
        prepared,
        base_lines,
        customer_id,
        comparison_allowed=comparison_allowed,
    )
    behavior = _build_customer_behavior(scoped)

    milestones = (
        scoped.groupby(["currency_code", "type_operation"], as_index=False, dropna=False)
        .agg(
            nombre_operations=("event_key", "nunique"),
            montant_total_observe=("montant_operation", "sum"),
            premiere_operation=("created_at", "min"),
            derniere_operation=("created_at", "max"),
        )
        .sort_values(["currency_code", "premiere_operation", "type_operation"])
        .reset_index(drop=True)
    )
    credit_mask = (
        scoped["type_operation"].isin(["Decaissement de credit", "Remboursement de credit", "Remboursement avec penalite"])
        | scoped[["montant_decaisse_client", "interet_observe", "principal_rembourse", "penalite_observee"]].gt(0).any(axis=1)
    )
    credit_detail = scoped.loc[credit_mask].copy()
    credit_summary = pd.DataFrame()
    repayment_detail = pd.DataFrame()
    repayment_summary = pd.DataFrame()
    if not credit_detail.empty:
        credit_detail["est_decaissement"] = credit_detail["type_operation"].eq("Decaissement de credit")
        credit_detail["est_remboursement"] = credit_detail["type_operation"].isin(
            ["Remboursement de credit", "Remboursement avec penalite"]
        )
        credit_detail["remboursement_avec_penalite"] = credit_detail["penalite_observee"].gt(0)
        credit_detail["remboursement_avec_epargne_dat"] = credit_detail["epargne_dat_remboursement"].gt(0)
        credit_summary = (
            credit_detail.groupby("currency_code", as_index=False, dropna=False)
            .agg(
                nombre_decaissements=("est_decaissement", "sum"),
                montant_decaisse_client=("montant_decaisse_client", "sum"),
                dette_creee_observee=("dette_creee_observee", "sum"),
                interet_observe=("interet_observe", "sum"),
                nombre_remboursements=("est_remboursement", "sum"),
                principal_rembourse=("principal_rembourse", "sum"),
                remboursements_avec_penalite=("remboursement_avec_penalite", "sum"),
                penalite_observee=("penalite_observee", "sum"),
                remboursements_avec_epargne_dat=("remboursement_avec_epargne_dat", "sum"),
                revenu_credit_observe=("revenu_credit_observe", "sum"),
            )
        )
        credit_summary["ratio_interet_decaissement_pct"] = (
            credit_summary["interet_observe"]
            .div(credit_summary["montant_decaisse_client"].replace(0, pd.NA))
            .mul(100)
        )
        repayment_detail = credit_detail.loc[credit_detail["est_remboursement"]].copy()
        if not repayment_detail.empty:
            repayment_detail["montant_paye_observe"] = repayment_detail[
                "remboursement_compte_ouvert"
            ].where(
                repayment_detail["remboursement_compte_ouvert"].gt(0),
                repayment_detail["remboursement_mpesa"].where(
                    repayment_detail["remboursement_mpesa"].gt(0),
                    repayment_detail["montant_operation"],
                ),
            )
            repayment_summary = (
                repayment_detail.groupby(
                    ["customer_id", "currency_code"],
                    as_index=False,
                    dropna=False,
                )
                .agg(
                    nombre_remboursements=("event_key", "nunique"),
                    montant_paye_observe=("montant_paye_observe", "sum"),
                    principal_rembourse=("principal_rembourse", "sum"),
                    interet_observe=("interet_observe", "sum"),
                    penalite_observee=("penalite_observee", "sum"),
                )
            )

    path_columns = [
        "created_at", "currency_code", "event_reference", "ref_no", "type_operation", "sens_metier",
        "montant_operation", "montant_entree_bisou", "montant_sortie_bisou", "mode_remboursement_observe",
        "account_types", "descriptions", "nombre_lignes", "statut_controle_turbo",
    ]
    credit_columns = [
        "created_at", "currency_code", "event_reference", "type_operation", "montant_decaisse_client",
        "dette_creee_observee", "interet_observe", "remboursement_mpesa",
        "remboursement_compte_ouvert", "principal_rembourse",
        "penalite_observee", "epargne_dat_remboursement", "mode_remboursement_observe",
        "origine_remboursement_observee",
        "statut_controle_turbo", "observation_controle_turbo",
    ]
    repayment_columns = [
        "customer_id", "created_at", "event_reference", "ref_no", "currency_code",
        "montant_paye_observe", "principal_rembourse", "interet_observe",
        "penalite_observee", "mode_remboursement_observe",
        "origine_remboursement_observee",
    ]
    control_columns = [
        "created_at", "currency_code", "event_reference", "type_operation", "montant_operation",
        "controle_montant_operation", "detail_controle_montant", "nombre_lignes",
        "lignes_mouvement_nul", "lignes_solde_negatif", "types_comptes_inconnus",
        "total_debit_ecritures", "total_credit_ecritures", "ecart_debit_credit_observe",
        "statut_controle_turbo", "observation_controle_turbo",
    ]
    internal_columns = [
        "created_at", "date_creation_dat", "date_fin_dat", "reference_dat",
        "currency_code", "event_reference", "type_operation", "montant_operation",
        "transfert_dat_sortie", "transfert_epargne_entree", "account_types", "descriptions",
        "statut_controle_turbo", "observation_controle_turbo",
    ]
    return {
        "parcours_turbo": scoped[path_columns].sort_values("created_at").reset_index(drop=True),
        "jalons_turbo": milestones,
        "credit_turbo_synthese_client": credit_summary,
        "credit_turbo_detail_client": credit_detail[credit_columns].sort_values("created_at").reset_index(drop=True),
        "remboursements_turbo_synthese_client": repayment_summary,
        "remboursements_turbo_detail_client": (
            repayment_detail[repayment_columns].sort_values("created_at").reset_index(drop=True)
            if not repayment_detail.empty
            else pd.DataFrame(columns=repayment_columns)
        ),
        "positions_turbo": positions,
        "comportement_turbo": behavior,
        "mouvements_internes_turbo": internal[internal_columns].sort_values("created_at").reset_index(drop=True),
        "prochains_remboursements_client": upcoming_repayments,
        "controles_client_turbo": scoped[control_columns].sort_values("created_at").reset_index(drop=True),
        "elements_extrait_client_turbo": statement_elements["detail"],
        "elements_extrait_client_synthese": statement_elements["synthese"],
        "interets_dat_credites_client": dat_interest_entries,
        "dat_en_cours_client": empty["dat_en_cours_client"],
    }


def build_mpesa_statement(
    prepared: MpesaPreparedData,
    customer_id: str,
    opening_balances: dict[str, float | None] | None = None,
    date_start: object | None = None,
    date_end: object | None = None,
) -> dict[str, Any]:
    opening_balances = opening_balances or {}
    transactions = prepared.transactions
    tx_client = transactions.loc[transactions["customer_id"].eq(str(customer_id))].copy()
    dat_client = filter_customer_frame(prepared.fixed_savings, str(customer_id))
    savings_client = filter_customer_frame(prepared.current_savings, str(customer_id))
    loans_client = filter_customer_frame(prepared.loans, str(customer_id))

    if tx_client.empty:
        raise ValueError(f"Aucune transaction trouvee pour le client {customer_id}.")

    if not dat_client.empty:
        situation_date = pd.to_datetime(transactions["created_at"], errors="coerce").max()
        dat_client["statut_dat"] = np.select(
            [
                numeric_column(dat_client, "balance").le(0),
                dat_client.get("maturity_date", pd.Series(pd.NaT, index=dat_client.index)).notna()
                & dat_client.get("maturity_date", pd.Series(pd.NaT, index=dat_client.index)).lt(situation_date),
            ],
            ["Solde nul", "Echu"],
            default="Actif",
        )

    tx_client["operation_reference"] = tx_client["ref_no"].where(
        ~tx_client["ref_no"].apply(_is_empty_text), tx_client["reference_id"]
    )
    missing_reference = tx_client["operation_reference"].apply(_is_empty_text)
    tx_client.loc[missing_reference, "operation_reference"] = (
        "LIGNE-" + tx_client.loc[missing_reference, "id"].astype("string")
    )
    operation_metadata = (
        tx_client.groupby(
            ["customer_id", "currency_code", "created_at", "operation_reference"],
            as_index=False,
            dropna=False,
        )
        .agg(
            description_turbo=("description", concat_unique),
            account_types_operation=("account_type", concat_unique),
        )
    )

    mpesa = tx_client.loc[tx_client["account_type"].eq("MPESA ACCOUNT")].copy()
    if mpesa.empty:
        raise ValueError(f"Aucun mouvement MPESA ACCOUNT trouve pour le client {customer_id}.")

    statement_aggregations: dict[str, tuple[str, object]] = {
        "telephone": ("msisdn1", concat_unique),
        "debit_mpesa": ("dr", "sum"),
        "credit_mpesa": ("cr", "sum"),
        "references_internes": ("reference_id", concat_unique),
        "descriptions": ("description", concat_unique),
        "account_types": ("account_type", concat_unique),
        "nombre_lignes_comptables": ("id", "count"),
    }
    if "Nom_client" in mpesa.columns:
        statement_aggregations["Nom_client"] = ("Nom_client", concat_unique)
    if "mode_rapprochement_nom_client" in mpesa.columns:
        statement_aggregations["mode_rapprochement_nom_client"] = ("mode_rapprochement_nom_client", concat_unique)
    statement = (
        mpesa.groupby(["customer_id", "currency_code", "created_at", "operation_reference"], as_index=False, dropna=False)
        .agg(**statement_aggregations)
        .sort_values(["currency_code", "created_at", "operation_reference"])
    )
    statement = statement.merge(
        operation_metadata,
        on=["customer_id", "currency_code", "created_at", "operation_reference"],
        how="left",
    )
    open_savings_flows = build_open_savings_operation_flows(tx_client)
    if not open_savings_flows.empty:
        statement = statement.merge(
            open_savings_flows,
            on=["customer_id", "currency_code", "created_at", "operation_reference"],
            how="left",
        )
    else:
        statement["debit_compte_ouvert"] = 0.0
        statement["credit_compte_ouvert"] = 0.0
        statement["description_compte_ouvert"] = ""
        statement["nombre_lignes_compte_ouvert"] = 0
    for column in ["debit_compte_ouvert", "credit_compte_ouvert", "nombre_lignes_compte_ouvert"]:
        statement[column] = pd.to_numeric(
            statement.get(column, pd.Series(0, index=statement.index)),
            errors="coerce",
        ).fillna(0.0)
    statement["description_compte_ouvert"] = clean_text(
        statement.get(
            "description_compte_ouvert",
            pd.Series("", index=statement.index),
        )
    )
    has_turbo_description = ~statement["description_turbo"].apply(_is_empty_text)
    statement["descriptions"] = statement["description_turbo"].where(
        has_turbo_description, statement["descriptions"]
    )
    has_operation_accounts = ~statement["account_types_operation"].apply(_is_empty_text)
    statement["account_types"] = statement["account_types_operation"].where(
        has_operation_accounts, statement["account_types"]
    )
    statement = statement.drop(columns=["account_types_operation"])
    if "Nom_client" not in statement.columns:
        statement["Nom_client"] = pd.NA
    if "mode_rapprochement_nom_client" not in statement.columns:
        statement["mode_rapprochement_nom_client"] = "Nom client non disponible"

    statement["reference_dat_operation"] = statement["references_internes"].apply(lambda value: extract_prefixed_reference(value, "FA"))
    statement["reference_credit_operation"] = statement["references_internes"].apply(lambda value: extract_prefixed_reference(value, "LN"))

    dat_direct = _build_dat_direct(tx_client)
    if not dat_direct.empty:
        statement = statement.merge(dat_direct, on=["currency_code", "created_at"], how="left")
        statement["reference_dat_operation"] = statement["reference_dat_direct"].fillna(statement["reference_dat_operation"])
        statement = statement.drop(columns=["reference_dat_direct"])
    else:
        statement["solde_dat_operation_avant"] = np.nan
        statement["solde_dat_operation_apres"] = np.nan
        statement["variation_dat_operation"] = np.nan

    statement["mouvement_net_mpesa"] = statement["credit_mpesa"] - statement["debit_mpesa"]
    statement["entree_mpesa"] = statement["mouvement_net_mpesa"].clip(lower=0)
    statement["sortie_mpesa"] = (-statement["mouvement_net_mpesa"].clip(upper=0))
    statement["type_operation"] = statement.apply(
        lambda row: classify_mpesa_operation(row["descriptions"], row["account_types"], row["mouvement_net_mpesa"]),
        axis=1,
    )
    loan_disbursement = statement["type_operation"].eq("Decaissement de credit")
    statement["pret_brut_decaisse"] = statement["credit_mpesa"].where(
        loan_disbursement,
        0.0,
    )
    statement["interet_pret_preleve"] = statement["debit_mpesa"].where(
        loan_disbursement,
        0.0,
    )
    statement["net_pret_verse"] = (
        statement["pret_brut_decaisse"] - statement["interet_pret_preleve"]
    ).clip(lower=0.0)
    statement["taux_interet_pret_pct"] = (
        statement["interet_pret_preleve"]
        .div(statement["pret_brut_decaisse"].replace(0, pd.NA))
        .mul(100)
    )
    statement["taux_interet_pret_reference_pct"] = np.where(
        loan_disbursement,
        DEFAULT_LOAN_INTEREST_RATE_PCT,
        np.nan,
    )
    statement["interet_pret_reference_7pct"] = (
        statement["pret_brut_decaisse"] * DEFAULT_LOAN_INTEREST_RATE_PCT / 100
    )
    statement["ecart_interet_pret_vs_7pct"] = (
        statement["interet_pret_preleve"]
        - statement["interet_pret_reference_7pct"]
    ).where(loan_disbursement, 0.0)
    repayment_from_open_account = _customer_internal_savings_repayment_mask(
        statement
    )
    # Position du portefeuille M-PESA du client. Un remboursement prélevé sur
    # le compte ouvert n'affecte pas son solde M-PESA, même si Turbo contient
    # une ligne MPESA ACCOUNT technique dans le même événement.
    statement["mouvement_net_client_mpesa"] = statement["mouvement_net_mpesa"].where(
        ~repayment_from_open_account,
        0.0,
    )
    statement["cumul_net_depuis_debut_fichier"] = statement.groupby("currency_code")["mouvement_net_mpesa"].cumsum()
    statement["cumul_net_client_mpesa"] = statement.groupby("currency_code")[
        "mouvement_net_client_mpesa"
    ].cumsum()
    statement["solde_mpesa_avant"] = np.nan
    statement["solde_mpesa_apres"] = np.nan
    statement["solde_mpesa_disponible"] = False
    statement["solde_client_mpesa_avant"] = np.nan
    statement["solde_client_mpesa_apres"] = np.nan
    statement["solde_client_mpesa_disponible"] = False

    for currency, index in statement.groupby("currency_code").groups.items():
        opening = opening_balances.get(str(currency))
        if opening is None or pd.isna(opening):
            continue
        opening = float(opening)
        cumulative = statement.loc[index, "cumul_net_depuis_debut_fichier"]
        statement.loc[index, "solde_mpesa_apres"] = opening + cumulative
        statement.loc[index, "solde_mpesa_avant"] = statement.loc[index, "solde_mpesa_apres"] - statement.loc[index, "mouvement_net_mpesa"]
        statement.loc[index, "solde_mpesa_disponible"] = True
        client_cumulative = statement.loc[index, "cumul_net_client_mpesa"]
        statement.loc[index, "solde_client_mpesa_apres"] = opening + client_cumulative
        statement.loc[index, "solde_client_mpesa_avant"] = (
            statement.loc[index, "solde_client_mpesa_apres"]
            - statement.loc[index, "mouvement_net_client_mpesa"]
        )
        statement.loc[index, "solde_client_mpesa_disponible"] = True

    dat_final = build_dat_final(prepared.fixed_savings, str(customer_id))
    savings_final = build_savings_final(prepared.current_savings, str(customer_id))
    savings_events = build_account_events(tx_client, "NORMAL SAVINGS")
    dat_events = build_account_events(tx_client, "FIXED SAVINGS")
    statement = add_reconstructed_balance(statement, savings_events, savings_final, "solde_epargne_au_moment")
    statement = add_reconstructed_balance(statement, dat_events, dat_final, "solde_dat_total_au_moment")
    statement["epargne_courante_finale"] = statement["currency_code"].map(lambda currency: float(savings_final.get(currency, 0.0)))
    statement["dat_final_client"] = statement["currency_code"].map(lambda currency: float(dat_final.get(currency, 0.0)))

    statement = enrich_with_loans(statement, prepared.loans)

    if date_start is not None:
        start = pd.to_datetime(date_start, errors="coerce")
        if pd.notna(start):
            statement = statement.loc[statement["created_at"].ge(start)]
    if date_end is not None:
        end = pd.to_datetime(date_end, errors="coerce")
        if pd.notna(end):
            if not hasattr(date_end, "hour"):
                end = _timestamp_plus(end, days=1, microseconds=-1)
            statement = statement.loc[statement["created_at"].le(end)]

    statement["controle_mouvement"] = np.select(
        [
            statement["mouvement_net_mpesa"].eq(0),
            statement["operation_reference"].astype("string").str.startswith("LIGNE-", na=False),
        ],
        ["Mouvement nul a verifier", "Reference absente"],
        default="OK",
    )
    statement = statement.sort_values(["created_at", "currency_code", "operation_reference"]).reset_index(drop=True)

    customer_transaction_analysis = build_customer_transaction_analysis(prepared, str(customer_id))
    summary = build_customer_summary(
        statement,
        dat_client,
        savings_client,
        loans_client,
        str(customer_id),
        positions_turbo=customer_transaction_analysis.get(
            "positions_turbo", pd.DataFrame()
        ),
    )
    diagnostics = build_diagnostics(prepared, str(customer_id), statement)
    g2_dat = build_g2_dat_crosscheck(prepared, str(customer_id))
    client_visible_analysis = dict(customer_transaction_analysis)
    for internal_credit_key in [
        "credit_turbo_synthese_client",
        "credit_turbo_detail_client",
        "positions_turbo",
    ]:
        client_visible_analysis.pop(internal_credit_key, None)
    g2_available = not prepared.g2_transactions.empty
    name_enriched_by_g2 = bool(
        "Nom_client" in statement.columns
        and clean_text(statement["Nom_client"]).ne("").any()
        and g2_available
    )
    return {
        "customer_id": str(customer_id),
        "mode_source_extrait": "Solution Numérique + verification G2" if g2_available else "Solution Numérique seule",
        "controle_g2_disponible": g2_available,
        "nom_client_enrichi_g2": name_enriched_by_g2,
        "extrait": format_statement_columns(statement),
        "synthese": summary,
        "dat_final": dat_client,
        "mouvements_dat": dat_events,
        "mouvements_epargne": savings_events,
        "credits": loans_client,
        "g2_dat": g2_dat,
        "diagnostics": diagnostics,
        **client_visible_analysis,
    }


def enrich_with_loans(statement: pd.DataFrame, loans: pd.DataFrame) -> pd.DataFrame:
    result = statement.copy()
    if loans.empty or "loan_id" not in loans.columns:
        for column in [
            "loan_id",
            "loan_amount",
            "loan_balance",
            "amount_paid",
            "outstanding_principle",
            "outstanding_interest",
            "outstanding_penalty_fees",
            "status_name",
            "due_date",
        ]:
            result[column] = np.nan
        return result
    loan_columns = [
        column
        for column in [
            "loan_id",
            "loan_amount",
            "loan_balance",
            "amount_paid",
            "outstanding_principle",
            "outstanding_interest",
            "outstanding_penalty_fees",
            "status_name",
            "due_date",
        ]
        if column in loans.columns
    ]
    loan_frame = loans[loan_columns].drop_duplicates("loan_id").copy()
    return result.merge(loan_frame, left_on="reference_credit_operation", right_on="loan_id", how="left")


def build_customer_summary(
    statement: pd.DataFrame,
    dat_client: pd.DataFrame,
    savings_client: pd.DataFrame,
    loans_client: pd.DataFrame,
    customer_id: str,
    *,
    positions_turbo: pd.DataFrame | None = None,
) -> pd.DataFrame:
    if statement.empty:
        return pd.DataFrame()
    rows: list[dict[str, object]] = []
    positions = (
        positions_turbo.copy()
        if isinstance(positions_turbo, pd.DataFrame)
        else pd.DataFrame()
    )
    for currency, group in statement.groupby("currency_code", sort=True, dropna=False):
        real_balance = bool(group["solde_mpesa_disponible"].fillna(False).all())
        # La synthèse reprend le mouvement net MPESA de chaque événement, puis
        # inverse son sens pour Bisou Bisou. Un remboursement financé par le
        # compte ouvert est un transfert interne et reste hors des flux externes.
        internal_repayment = _customer_internal_savings_repayment_mask(group)
        business_entries = pd.to_numeric(
            group.get("sortie_mpesa", pd.Series(0.0, index=group.index)),
            errors="coerce",
        ).fillna(0.0).mask(internal_repayment, 0.0)
        business_outputs = pd.to_numeric(
            group.get("entree_mpesa", pd.Series(0.0, index=group.index)),
            errors="coerce",
        ).fillna(0.0).mask(internal_repayment, 0.0)
        business_net = float(business_entries.sum() - business_outputs.sum())
        if real_balance:
            opening_balance = pd.to_numeric(
                group["solde_mpesa_avant"], errors="coerce"
            ).iloc[0]
            closing_balance = (
                float(opening_balance) + business_net
                if pd.notna(opening_balance)
                else np.nan
            )
        else:
            closing_balance = np.nan
        client_balance_available = bool(
            "solde_client_mpesa_disponible" in group.columns
            and group["solde_client_mpesa_disponible"]
            .astype("boolean")
            .fillna(False)
            .all()
        )
        client_closing_balance = (
            pd.to_numeric(group["solde_client_mpesa_apres"], errors="coerce").iloc[-1]
            if client_balance_available
            and "solde_client_mpesa_apres" in group.columns
            else np.nan
        )

        currency_positions = pd.DataFrame()
        if not positions.empty and {"currency_code", "famille_position"}.issubset(
            positions.columns
        ):
            currency_positions = positions.loc[
                clean_text(positions["currency_code"]).str.upper().eq(
                    str(currency).upper()
                )
            ].copy()

        def observed_position(family: str) -> tuple[float, int]:
            family_rows = currency_positions.loc[
                clean_text(currency_positions.get("famille_position", pd.Series("", index=currency_positions.index))).eq(
                    family
                )
            ]
            if family_rows.empty:
                return np.nan, 0
            amount = pd.to_numeric(
                family_rows.get(
                    "solde_transactions_observe",
                    pd.Series(np.nan, index=family_rows.index),
                ),
                errors="coerce",
            ).sum(min_count=1)
            accounts = pd.to_numeric(
                family_rows.get(
                    "nombre_comptes_observes",
                    pd.Series(0, index=family_rows.index),
                ),
                errors="coerce",
            ).fillna(0).sum()
            return (float(amount) if pd.notna(amount) else np.nan, int(accounts))

        current_snapshot = (
            not savings_client.empty
            and "currency_code" in savings_client.columns
            and clean_text(savings_client["currency_code"])
            .str.upper()
            .eq(str(currency).upper())
            .any()
        )
        dat_snapshot = (
            not dat_client.empty
            and "currency_code" in dat_client.columns
            and clean_text(dat_client["currency_code"])
            .str.upper()
            .eq(str(currency).upper())
            .any()
        )
        observed_current, observed_current_accounts = observed_position(
            "Epargne courante"
        )
        observed_dat, observed_dat_accounts = observed_position("DAT")
        current_balance = float(group["epargne_courante_finale"].iloc[-1])
        current_source = "Savings Account"
        if not current_snapshot and pd.notna(observed_current):
            current_balance = observed_current
            current_source = "Transactions - dernière position observée"
        elif not current_snapshot:
            current_source = "Position non disponible"
        dat_balance = float(group["dat_final_client"].iloc[-1])
        dat_source = "Savings Account"
        if not dat_snapshot and pd.notna(observed_dat):
            dat_balance = observed_dat
            dat_source = "Transactions - dernière position observée"
        elif not dat_snapshot:
            dat_source = "Position non disponible"
        loan_balance = 0.0
        loan_count = 0
        if not loans_client.empty and "currency_code" in loans_client.columns:
            loans_currency = loans_client.loc[loans_client["currency_code"].eq(currency)]
            loan_count = int(loans_currency["loan_id"].nunique()) if "loan_id" in loans_currency.columns else len(loans_currency)
            if "loan_balance" in loans_currency.columns:
                loan_balance = float(pd.to_numeric(loans_currency["loan_balance"], errors="coerce").fillna(0).sum())
        rows.append(
            {
                "customer_id": customer_id,
                "Nom_client": concat_unique(group["Nom_client"]) if "Nom_client" in group.columns else "",
                "telephone": concat_unique(group["telephone"]),
                "devise": currency,
                "nombre_operations_mpesa": int(len(group)),
                "premiere_transaction": group["created_at"].min(),
                "derniere_transaction": group["created_at"].max(),
                "total_entrees_mpesa": float(business_entries.sum()),
                "total_sorties_mpesa": float(business_outputs.sum()),
                "mouvement_net": business_net,
                "solde_mpesa_final": closing_balance,
                "solde_mpesa_est_reel": real_balance,
                "solde_mpesa_client_final": (
                    float(client_closing_balance)
                    if pd.notna(client_closing_balance)
                    else np.nan
                ),
                "solde_mpesa_client_est_reel": client_balance_available,
                "source_solde_mpesa_client": (
                    "Solde d'ouverture + mouvements du portefeuille client"
                    if client_balance_available
                    else "Solde d'ouverture non fourni"
                ),
                "epargne_courante_finale": current_balance,
                "source_epargne_courante_finale": current_source,
                "dat_final": dat_balance,
                "source_dat_final": dat_source,
                "nombre_dat": (
                    int(
                        clean_text(dat_client["currency_code"])
                        .str.upper()
                        .eq(str(currency).upper())
                        .sum()
                    )
                    if dat_snapshot
                    else observed_dat_accounts
                ),
                "nombre_comptes_epargne_observes": observed_current_accounts,
                "nombre_credits": loan_count,
                "solde_credit_total": loan_balance,
            }
        )
    return pd.DataFrame(rows)


TRANSACTION_ANOMALY_CONTROL_NAMES = (
    "Lignes sans customer_id",
    "Lignes sans reference_id",
    "Dates invalides",
    "Mouvements dr = 0 et cr = 0",
    "Lignes avec dr > 0 et cr > 0",
    "Soldes bal_before/bal_after negatifs",
    "currency_code vide",
    "account_type vide",
    "Types de comptes a classifier",
    "Doublons exacts",
    "Lignes dans des groupes d'ecritures repetees",
)


def build_transaction_anomalies(
    transactions: pd.DataFrame | None,
    selected_controls: Iterable[str] | None = None,
) -> pd.DataFrame:
    """Retourne les lignes anormales avec un motif explicite par ligne."""
    if not isinstance(transactions, pd.DataFrame):
        return pd.DataFrame(columns=["raison_anomalie"])

    work = transactions.copy()
    if "raison_anomalie" in work.columns:
        work = work.drop(columns=["raison_anomalie"])
    rule_masks: dict[str, pd.Series] = {}
    rule_labels: dict[str, str] = {}

    def append_reason(mask: pd.Series, label: str, control: str) -> None:
        condition = pd.Series(mask, index=work.index).fillna(False).astype(bool)
        rule_masks[control] = condition
        rule_labels[control] = label

    missing_customer = (
        work["customer_id"].apply(_is_empty_text)
        if "customer_id" in work.columns
        else pd.Series(True, index=work.index)
    )
    append_reason(
        missing_customer,
        "customer_id manquant",
        "Lignes sans customer_id",
    )

    missing_reference = (
        work["reference_id"].apply(_is_empty_text)
        if "reference_id" in work.columns
        else pd.Series(True, index=work.index)
    )
    append_reason(
        missing_reference,
        "reference_id manquant",
        "Lignes sans reference_id",
    )

    invalid_dates = (
        pd.to_datetime(work["created_at"], errors="coerce").isna()
        if "created_at" in work.columns
        else pd.Series(True, index=work.index)
    )
    append_reason(
        invalid_dates,
        "Date created_at invalide ou manquante",
        "Dates invalides",
    )

    missing_currency = (
        work["currency_code"].apply(_is_empty_text)
        if "currency_code" in work.columns
        else pd.Series(True, index=work.index)
    )
    append_reason(
        missing_currency,
        "currency_code manquant",
        "currency_code vide",
    )

    if {"dr", "cr"}.issubset(work.columns):
        dr_values = numeric_column(work, "dr")
        cr_values = numeric_column(work, "cr")
        append_reason(
            dr_values.eq(0) & cr_values.eq(0),
            "Mouvement nul : dr = 0 et cr = 0",
            "Mouvements dr = 0 et cr = 0",
        )
        append_reason(
            dr_values.gt(0) & cr_values.gt(0),
            "Incoherence de sens : dr > 0 et cr > 0",
            "Lignes avec dr > 0 et cr > 0",
        )

    negative_balance = numeric_column(work, "bal_before").lt(0) | numeric_column(
        work,
        "bal_after",
    ).lt(0)
    append_reason(
        negative_balance,
        "Solde bal_before ou bal_after negatif",
        "Soldes bal_before/bal_after negatifs",
    )

    if "account_type" in work.columns:
        account_types = clean_text(work["account_type"]).str.upper()
        empty_account = account_types.eq("")
        unknown_account = account_types.ne("") & ~account_types.isin(KNOWN_ACCOUNT_TYPES)
    else:
        account_types = pd.Series("", index=work.index, dtype="string")
        empty_account = pd.Series(True, index=work.index)
        unknown_account = pd.Series(False, index=work.index)
    append_reason(
        empty_account,
        "account_type manquant",
        "account_type vide",
    )
    append_reason(
        unknown_account,
        "account_type non reference",
        "Types de comptes a classifier",
    )

    append_reason(
        work.duplicated(),
        "Doublon exact d'une ligne precedente",
        "Doublons exacts",
    )

    duplicate_key_columns = [
        column
        for column in ["customer_id", "created_at", "ref_no", "reference_id", "dr", "cr"]
        if column in work.columns
    ]
    repeated_group_rows = pd.Series(False, index=work.index)
    if duplicate_key_columns:
        duplicate_work = work.copy()
        duplicate_work["__account_type_control"] = account_types
        grouped = duplicate_work.groupby(
            duplicate_key_columns,
            dropna=False,
            sort=False,
        )["__account_type_control"]
        repeated_group_rows = grouped.transform("size").gt(1) & grouped.transform(
            "nunique"
        ).le(1)
    append_reason(
        repeated_group_rows,
        "Groupe d'ecritures repetees avec le meme type de compte",
        "Lignes dans des groupes d'ecritures repetees",
    )

    if selected_controls is None:
        active_controls = list(rule_masks)
    else:
        selected = {
            str(control).strip()
            for control in selected_controls
            if str(control).strip()
        }
        active_controls = [control for control in rule_masks if control in selected]

    reasons = pd.Series("", index=work.index, dtype="string")
    for control in active_controls:
        condition = rule_masks[control]
        label = rule_labels[control]
        updated = reasons.where(reasons.eq(""), reasons + " | ") + label
        reasons = reasons.mask(condition, updated)
    anomaly_mask = reasons.ne("")

    anomaly_mask_array = anomaly_mask.to_numpy()
    anomalies = work.iloc[anomaly_mask_array].copy()
    anomalies.insert(
        0,
        "raison_anomalie",
        reasons.iloc[anomaly_mask_array].to_numpy(),
    )
    return anomalies


def build_diagnostics(prepared: MpesaPreparedData, customer_id: str | None = None, statement: pd.DataFrame | None = None) -> pd.DataFrame:
    tx = prepared.transactions
    diagnostics: list[dict[str, object]] = []

    def add(control: str, value: int | str, status: str, detail: str = "") -> None:
        diagnostics.append({"controle": control, "valeur": value, "statut": status, "detail": detail})

    def add_dat_controls() -> None:
        fixed = prepared.fixed_savings
        if not isinstance(fixed, pd.DataFrame) or fixed.empty:
            return
        fixed = fixed.copy()
        if customer_id is not None and "customer_id" in fixed.columns:
            fixed = fixed.loc[fixed["customer_id"].astype("string").eq(str(customer_id))].copy()
        if fixed.empty or not {"date_approved", "maturity_date"}.issubset(fixed.columns):
            return
        approved = pd.to_datetime(fixed["date_approved"], errors="coerce")
        maturity = pd.to_datetime(fixed["maturity_date"], errors="coerce")
        invalid_order = approved.notna() & maturity.notna() & maturity.lt(approved)
        invalid_count = int(invalid_order.sum())
        add(
            "DAT - echeance anterieure a l'approbation",
            invalid_count,
            "OK" if invalid_count == 0 else "A surveiller",
            "Verifier les dates d'approbation et d'echeance des DAT concernes.",
        )

        analysis_date = pd.to_datetime(_mpesa_analysis_date(prepared), errors="coerce")
        if pd.isna(analysis_date):
            analysis_date = pd.Timestamp.now()
        positive_balance = numeric_column(fixed, "balance").gt(0)
        expired_positive = maturity.notna() & maturity.lt(pd.Timestamp(analysis_date).normalize()) & positive_balance
        expired_count = int(expired_positive.sum())
        rate = 100 * expired_count / len(fixed) if len(fixed) else 0.0
        add(
            "DAT echus avec solde positif",
            expired_count,
            "OK" if expired_count == 0 else "Controle metier",
            (
                f"{rate:.1f}% des DAT du perimetre. Peut correspondre a un renouvellement ou a un DAT non cloture; "
                "ne pas traiter automatiquement comme une erreur de donnees."
            ),
        )

    if tx.empty:
        add("Transactions chargees", 0, "A verifier", "Aucun fichier Transactions exploitable.")
        if not prepared.g2_transactions.empty:
            add("Transactions G2 chargees", int(len(prepared.g2_transactions)), "Information")
        add_dat_controls()
        return pd.DataFrame(diagnostics)

    missing_customer = int(tx["customer_id"].apply(_is_empty_text).sum()) if "customer_id" in tx.columns else len(tx)
    add("Lignes sans customer_id", missing_customer, "OK" if missing_customer == 0 else "A verifier")
    reference_missing = 0
    if "reference_id" in tx.columns:
        reference_missing += int(tx["reference_id"].apply(_is_empty_text).sum())
    add("Lignes sans reference_id", reference_missing, "OK" if reference_missing == 0 else "A verifier")
    ref_no_missing = int(tx["ref_no"].apply(_is_empty_text).sum()) if "ref_no" in tx.columns else len(tx)
    add("Lignes sans ref_no", ref_no_missing, "OK" if ref_no_missing == 0 else "Information")
    invalid_dates = int(pd.to_datetime(tx["created_at"], errors="coerce").isna().sum()) if "created_at" in tx.columns else len(tx)
    add("Dates invalides", invalid_dates, "OK" if invalid_dates == 0 else "A verifier")
    dr_values = numeric_column(tx, "dr")
    cr_values = numeric_column(tx, "cr")
    zero_moves = int((dr_values.eq(0) & cr_values.eq(0)).sum())
    add("Mouvements dr = 0 et cr = 0", zero_moves, "OK" if zero_moves == 0 else "A verifier")
    both_dr_cr = int((dr_values.gt(0) & cr_values.gt(0)).sum())
    add("Lignes avec dr > 0 et cr > 0", both_dr_cr, "OK" if both_dr_cr == 0 else "A verifier")
    negative_balance = int((numeric_column(tx, "bal_before").lt(0) | numeric_column(tx, "bal_after").lt(0)).sum())
    add("Soldes bal_before/bal_after negatifs", negative_balance, "OK" if negative_balance == 0 else "A verifier")
    empty_currency = int(tx["currency_code"].apply(_is_empty_text).sum()) if "currency_code" in tx.columns else len(tx)
    add("currency_code vide", empty_currency, "OK" if empty_currency == 0 else "A verifier")
    if "account_type" in tx.columns:
        account_types = clean_text(tx["account_type"]).str.upper()
        empty_account = int(account_types.eq("").sum())
        unknown_mask = account_types.ne("") & ~account_types.isin(KNOWN_ACCOUNT_TYPES)
        unknown_account = int(unknown_mask.sum())
        unknown_values = concat_unique(account_types.loc[unknown_mask])
    else:
        empty_account = len(tx)
        unknown_account = 0
        unknown_values = ""
    add("account_type vide", empty_account, "OK" if empty_account == 0 else "A verifier")
    add(
        "Types de comptes a classifier",
        unknown_account,
        "OK" if unknown_account == 0 else "A verifier",
        f"Valeurs non referencees : {unknown_values}" if unknown_values else "Tous les types charges sont references.",
    )

    exact_duplicates = int(tx.duplicated().sum())
    add("Doublons exacts", exact_duplicates, "OK" if exact_duplicates == 0 else "A verifier")
    duplicate_key_columns = [
        column
        for column in ["customer_id", "created_at", "ref_no", "reference_id", "dr", "cr"]
        if column in tx.columns
    ]
    linked_groups = 0
    linked_rows = 0
    repeated_to_review = 0
    repeated_rows_to_review = 0
    if duplicate_key_columns:
        duplicate_work = tx.copy()
        duplicate_work["__account_type_control"] = clean_text(
            duplicate_work.get("account_type", pd.Series("", index=duplicate_work.index))
        ).str.upper()
        duplicate_work["__id_control"] = clean_identifier(
            duplicate_work.get("id", pd.Series("", index=duplicate_work.index))
        )
        duplicate_groups = (
            duplicate_work.groupby(duplicate_key_columns, dropna=False, as_index=False)
            .agg(
                nombre_lignes=("__account_type_control", "size"),
                nombre_types_comptes=("__account_type_control", "nunique"),
                nombre_ids=("__id_control", "nunique"),
            )
        )
        repeated = duplicate_groups["nombre_lignes"].gt(1)
        linked = repeated & duplicate_groups["nombre_types_comptes"].gt(1)
        linked_groups = int(linked.sum())
        linked_rows = int(duplicate_groups.loc[linked, "nombre_lignes"].sum())
        repeated_to_review = int((repeated & ~linked).sum())
        repeated_rows_to_review = int(
            duplicate_groups.loc[repeated & ~linked, "nombre_lignes"].sum()
        )
    add(
        "Ecritures comptables liees",
        linked_groups,
        "Information",
        f"{linked_rows} lignes reparties dans {linked_groups} groupe(s) multi-comptes; elles ne sont pas des doublons.",
    )
    add(
        "Lignes dans des groupes d'ecritures repetees",
        repeated_rows_to_review,
        "OK" if repeated_rows_to_review == 0 else "A verifier",
        (
            f"{repeated_rows_to_review} ligne(s) repartie(s) dans "
            f"{repeated_to_review} groupe(s), avec les memes attributs de controle "
            "sans changement de type de compte."
        ),
    )
    add_dat_controls()
    if not prepared.g2_transactions.empty:
        g2_missing_phone = (
            int(prepared.g2_transactions["phone_prefixe"].isna().sum())
            if "phone_prefixe" in prepared.g2_transactions.columns
            else int(len(prepared.g2_transactions))
        )
        add("Transactions G2 chargees", int(len(prepared.g2_transactions)), "Information")
        add("Transactions G2 sans telephone exploitable", g2_missing_phone, "OK" if g2_missing_phone == 0 else "A verifier")

    if customer_id:
        clients_dat = set(prepared.fixed_savings["customer_id"].dropna().astype(str)) if not prepared.fixed_savings.empty and "customer_id" in prepared.fixed_savings.columns else set()
        clients_savings = set(prepared.current_savings["customer_id"].dropna().astype(str)) if not prepared.current_savings.empty and "customer_id" in prepared.current_savings.columns else set()
        add("Client sans fichier DAT", int(str(customer_id) not in clients_dat), "OK" if str(customer_id) in clients_dat else "Information")
        add("Client sans compte epargne", int(str(customer_id) not in clients_savings), "OK" if str(customer_id) in clients_savings else "Information")
        if statement is not None and not statement.empty:
            dat_refs = statement["reference_dat_operation"].astype("string").fillna("")
            credit_refs = statement["reference_credit_operation"].astype("string").fillna("")
            known_loans = set(prepared.loans["loan_id"].dropna().astype(str)) if not prepared.loans.empty and "loan_id" in prepared.loans.columns else set()
            unknown_credit_refs = int(credit_refs.ne("").sum()) if not known_loans else int((credit_refs.ne("") & ~credit_refs.isin(known_loans)).sum())
            add("References DAT detectees", int(dat_refs.ne("").sum()), "Information")
            add("References credit non reconnues", unknown_credit_refs, "OK" if unknown_credit_refs == 0 else "A verifier")

    return pd.DataFrame(diagnostics)


def format_statement_columns(statement: pd.DataFrame) -> pd.DataFrame:
    ordered = [
        "created_at",
        "customer_id",
        "Nom_client",
        "mode_rapprochement_nom_client",
        "telephone",
        "currency_code",
        "type_operation",
        "operation_reference",
        "references_internes",
        "reference_dat_operation",
        "reference_credit_operation",
        "description_turbo",
        "descriptions",
        "pret_brut_decaisse",
        "interet_pret_preleve",
        "taux_interet_pret_pct",
        "taux_interet_pret_reference_pct",
        "interet_pret_reference_7pct",
        "ecart_interet_pret_vs_7pct",
        "net_pret_verse",
        "entree_mpesa",
        "sortie_mpesa",
        "mouvement_net_mpesa",
        "debit_compte_ouvert",
        "credit_compte_ouvert",
        "description_compte_ouvert",
        "nombre_lignes_compte_ouvert",
        "solde_mpesa_avant",
        "solde_mpesa_apres",
        "cumul_net_depuis_debut_fichier",
        "solde_epargne_au_moment",
        "solde_dat_operation_avant",
        "solde_dat_operation_apres",
        "variation_dat_operation",
        "solde_dat_total_au_moment",
        "dat_final_client",
        "epargne_courante_finale",
        "loan_id",
        "loan_amount",
        "loan_balance",
        "amount_paid",
        "outstanding_principle",
        "outstanding_interest",
        "outstanding_penalty_fees",
        "status_name",
        "due_date",
        "controle_mouvement",
        "nombre_lignes_comptables",
    ]
    present = [column for column in ordered if column in statement.columns]
    rest = [column for column in statement.columns if column not in present]
    return statement[present + rest].copy()


def _customer_internal_savings_repayment_mask(frame: pd.DataFrame) -> pd.Series:
    """Repere les remboursements finances par le compte d'epargne ouvert.

    Ces evenements soldent une position de credit par transfert interne
    ``NORMAL SAVINGS -> credit``. Ils restent visibles dans les remboursements,
    mais ne constituent ni une nouvelle entree ni une nouvelle sortie externe
    de Bisou Bisou.
    """
    operation_type = clean_text(
        frame.get("type_operation", pd.Series("", index=frame.index))
    )
    normalized_accounts = frame.get(
        "account_types", pd.Series("", index=frame.index)
    ).apply(normalize_label)
    normalized_descriptions = frame.get(
        "descriptions", pd.Series("", index=frame.index)
    ).apply(normalize_label)
    return (
        operation_type.isin(
            ["Remboursement de credit", "Remboursement avec penalite"]
        )
        & normalized_accounts.str.contains("normal savings", na=False)
        & normalized_descriptions.str.contains(
            r"remboursement.*compte|compte.*remboursement",
            regex=True,
            na=False,
        )
    )


def build_customer_statement_view(
    statement: pd.DataFrame,
    *,
    account_number: object = "",
    entry_account_number: object | None = None,
    output_account_number: object | None = None,
    allow_multiple_currencies: bool = False,
) -> dict[str, Any]:
    """Construit l'extrait officiel selon le sens metier Bisou Bisou.

    Le compte Turbo ``MPESA ACCOUNT`` porte le mouvement inverse du flux de
    l'organisation : un debit Turbo correspond a une entree Bisou Bisou et un
    credit Turbo a une sortie. Les cumuls restent calcules separement par devise.
    """
    legacy_account = str(account_number).strip()
    entry_account = (
        legacy_account if entry_account_number is None else str(entry_account_number).strip()
    )
    output_account = (
        legacy_account if output_account_number is None else str(output_account_number).strip()
    )
    empty_transactions = pd.DataFrame(columns=CUSTOMER_STATEMENT_COLUMNS)
    empty_result: dict[str, Any] = {
        "transactions": empty_transactions,
        "currency": "",
        "customer_id": "",
        "customer_name": "",
        "telephone": "",
        "account_number": legacy_account,
        "entry_account_number": entry_account,
        "output_account_number": output_account,
        "total_entries": 0.0,
        "total_outputs": 0.0,
        "flow_net": 0.0,
        "opening_amount": np.nan,
        "closing_amount": np.nan,
        "balance_is_real": False,
        "balance_label": "Cumul net",
        "summary_by_currency": pd.DataFrame(),
        "detail_transactions": empty_transactions,
    }
    if not isinstance(statement, pd.DataFrame) or statement.empty:
        return empty_result

    frame = statement.copy()
    frame["currency_code"] = clean_text(
        frame.get("currency_code", pd.Series("", index=frame.index))
    ).str.upper()
    currencies = [value for value in frame["currency_code"].dropna().unique().tolist() if value]
    if len(currencies) > 1 and not allow_multiple_currencies:
        raise ValueError("L'extrait client officiel doit contenir une seule devise.")
    currency = "ALL" if len(currencies) > 1 else currencies[0] if currencies else "SANS DEVISE"

    frame["created_at"] = pd.to_datetime(
        frame.get("created_at", pd.Series(pd.NaT, index=frame.index)), errors="coerce"
    )
    frame = frame.sort_values(["created_at", "operation_reference"], na_position="last").reset_index(drop=True)
    turbo_entries = pd.to_numeric(
        frame.get("entree_mpesa", pd.Series(0.0, index=frame.index)), errors="coerce"
    ).fillna(0.0)
    turbo_outputs = pd.to_numeric(
        frame.get("sortie_mpesa", pd.Series(0.0, index=frame.index)), errors="coerce"
    ).fillna(0.0)
    # Le sens du compte MPESA Turbo est inverse du flux de l'organisation.
    # Un remboursement finance par NORMAL SAVINGS est toutefois un transfert
    # interne : il reste dans le bloc des remboursements mais ne constitue pas
    # un nouvel encaissement externe.
    internal_repayment = _customer_internal_savings_repayment_mask(frame)
    entries = turbo_outputs.mask(internal_repayment, 0.0)
    outputs = turbo_entries.mask(internal_repayment, 0.0)
    movements = entries - outputs

    real_before = pd.to_numeric(
        frame.get("solde_mpesa_avant", pd.Series(np.nan, index=frame.index)), errors="coerce"
    )
    if "solde_mpesa_disponible" in frame.columns:
        available = frame["solde_mpesa_disponible"].astype("boolean").fillna(False)
    else:
        available = real_before.notna()

    displayed_balance = pd.Series(np.nan, index=frame.index, dtype="float64")
    summary_rows: list[dict[str, object]] = []
    for currency_code, index in frame.groupby("currency_code", sort=True, dropna=False).groups.items():
        group_movements = movements.loc[index]
        group_real = bool(available.loc[index].all() and real_before.loc[index].notna().all())
        if group_real:
            opening = float(real_before.loc[index].iloc[0])
            group_balance = opening + group_movements.cumsum()
        else:
            opening = 0.0
            group_balance = group_movements.cumsum()
        displayed_balance.loc[index] = group_balance
        summary_rows.append(
            {
                "currency_code": currency_code or "SANS DEVISE",
                "total_entries": float(entries.loc[index].sum()),
                "total_outputs": float(outputs.loc[index].sum()),
                "opening_amount": opening,
                "closing_amount": float(group_balance.iloc[-1]),
                "balance_is_real": group_real,
                "balance_label": "Solde" if group_real else "Cumul net",
            }
        )
    summary_by_currency = pd.DataFrame(summary_rows)
    balance_is_real = bool(
        not summary_by_currency.empty
        and summary_by_currency["balance_is_real"].astype(bool).all()
    )

    names = frame.get("Nom_client", pd.Series("", index=frame.index))
    phones = frame.get("telephone", pd.Series("", index=frame.index))

    def french_number(value: object, *, decimals: int = 2) -> str:
        number = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
        if pd.isna(number):
            return "-"
        return (
            f"{float(number):,.{decimals}f}"
            .replace(",", "\u00a0")
            .replace(".", ",")
        )

    def french_percent(value: object) -> str:
        number = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
        if pd.isna(number):
            return "-"
        decimals = 0 if abs(float(number) - round(float(number))) < 1e-9 else 2
        return french_number(number, decimals=decimals)

    def numeric_or_zero(value: object) -> float:
        number = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
        return 0.0 if pd.isna(number) else float(number)

    def statement_description(row: pd.Series) -> str:
        if str(row.get("type_operation", "")).strip() == "Decaissement de credit":
            gross = numeric_or_zero(row.get("pret_brut_decaisse"))
            interest = numeric_or_zero(row.get("interet_pret_preleve"))
            net = numeric_or_zero(row.get("net_pret_verse"))
            rate = pd.to_numeric(row.get("taux_interet_pret_pct"), errors="coerce")
            # Ne détailler la retenue que si Turbo porte effectivement les deux
            # faces MPESA. Une exportation partielle avec le seul crédit brut ne
            # permet pas d'inventer l'intérêt ni le net contractuel.
            if gross > 0 and interest > 0 and pd.notna(rate):
                currency_code = str(row.get("currency_code", "")).strip().upper()
                currency_suffix = f" {currency_code}" if currency_code else ""
                loan_label = (
                    f"Prêt brut : {french_number(gross)}{currency_suffix} — "
                    f"intérêt prélevé : {french_number(interest)}{currency_suffix} "
                    f"({french_percent(rate)} %) — "
                    f"net versé : {french_number(net)}{currency_suffix}"
                )
                identity = [row.get("telephone"), row.get("Nom_client")]
                identity_text = " - ".join(
                    str(value).strip() for value in identity if not _is_empty_text(value)
                )
                return f"{loan_label} - {identity_text}" if identity_text else loan_label
        turbo_description = row.get("description_turbo")
        if _is_empty_text(turbo_description):
            turbo_description = row.get("descriptions")
        parts = [turbo_description, row.get("telephone"), row.get("Nom_client")]
        return " - ".join(str(value).strip() for value in parts if not _is_empty_text(value))

    account_values = np.select(
        [entries.gt(0), outputs.gt(0)],
        [entry_account, output_account],
        default=entry_account or output_account,
    )
    transactions = pd.DataFrame(
        {
            "date": frame["created_at"],
            "compte": account_values,
            "receipt_no": frame.get("operation_reference", pd.Series("", index=frame.index)),
            "devise": frame["currency_code"],
            "description": frame.apply(statement_description, axis=1),
            "entree": entries,
            "sortie": outputs,
            "solde": displayed_balance,
        }
    )[CUSTOMER_STATEMENT_COLUMNS]

    if len(summary_by_currency) == 1:
        summary_row = summary_by_currency.iloc[0]
        opening_amount = summary_row["opening_amount"]
        closing_amount = summary_row["closing_amount"]
        total_entries = summary_row["total_entries"]
        total_outputs = summary_row["total_outputs"]
        flow_net = float(total_entries) - float(total_outputs)
        balance_label = summary_row["balance_label"]
    else:
        opening_amount = np.nan
        closing_amount = np.nan
        total_entries = np.nan
        total_outputs = np.nan
        flow_net = np.nan
        balance_label = "Solde par devise" if balance_is_real else "Cumul net par devise"

    result = dict(empty_result)
    result.update(
        {
            "transactions": transactions,
            "currency": currency,
            "customer_id": concat_unique(frame.get("customer_id", pd.Series("", index=frame.index))),
            "customer_name": concat_unique(names),
            "telephone": concat_unique(phones),
            "total_entries": float(total_entries) if pd.notna(total_entries) else np.nan,
            "total_outputs": float(total_outputs) if pd.notna(total_outputs) else np.nan,
            "flow_net": float(flow_net) if pd.notna(flow_net) else np.nan,
            "opening_amount": float(opening_amount) if pd.notna(opening_amount) else np.nan,
            "closing_amount": float(closing_amount) if pd.notna(closing_amount) else np.nan,
            "balance_is_real": balance_is_real,
            "balance_label": balance_label,
            "entry_account_number": entry_account,
            "output_account_number": output_account,
            "summary_by_currency": summary_by_currency,
            "detail_transactions": _customer_open_savings_detail_transactions(
                transactions,
                frame,
                entry_account_number=entry_account,
                output_account_number=output_account,
            ),
        }
    )
    return result


def _customer_open_savings_detail_transactions(
    transactions: pd.DataFrame,
    statement: pd.DataFrame,
    *,
    entry_account_number: object | None = None,
    output_account_number: object | None = None,
) -> pd.DataFrame:
    """Construit le détail à partir du seul compte ouvert du client.

    Le tableau ``Détail des transactions`` est un relevé opérationnel du compte
    ouvert : il reprend uniquement les écritures ``NORMAL SAVINGS``. Les dépôts
    DAT, les décaissements de prêt et les écritures techniques de crédit qui ne
    touchent pas le compte ouvert restent dans leurs blocs dédiés.
    """
    empty_detail = pd.DataFrame(columns=CUSTOMER_STATEMENT_COLUMNS)
    if (
        transactions.empty
        or not isinstance(statement, pd.DataFrame)
        or statement.empty
        or not {"debit_compte_ouvert", "credit_compte_ouvert"}.issubset(statement.columns)
    ):
        return empty_detail

    frame = statement.copy()
    frame["created_at"] = pd.to_datetime(
        frame.get("created_at", pd.Series(pd.NaT, index=frame.index)),
        errors="coerce",
    )
    frame["currency_code"] = clean_text(
        frame.get("currency_code", pd.Series("", index=frame.index))
    ).str.upper()
    frame["debit_compte_ouvert"] = pd.to_numeric(
        frame["debit_compte_ouvert"], errors="coerce"
    ).fillna(0.0)
    frame["credit_compte_ouvert"] = pd.to_numeric(
        frame["credit_compte_ouvert"], errors="coerce"
    ).fillna(0.0)
    frame = frame.loc[
        frame["debit_compte_ouvert"].abs().gt(0)
        | frame["credit_compte_ouvert"].abs().gt(0)
    ].copy()
    if frame.empty:
        return empty_detail
    frame = frame.sort_values(
        ["currency_code", "created_at", "operation_reference"],
        na_position="last",
    ).reset_index(drop=True)

    entry_account = str(entry_account_number or "").strip() or "Compte ouvert"
    output_account = str(output_account_number or "").strip() or "Compte ouvert"

    def detail_description(row: pd.Series) -> str:
        source_description = row.get("description_compte_ouvert")
        if _is_empty_text(source_description):
            source_description = row.get("description_turbo")
        if _is_empty_text(source_description):
            source_description = row.get("descriptions")
        parts = [source_description, row.get("telephone"), row.get("Nom_client")]
        return " - ".join(str(value).strip() for value in parts if not _is_empty_text(value))

    entree = frame["credit_compte_ouvert"]
    sortie = frame["debit_compte_ouvert"]
    account_values = np.select(
        [entree.gt(0) & sortie.le(0), sortie.gt(0) & entree.le(0)],
        [entry_account, output_account],
        default="Compte ouvert",
    )
    detail = pd.DataFrame(
        {
            "date": frame["created_at"],
            "compte": account_values,
            "receipt_no": frame.get(
                "operation_reference",
                pd.Series("", index=frame.index),
            ),
            "devise": frame["currency_code"],
            "description": frame.apply(detail_description, axis=1),
            "entree": entree,
            "sortie": sortie,
        }
    )
    detail["solde"] = (
        detail["entree"].sub(detail["sortie"]).groupby(detail["devise"], sort=False).cumsum()
    )
    return detail[CUSTOMER_STATEMENT_COLUMNS].reset_index(drop=True)


def _customer_statement_detail_transactions(
    transactions: pd.DataFrame,
    statement: pd.DataFrame,
) -> pd.DataFrame:
    """Évite de répéter les mouvements déjà présentés dans un bloc dédié.

    Le dépôt DAT reste inclus dans les flux externes et le cumul. Le
    remboursement financé par le compte ouvert reste dans ``Remboursements
    observés`` mais est exclu des flux externes et du détail transactionnel.
    """
    detail = transactions.copy()
    if (
        detail.empty
        or not isinstance(statement, pd.DataFrame)
        or statement.empty
        or "type_operation" not in statement.columns
    ):
        return detail

    dat_deposit = clean_text(statement["type_operation"]).eq(
        "Sortie M-PESA_Turbo vers DAT"
    )
    internal_repayment = _customer_internal_savings_repayment_mask(statement)
    excluded_statement = statement.loc[dat_deposit | internal_repayment].copy()
    if excluded_statement.empty:
        return detail

    excluded_keys = pd.MultiIndex.from_arrays(
        [
            pd.to_datetime(
                excluded_statement.get(
                    "created_at",
                    pd.Series(pd.NaT, index=excluded_statement.index),
                ),
                errors="coerce",
            ),
            clean_text(
                excluded_statement.get(
                    "currency_code",
                    pd.Series("", index=excluded_statement.index),
                )
            ).str.upper(),
            clean_text(
                excluded_statement.get(
                    "operation_reference",
                    pd.Series("", index=excluded_statement.index),
                )
            ),
        ]
    )
    detail_keys = pd.MultiIndex.from_arrays(
        [
            pd.to_datetime(
                detail.get("date", pd.Series(pd.NaT, index=detail.index)),
                errors="coerce",
            ),
            clean_text(
                detail.get("devise", pd.Series("", index=detail.index))
            ).str.upper(),
            clean_text(
                detail.get("receipt_no", pd.Series("", index=detail.index))
            ),
        ]
    )
    return detail.loc[~detail_keys.isin(excluded_keys)].reset_index(drop=True)


def _customer_statement_export_detail(
    transactions: pd.DataFrame,
    statement: pd.DataFrame,
    summary_by_currency: pd.DataFrame,
    *,
    entry_account_number: object | None = None,
    output_account_number: object | None = None,
) -> pd.DataFrame:
    """Prépare le détail officiel du compte ouvert.

    Son cumul part de zéro et suit uniquement les écritures ``NORMAL SAVINGS``
    affichées dans ce tableau. Le solde d'ouverture, la clôture, les DAT et le
    prêt net restent dans leurs blocs dédiés.
    """
    detail = _customer_open_savings_detail_transactions(
        transactions,
        statement,
        entry_account_number=entry_account_number,
        output_account_number=output_account_number,
    )
    if detail.empty or "solde" not in detail.columns:
        return detail
    detail["solde"] = pd.to_numeric(detail["solde"], errors="coerce")
    return detail


def _customer_statement_flow_summary(view: dict[str, Any]) -> pd.DataFrame:
    """Restitue les flux Bisou Bisou et leurs bornes d'ouverture/clôture."""
    source = view.get("summary_by_currency", pd.DataFrame())
    summary = source.copy() if isinstance(source, pd.DataFrame) else pd.DataFrame()
    columns = [
        "currency_code",
        "opening_amount",
        "total_entries",
        "total_outputs",
        "flow_net",
        "closing_amount",
    ]
    if summary.empty:
        return pd.DataFrame(columns=columns)
    openings = summary.get("opening_amount", pd.Series(0.0, index=summary.index))
    entries = summary.get("total_entries", pd.Series(0.0, index=summary.index))
    outputs = summary.get("total_outputs", pd.Series(0.0, index=summary.index))
    closings = summary.get("closing_amount", pd.Series(np.nan, index=summary.index))
    summary["opening_amount"] = pd.to_numeric(openings, errors="coerce").fillna(0.0)
    summary["total_entries"] = pd.to_numeric(entries, errors="coerce").fillna(0.0)
    summary["total_outputs"] = pd.to_numeric(outputs, errors="coerce").fillna(0.0)
    summary["flow_net"] = summary["total_entries"] - summary["total_outputs"]
    summary["closing_amount"] = pd.to_numeric(closings, errors="coerce")
    summary["closing_amount"] = summary["closing_amount"].fillna(
        summary["opening_amount"] + summary["flow_net"]
    )
    return summary[columns].reset_index(drop=True)


def _customer_statement_analysis_frame(
    analysis_report: dict[str, Any],
    key: str,
    *,
    customer_id: object,
    currency: object,
    all_currencies: bool,
) -> pd.DataFrame:
    """Limite une analyse au client et à la devise du document."""
    source = analysis_report.get(key, pd.DataFrame())
    if not isinstance(source, pd.DataFrame) or source.empty:
        return pd.DataFrame()
    scoped = source.copy()
    customer_scope = clean_identifier(pd.Series([customer_id])).iloc[0]
    if customer_scope and "customer_id" in scoped.columns:
        scoped = scoped.loc[
            clean_identifier(scoped["customer_id"]).eq(customer_scope)
        ].copy()
    if not all_currencies:
        currency_text = str(currency).strip().upper()
        currency_column = next(
            (
                column
                for column in ["currency_code", "devise"]
                if column in scoped.columns
            ),
            "",
        )
        if currency_column:
            scoped = scoped.loc[
                clean_text(scoped[currency_column]).str.upper().eq(currency_text)
            ].copy()
    return scoped


def build_customer_statement_detail_with_covered_operations(
    detail: pd.DataFrame,
    analysis_report: dict[str, Any],
    *,
    customer_id: object,
    currency: object,
    entry_account_number: object | None = None,
    all_currencies: bool = False,
) -> pd.DataFrame:
    """Ajoute au détail les opérations DAT qui reviennent au compte client.

    Le détail reste un relevé opérationnel : dépôts, retraits et remboursements
    depuis le compte ouvert viennent des lignes ``NORMAL SAVINGS``. Les retours
    de principal DAT et les intérêts DAT constatés peuvent provenir des analyses
    Turbo/Savings, car ils n'ont pas toujours une ligne ``MPESA ACCOUNT``.
    """
    base = (
        detail.copy()
        if isinstance(detail, pd.DataFrame) and not detail.empty
        else pd.DataFrame(columns=CUSTOMER_STATEMENT_COLUMNS)
    )
    for column in CUSTOMER_STATEMENT_COLUMNS:
        if column not in base.columns:
            base[column] = pd.NA
    base = base[CUSTOMER_STATEMENT_COLUMNS].copy()
    base["date"] = pd.to_datetime(base["date"], errors="coerce")
    base["devise"] = clean_text(base["devise"]).str.upper()
    base["entree"] = pd.to_numeric(base["entree"], errors="coerce").fillna(0.0)
    base["sortie"] = pd.to_numeric(base["sortie"], errors="coerce").fillna(0.0)

    account = str(entry_account_number or "").strip() or "Compte ouvert"
    rows: list[dict[str, object]] = []

    def has_similar_entry(date_value: object, currency_value: object, amount: float, pattern: str) -> bool:
        if base.empty or amount <= 0:
            return False
        dates = pd.to_datetime(base["date"], errors="coerce")
        date = pd.to_datetime(date_value, errors="coerce")
        if pd.isna(date):
            date_mask = pd.Series(False, index=base.index)
        else:
            date_mask = dates.eq(date)
        currency_mask = base["devise"].eq(str(currency_value).strip().upper())
        amount_mask = (base["entree"] - float(amount)).abs().le(1e-9)
        description_mask = base["description"].apply(normalize_label).str.contains(
            pattern,
            regex=True,
            na=False,
        )
        return bool((date_mask & currency_mask & amount_mask & description_mask).any())

    internal = _customer_statement_analysis_frame(
        analysis_report,
        "mouvements_internes_turbo",
        customer_id=customer_id,
        currency=currency,
        all_currencies=all_currencies,
    )
    if not internal.empty:
        for _, row in internal.iterrows():
            amount = pd.to_numeric(
                pd.Series(
                    [
                        row.get("transfert_epargne_entree"),
                        row.get("transfert_dat_sortie"),
                        row.get("montant_operation"),
                    ]
                ),
                errors="coerce",
            ).dropna()
            value = float(amount.max()) if not amount.empty else 0.0
            if value <= 0:
                continue
            date_value = row.get("created_at")
            currency_value = str(row.get("currency_code", "")).strip().upper()
            if has_similar_entry(date_value, currency_value, value, r"retrait compte bloque|dat"):
                continue
            reference = row.get("event_reference")
            description = "Retour du montant principal du DAT"
            source_description = row.get("descriptions")
            if not _is_empty_text(source_description):
                description = f"{description} - {source_description}"
            rows.append(
                {
                    "date": date_value,
                    "compte": account,
                    "receipt_no": reference,
                    "devise": currency_value,
                    "description": description,
                    "entree": value,
                    "sortie": 0.0,
                    "solde": 0.0,
                }
            )

    dat_interest = _customer_statement_analysis_frame(
        analysis_report,
        "interets_dat_credites_client",
        customer_id=customer_id,
        currency=currency,
        all_currencies=all_currencies,
    )
    if not dat_interest.empty:
        for _, row in dat_interest.iterrows():
            value = pd.to_numeric(row.get("interet_client_constate"), errors="coerce")
            if pd.isna(value) or float(value) <= 0:
                continue
            date_value = row.get("date_ecriture_turbo")
            if pd.isna(pd.to_datetime(date_value, errors="coerce")):
                date_value = row.get("maturity_date")
            currency_value = str(row.get("currency_code", "")).strip().upper()
            if has_similar_entry(date_value, currency_value, float(value), r"interet|intérêt|dat"):
                continue
            reference = row.get("reference_transaction_turbo")
            if _is_empty_text(reference):
                reference = row.get("savings_id")
            savings_id = row.get("savings_id")
            description = "Entrée des intérêts sur DAT"
            if not _is_empty_text(savings_id):
                description = f"{description} - {savings_id}"
            rows.append(
                {
                    "date": date_value,
                    "compte": account,
                    "receipt_no": reference,
                    "devise": currency_value,
                    "description": description,
                    "entree": float(value),
                    "sortie": 0.0,
                    "solde": 0.0,
                }
            )

    if rows:
        additional = pd.DataFrame(rows)
        base = (
            additional
            if base.empty
            else pd.concat([base, additional], ignore_index=True, sort=False)
        )
    if base.empty:
        return base[CUSTOMER_STATEMENT_COLUMNS]
    base["date"] = pd.to_datetime(base["date"], errors="coerce")
    base["devise"] = clean_text(base["devise"]).str.upper()
    base["entree"] = pd.to_numeric(base["entree"], errors="coerce").fillna(0.0)
    base["sortie"] = pd.to_numeric(base["sortie"], errors="coerce").fillna(0.0)
    base = base.sort_values(
        ["devise", "date", "receipt_no"],
        na_position="last",
    ).reset_index(drop=True)
    base["solde"] = (
        base["entree"].sub(base["sortie"]).groupby(base["devise"], sort=False).cumsum()
    )
    return base[CUSTOMER_STATEMENT_COLUMNS].reset_index(drop=True)


def build_customer_statement_detail_with_opening_balance(
    detail: pd.DataFrame,
    financial_summary: pd.DataFrame,
) -> pd.DataFrame:
    """Recalcule le solde du détail depuis l'ouverture de la synthèse."""
    if not isinstance(detail, pd.DataFrame) or detail.empty:
        return pd.DataFrame(columns=CUSTOMER_STATEMENT_COLUMNS)
    output = detail.copy()
    for column in CUSTOMER_STATEMENT_COLUMNS:
        if column not in output.columns:
            output[column] = pd.NA
    output = output[CUSTOMER_STATEMENT_COLUMNS].copy()
    output["date"] = pd.to_datetime(output["date"], errors="coerce")
    output["devise"] = clean_text(output["devise"]).str.upper()
    output["entree"] = pd.to_numeric(output["entree"], errors="coerce").fillna(0.0)
    output["sortie"] = pd.to_numeric(output["sortie"], errors="coerce").fillna(0.0)
    if (
        isinstance(financial_summary, pd.DataFrame)
        and not financial_summary.empty
        and {"currency_code", "opening_amount"}.issubset(financial_summary.columns)
    ):
        openings = (
            financial_summary.assign(
                currency_code=clean_text(financial_summary["currency_code"]).str.upper(),
                opening_amount=pd.to_numeric(
                    financial_summary["opening_amount"], errors="coerce"
                ).fillna(0.0),
            )
            .drop_duplicates("currency_code", keep="last")
            .set_index("currency_code")["opening_amount"]
        )
    else:
        openings = pd.Series(dtype="float64")
    output = output.sort_values(
        ["devise", "date", "receipt_no"],
        na_position="last",
    ).reset_index(drop=True)
    movement = output["entree"] - output["sortie"]
    output["solde"] = movement.groupby(output["devise"], sort=False).cumsum()
    output["solde"] = output["solde"] + output["devise"].map(openings).fillna(0.0)
    return output[CUSTOMER_STATEMENT_COLUMNS].reset_index(drop=True)


def _customer_statement_dat_rate_label(
    analysis_report: dict[str, Any],
    *,
    customer_id: object,
    currency: object,
    all_currencies: bool,
) -> str:
    """Formate le ou les taux DAT réellement utilisés dans le document."""
    active_dat = _customer_statement_analysis_frame(
        analysis_report,
        "dat_en_cours_client",
        customer_id=customer_id,
        currency=currency,
        all_currencies=all_currencies,
    )
    rates = pd.to_numeric(
        active_dat.get(
            "taux_interet_annuel_pct",
            pd.Series(dtype="float64"),
        ),
        errors="coerce",
    ).dropna()
    unique_rates = sorted({float(value) for value in rates.tolist()})
    if not unique_rates:
        unique_rates = [float(DEFAULT_DAT_ANNUAL_INTEREST_RATE_PCT)]
    return " / ".join(
        f"{rate:.1f} %".replace(".", ",") for rate in unique_rates
    )


def build_customer_statement_savings_summary(
    analysis_report: dict[str, Any],
    *,
    customer_id: object,
    currency: object,
    all_currencies: bool = False,
) -> pd.DataFrame:
    """Sépare les positions d'épargne courante et de DAT par devise."""
    summary = _customer_statement_analysis_frame(
        analysis_report,
        "synthese",
        customer_id=customer_id,
        currency=currency,
        all_currencies=all_currencies,
    )
    columns = ["currency_code", "compte_ouvert", "compte_bloque"]
    if summary.empty:
        return pd.DataFrame(columns=columns)
    currency_column = (
        "devise" if "devise" in summary.columns else "currency_code"
    )
    result = pd.DataFrame(
        {
            "currency_code": clean_text(summary[currency_column]).str.upper(),
            "compte_ouvert": pd.to_numeric(
                summary.get(
                    "epargne_courante_finale",
                    pd.Series(np.nan, index=summary.index),
                ),
                errors="coerce",
            ),
            "compte_bloque": pd.to_numeric(
                summary.get(
                    "dat_final",
                    pd.Series(np.nan, index=summary.index),
                ),
                errors="coerce",
            ),
        }
    )
    return result.loc[result["currency_code"].ne(""), columns].reset_index(drop=True)


def build_customer_statement_financial_summary(
    view: dict[str, Any],
    analysis_report: dict[str, Any],
    *,
    customer_id: object,
    currency: object,
    all_currencies: bool = False,
) -> pd.DataFrame:
    """Produit une synthèse bancaire du compte ouvert, enrichie par l'épargne."""
    flow_summary = _customer_statement_flow_summary(view)
    savings_summary = build_customer_statement_savings_summary(
        analysis_report,
        customer_id=customer_id,
        currency=currency,
        all_currencies=all_currencies,
    )
    columns = [
        "currency_code",
        "opening_amount",
        "total_entries",
        "total_outputs",
        "flow_net",
        "closing_amount",
        "compte_ouvert",
        "compte_bloque",
    ]
    if flow_summary.empty and savings_summary.empty:
        return pd.DataFrame(columns=columns)

    detail = view.get("detail_transactions", pd.DataFrame())
    if isinstance(detail, pd.DataFrame) and not detail.empty and "devise" in detail.columns:
        detail_frame = detail.copy()
        detail_frame["currency_code"] = clean_text(detail_frame["devise"]).str.upper()
        detail_frame["entree"] = pd.to_numeric(
            detail_frame.get("entree", pd.Series(0.0, index=detail_frame.index)),
            errors="coerce",
        ).fillna(0.0)
        detail_frame["sortie"] = pd.to_numeric(
            detail_frame.get("sortie", pd.Series(0.0, index=detail_frame.index)),
            errors="coerce",
        ).fillna(0.0)
        bank_flow_summary = (
            detail_frame.groupby("currency_code", as_index=False, dropna=False)
            .agg(total_entries=("entree", "sum"), total_outputs=("sortie", "sum"))
        )
    else:
        bank_flow_summary = pd.DataFrame(
            columns=["currency_code", "total_entries", "total_outputs"]
        )

    currencies: set[str] = set()
    for source in [flow_summary, savings_summary, bank_flow_summary]:
        if isinstance(source, pd.DataFrame) and not source.empty and "currency_code" in source.columns:
            currencies |= {
                str(value).strip().upper()
                for value in source["currency_code"].dropna().tolist()
                if str(value).strip()
            }
    summary = pd.DataFrame({"currency_code": sorted(currencies)})
    summary = summary.merge(
        bank_flow_summary,
        on="currency_code",
        how="left",
    ).merge(
        savings_summary,
        on="currency_code",
        how="left",
    )
    for column in columns:
        if column not in summary.columns:
            summary[column] = np.nan
    summary["currency_code"] = clean_text(summary["currency_code"]).str.upper()
    summary["total_entries"] = pd.to_numeric(
        summary["total_entries"], errors="coerce"
    ).fillna(0.0)
    summary["total_outputs"] = pd.to_numeric(
        summary["total_outputs"], errors="coerce"
    ).fillna(0.0)
    summary["flow_net"] = summary["total_entries"] - summary["total_outputs"]
    compte_ouvert = pd.to_numeric(summary["compte_ouvert"], errors="coerce")
    summary["closing_amount"] = compte_ouvert.where(
        compte_ouvert.notna(),
        summary["flow_net"],
    )
    summary["opening_amount"] = summary["closing_amount"] - summary["flow_net"]
    flow_order = {
        str(value).upper(): index
        for index, value in enumerate(
            flow_summary.get("currency_code", pd.Series(dtype=str)).tolist()
        )
    }
    summary["__order"] = summary["currency_code"].map(flow_order).fillna(
        len(flow_order)
    )
    return (
        summary.loc[summary["currency_code"].ne("")]
        .sort_values(["__order", "currency_code"])
        .drop(columns="__order")
        .loc[:, columns]
        .reset_index(drop=True)
    )


def _customer_statement_currency_label(
    transactions: pd.DataFrame,
    currency_text: str,
    all_currencies: bool,
    fallback: str = "",
) -> str:
    observed = sorted(
        value
        for value in transactions.get("devise", pd.Series(dtype=str)).dropna().astype(str).unique().tolist()
        if value
    )
    if all_currencies:
        return f"ALL ({', '.join(observed)})" if observed else "ALL"
    return currency_text or fallback or (observed[0] if observed else "")


def _filter_customer_statement_for_export(
    statement: pd.DataFrame,
    currency: object,
    *,
    error_label: str,
) -> tuple[pd.DataFrame, str, bool]:
    if not isinstance(statement, pd.DataFrame) or statement.empty:
        raise ValueError(f"Aucune operation filtree n'est disponible pour {error_label}.")
    currency_text = str(currency).strip().upper()
    all_currencies = currency_text in {"ALL", "TOUTES", "TOUS", "CDF + USD"}
    frame = statement.copy()
    frame_currency = clean_text(
        frame.get("currency_code", pd.Series("", index=frame.index))
    ).str.upper()
    if not all_currencies:
        frame = frame.loc[frame_currency.eq(currency_text)].copy()
    if frame.empty:
        raise ValueError(
            f"Aucune operation {currency_text or 'sans devise'} n'est disponible pour {error_label}."
        )
    return frame, currency_text, all_currencies


def _customer_client_statement_operation_label(row: pd.Series) -> str:
    operation_type = str(row.get("type_operation", "")).strip()
    if operation_type == "Sortie M-PESA_Turbo vers DAT":
        return "Dépôt DAT / compte bloqué"
    if operation_type == "Sortie M-PESA_Turbo vers epargne":
        return "Dépôt compte ouvert"
    if operation_type == "Entree M-PESA_Turbo depuis epargne":
        return "Retrait depuis compte ouvert"
    if operation_type == "Decaissement de credit":
        gross = pd.to_numeric(row.get("pret_brut_decaisse"), errors="coerce")
        interest = pd.to_numeric(row.get("interet_pret_preleve"), errors="coerce")
        net = pd.to_numeric(row.get("net_pret_verse"), errors="coerce")
        currency_code = str(row.get("currency_code", "")).strip().upper()
        if pd.notna(gross) and pd.notna(interest) and pd.notna(net) and float(gross) > 0:
            suffix = f" {currency_code}" if currency_code else ""
            return (
                f"Prêt brut : {_pdf_number(gross, decimals=2)}{suffix} — "
                f"intérêt/frais : {_pdf_number(interest, decimals=2)}{suffix} — "
                f"net reçu : {_pdf_number(net, decimals=2)}{suffix}"
            )
        return "Prêt net reçu"
    if operation_type in {"Remboursement de credit", "Remboursement avec penalite"}:
        if bool(_customer_internal_savings_repayment_mask(pd.DataFrame([row])).iloc[0]):
            return "Remboursement depuis compte ouvert"
        return "Remboursement depuis compte M-PESA"
    if operation_type == "Transfert DAT vers epargne courante":
        return "Retour capital DAT vers compte ouvert"
    return operation_type or "Mouvement client"


def build_customer_client_statement_view(
    statement: pd.DataFrame,
    *,
    analysis_report: dict[str, Any] | None = None,
    customer_id: object,
    currency: object,
    account_number: object = "",
    entry_account_number: object | None = None,
    output_account_number: object | None = None,
    all_currencies: bool = False,
) -> dict[str, pd.DataFrame]:
    """Construit l'extrait du point de vue client.

    Cette vue ne confond pas le flux net Bisou Bisou avec la position du client :
    la position client suit uniquement l'épargne courante et le DAT, tandis que
    le prêt net reçu et les intérêts/frais de crédit restent séparés.
    """
    analysis_report = analysis_report or {}
    if not isinstance(statement, pd.DataFrame) or statement.empty:
        empty_summary = pd.DataFrame(
            columns=[
                "currency_code",
                "compte_ouvert",
                "compte_bloque",
                "position_epargne_finale",
                "pret_net_recu",
                "remboursements_observes",
                "frais_interets_credit",
            ]
        )
        return {
            "summary": empty_summary,
            "detail": pd.DataFrame(columns=CUSTOMER_CLIENT_STATEMENT_COLUMNS),
        }

    frame = statement.copy()
    frame["currency_code"] = clean_text(
        frame.get("currency_code", pd.Series("", index=frame.index))
    ).str.upper()
    frame["created_at"] = pd.to_datetime(
        frame.get("created_at", pd.Series(pd.NaT, index=frame.index)),
        errors="coerce",
    )
    frame = frame.sort_values(
        ["currency_code", "created_at", "operation_reference"],
        na_position="last",
    ).reset_index(drop=True)

    bisou_view = build_customer_statement_view(
        frame,
        account_number=account_number,
        entry_account_number=entry_account_number,
        output_account_number=output_account_number,
        allow_multiple_currencies=all_currencies,
    )
    financial_summary = build_customer_statement_financial_summary(
        bisou_view,
        analysis_report,
        customer_id=customer_id,
        currency=currency,
        all_currencies=all_currencies,
    )
    savings_by_currency = (
        financial_summary.set_index("currency_code")
        if isinstance(financial_summary, pd.DataFrame)
        and not financial_summary.empty
        and "currency_code" in financial_summary.columns
        else pd.DataFrame()
    )

    repayments = _customer_statement_analysis_frame(
        analysis_report,
        "remboursements_turbo_detail_client",
        customer_id=customer_id,
        currency=currency,
        all_currencies=all_currencies,
    )
    repayment_by_currency = (
        repayments.assign(
            currency_code=clean_text(repayments["currency_code"]).str.upper(),
            montant_paye_observe=pd.to_numeric(
                repayments.get(
                    "montant_paye_observe",
                    pd.Series(0.0, index=repayments.index),
                ),
                errors="coerce",
            ).fillna(0.0),
        )
        .groupby("currency_code")["montant_paye_observe"]
        .sum()
        if isinstance(repayments, pd.DataFrame)
        and not repayments.empty
        and "currency_code" in repayments.columns
        else pd.Series(dtype="float64")
    )

    internal_repayment = _customer_internal_savings_repayment_mask(frame)
    operation_type = clean_text(
        frame.get("type_operation", pd.Series("", index=frame.index))
    )
    sortie_mpesa = pd.to_numeric(
        frame.get("sortie_mpesa", pd.Series(0.0, index=frame.index)),
        errors="coerce",
    ).fillna(0.0)
    entree_mpesa = pd.to_numeric(
        frame.get("entree_mpesa", pd.Series(0.0, index=frame.index)),
        errors="coerce",
    ).fillna(0.0)
    loan_net = pd.to_numeric(
        frame.get("net_pret_verse", pd.Series(0.0, index=frame.index)),
        errors="coerce",
    ).fillna(0.0).where(operation_type.eq("Decaissement de credit"), 0.0)
    loan_fees = pd.to_numeric(
        frame.get("interet_pret_preleve", pd.Series(0.0, index=frame.index)),
        errors="coerce",
    ).fillna(0.0).where(operation_type.eq("Decaissement de credit"), 0.0)
    detail_loan_net = pd.Series(0.0, index=frame.index, dtype="float64")
    detail_loan_fees = pd.Series(0.0, index=frame.index, dtype="float64")
    savings_entries = pd.Series(0.0, index=frame.index, dtype="float64")
    savings_entries = savings_entries.mask(
        operation_type.eq("Sortie M-PESA_Turbo vers epargne"),
        sortie_mpesa,
    )
    savings_outputs = pd.Series(0.0, index=frame.index, dtype="float64")
    savings_outputs = savings_outputs.mask(
        operation_type.eq("Entree M-PESA_Turbo depuis epargne"),
        entree_mpesa,
    )
    savings_outputs = savings_outputs.mask(internal_repayment, sortie_mpesa)
    repayments_paid = pd.Series(0.0, index=frame.index, dtype="float64")
    repayments_paid = repayments_paid.mask(
        operation_type.isin(["Remboursement de credit", "Remboursement avec penalite"]),
        sortie_mpesa.where(internal_repayment, entree_mpesa),
    )

    detail = pd.DataFrame(
        {
            "date": frame["created_at"],
            "reference": frame.get(
                "operation_reference",
                pd.Series("", index=frame.index),
            ),
            "devise": frame["currency_code"],
            "operation": frame.apply(_customer_client_statement_operation_label, axis=1),
            "entree_epargne": savings_entries,
            "sortie_epargne": savings_outputs,
            "pret_net_recu": detail_loan_net,
            "remboursement_paye": repayments_paid,
            "frais_interets": detail_loan_fees,
        }
    )
    keep_detail = (
        detail[[
            "entree_epargne",
            "sortie_epargne",
            "pret_net_recu",
            "remboursement_paye",
            "frais_interets",
        ]]
        .abs()
        .sum(axis=1)
        .gt(0)
    )
    detail = detail.loc[keep_detail].reset_index(drop=True)

    position_values = pd.Series(np.nan, index=detail.index, dtype="float64")
    for currency_code, index in detail.groupby("devise", sort=False).groups.items():
        position_finale = np.nan
        if not savings_by_currency.empty and currency_code in savings_by_currency.index:
            row = savings_by_currency.loc[currency_code]
            if isinstance(row, pd.DataFrame):
                row = row.iloc[-1]
            compte_ouvert = pd.to_numeric(row.get("compte_ouvert"), errors="coerce")
            position_finale = 0.0 if pd.isna(compte_ouvert) else float(compte_ouvert)
        deltas = (
            pd.to_numeric(detail.loc[index, "entree_epargne"], errors="coerce").fillna(0.0)
            - pd.to_numeric(detail.loc[index, "sortie_epargne"], errors="coerce").fillna(0.0)
        )
        opening_position = 0.0 if pd.isna(position_finale) else float(position_finale) - float(deltas.sum())
        position_values.loc[index] = opening_position + deltas.cumsum()
    detail["position_epargne"] = position_values
    detail = detail[CUSTOMER_CLIENT_STATEMENT_COLUMNS]

    currencies = sorted(set(frame["currency_code"].dropna().astype(str)) | set(savings_by_currency.index.astype(str)))
    summary_rows: list[dict[str, object]] = []
    for currency_code in currencies:
        if not currency_code:
            continue
        scoped = frame.loc[frame["currency_code"].eq(currency_code)]
        savings_row = savings_by_currency.loc[currency_code] if currency_code in savings_by_currency.index else pd.Series(dtype=object)
        if isinstance(savings_row, pd.DataFrame):
            savings_row = savings_row.iloc[-1]
        compte_ouvert = pd.to_numeric(savings_row.get("compte_ouvert", np.nan), errors="coerce")
        compte_bloque = pd.to_numeric(savings_row.get("compte_bloque", np.nan), errors="coerce")
        compte_ouvert_value = 0.0 if pd.isna(compte_ouvert) else float(compte_ouvert)
        compte_bloque_value = 0.0 if pd.isna(compte_bloque) else float(compte_bloque)
        scoped_type = clean_text(scoped.get("type_operation", pd.Series("", index=scoped.index)))
        summary_rows.append(
            {
                "currency_code": currency_code,
                "compte_ouvert": compte_ouvert_value,
                "compte_bloque": compte_bloque_value,
                "position_epargne_finale": compte_ouvert_value + compte_bloque_value,
                "pret_net_recu": float(
                    pd.to_numeric(
                        scoped.get("net_pret_verse", pd.Series(0.0, index=scoped.index)),
                        errors="coerce",
                    )
                    .fillna(0.0)
                    .where(scoped_type.eq("Decaissement de credit"), 0.0)
                    .sum()
                ),
                "remboursements_observes": float(repayment_by_currency.get(currency_code, 0.0)),
                "frais_interets_credit": float(
                    pd.to_numeric(
                        scoped.get("interet_pret_preleve", pd.Series(0.0, index=scoped.index)),
                        errors="coerce",
                    )
                    .fillna(0.0)
                    .where(scoped_type.eq("Decaissement de credit"), 0.0)
                    .sum()
                ),
            }
        )
    return {
        "summary": pd.DataFrame(summary_rows),
        "detail": detail,
    }


def _pdf_number(value: Any, *, decimals: int = 0) -> str:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return "-"
    if pd.isna(number):
        return "-"
    return f"{number:,.{decimals}f}".replace(",", " ")
def _retention_svg(monthly: pd.DataFrame) -> str:
    if monthly.empty:
        return ""
    charts: list[str] = []
    colors = {"retention_m1_pct": "#17805c", "retention_90j_pct": "#173f73"}
    labels = {"retention_m1_pct": "Retention M+1", "retention_90j_pct": "Retention 90 jours"}
    for currency, frame in monthly.groupby("currency_code", dropna=False):
        frame = frame.sort_values("periode").reset_index(drop=True)
        if frame[["retention_m1_pct", "retention_90j_pct"]].notna().sum().sum() == 0:
            continue
        width, height = 760, 270
        left, right, top, bottom = 55, 22, 35, 48
        plot_width = width - left - right
        plot_height = height - top - bottom
        count = max(len(frame), 1)

        def x_position(index: int) -> float:
            return left + (plot_width / max(count - 1, 1)) * index

        def y_position(value: float) -> float:
            return top + plot_height * (1 - max(0.0, min(100.0, value)) / 100)

        svg_parts = [
            f'<svg class="retention-chart" viewBox="0 0 {width} {height}" role="img" '
            f'aria-label="Evolution de la retention {escape(str(currency))}">',
            f'<text x="{left}" y="20" class="chart-title">Devise {escape(str(currency))}</text>',
        ]
        for tick in [0, 25, 50, 75, 100]:
            y = y_position(float(tick))
            svg_parts.append(f'<line x1="{left}" y1="{y:.1f}" x2="{width-right}" y2="{y:.1f}" class="grid"/>')
            svg_parts.append(f'<text x="{left-10}" y="{y+4:.1f}" text-anchor="end" class="axis-label">{tick}%</text>')
        label_step = max(1, int(np.ceil(count / 6)))
        for index, month in enumerate(frame["mois"].astype(str)):
            if index % label_step == 0 or index == count - 1:
                x = x_position(index)
                svg_parts.append(f'<text x="{x:.1f}" y="{height-18}" text-anchor="middle" class="axis-label">{escape(month)}</text>')
        for column in ["retention_m1_pct", "retention_90j_pct"]:
            points: list[tuple[float, float, float]] = []
            for index, value in enumerate(pd.to_numeric(frame[column], errors="coerce")):
                if pd.notna(value):
                    points.append((x_position(index), y_position(float(value)), float(value)))
            if points:
                polyline = " ".join(f"{x:.1f},{y:.1f}" for x, y, _ in points)
                svg_parts.append(
                    f'<polyline points="{polyline}" fill="none" stroke="{colors[column]}" stroke-width="3"/>'
                )
                for x, y, value in points:
                    svg_parts.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="4" fill="{colors[column]}"/>')
                    svg_parts.append(
                        f'<text x="{x:.1f}" y="{y-8:.1f}" text-anchor="middle" class="point-label">{value:.0f}%</text>'
                    )
        legend_x = width - 300
        for offset, column in enumerate(["retention_m1_pct", "retention_90j_pct"]):
            x = legend_x + offset * 150
            svg_parts.append(f'<line x1="{x}" y1="18" x2="{x+24}" y2="18" stroke="{colors[column]}" stroke-width="3"/>')
            svg_parts.append(f'<text x="{x+30}" y="22" class="legend">{labels[column]}</text>')
        svg_parts.append("</svg>")
        charts.append("".join(svg_parts))
    return "".join(charts)


def _html_table(frame: pd.DataFrame, columns: list[str], labels: dict[str, str], *, limit: int = 80) -> str:
    present = [column for column in columns if column in frame.columns]
    if frame.empty or not present:
        return '<p class="empty">Aucune donnee disponible.</p>'
    display = frame[present].head(limit).rename(columns=labels).copy()
    for column in display.columns:
        source_name = next((key for key, label in labels.items() if label == column), column)
        if source_name.endswith("_pct"):
            display[column] = pd.to_numeric(display[column], errors="coerce").map(
                lambda value: f"{value:.1f}%" if pd.notna(value) else "-"
            )
        elif any(token in source_name for token in ["montant", "solde", "volume"]):
            display[column] = pd.to_numeric(display[column], errors="coerce").map(
                lambda value: _pdf_number(value, decimals=2)
            )
        else:
            display[column] = display[column].where(display[column].notna(), "-")
    return display.to_html(index=False, escape=True, border=0, classes="report-table")


def _solution_numeric_g2_reconciliation_counts(g2_dat: pd.DataFrame) -> dict[str, int | float]:
    """Resume le rapprochement G2/Solution Numerique sur le seul perimetre controlable."""
    if not isinstance(g2_dat, pd.DataFrame) or g2_dat.empty:
        return {
            "total": 0,
            "matched": 0,
            "exact": 0,
            "with_gap": 0,
            "unmatched": 0,
            "anomalies": 0,
            "rate": 0.0,
        }

    frame = g2_dat.copy()
    if "incluse_synthese" in frame.columns:
        eligible = frame["incluse_synthese"].astype("boolean").fillna(False).astype(bool)
        frame = frame.loc[eligible].copy()
    if frame.empty:
        return {
            "total": 0,
            "matched": 0,
            "exact": 0,
            "with_gap": 0,
            "unmatched": 0,
            "anomalies": 0,
            "rate": 0.0,
        }

    if "statut_rapprochement" in frame.columns:
        status = clean_text(frame["statut_rapprochement"])
        normalized_status = status.apply(normalize_label)
        exact_mask = normalized_status.eq("rapproche exact")
        gap_mask = normalized_status.eq("rapproche avec ecart")
        unmatched_mask = normalized_status.eq("non rapproche")
        comparable = exact_mask | gap_mask | unmatched_mask
        frame = frame.loc[comparable].copy()
        exact = int(exact_mask.loc[frame.index].sum())
        with_gap = int(gap_mask.loc[frame.index].sum())
        unmatched = int(unmatched_mask.loc[frame.index].sum())
        matched = exact + with_gap
    else:
        confirmed = clean_text(
            frame.get("operation_turbo_confirmee", pd.Series("", index=frame.index))
        ).eq("Oui")
        exact = int(confirmed.sum())
        with_gap = 0
        unmatched = int((~confirmed).sum())
        matched = exact

    total = int(len(frame))
    anomalies = int(
        frame.get("est_anomalie", pd.Series(False, index=frame.index))
        .fillna(False)
        .astype(bool)
        .sum()
    )
    rate = 100 * matched / total if total else 0.0
    return {
        "total": total,
        "matched": matched,
        "exact": exact,
        "with_gap": with_gap,
        "unmatched": unmatched,
        "anomalies": anomalies,
        "rate": rate,
    }


def _g2_executive_context(report: dict[str, Any]) -> dict[str, Any]:
    source_label = str(report.get("analysis_source_label", "G2") or "G2")
    analysis_mode_label = str(report.get("analysis_mode_label", "") or "")
    analysis_mode_normalized = normalize_label(analysis_mode_label)
    source_label_normalized = normalize_label(source_label)
    turbo_only = (
        source_label_normalized == "turbo"
        or source_label.casefold().startswith("solution num")
    )
    solution_numeric_with_g2 = (
        turbo_only
        and "g2" in analysis_mode_normalized
        and "seule" not in analysis_mode_normalized
    )
    daily_pivot = report.get("rapport_journalier_pivot", pd.DataFrame())
    g2_dat = report.get("g2_dat", pd.DataFrame())
    monthly = report.get("retention_mensuelle", pd.DataFrame())
    transaction_detail = report.get("rapport_journalier_detail", pd.DataFrame())
    transactions_by_day = report.get("transactions_par_jour", pd.DataFrame())
    transactions_by_weekday = report.get("transactions_par_jour_semaine", pd.DataFrame())
    transactions_by_hour = report.get("transactions_par_heure", pd.DataFrame())
    status_summary = report.get("statuts_g2", pd.DataFrame())

    if not isinstance(transaction_detail, pd.DataFrame):
        transaction_detail = pd.DataFrame()
    eligible_transaction_detail = transaction_detail.copy()
    if (
        not eligible_transaction_detail.empty
        and "incluse_synthese" in eligible_transaction_detail.columns
    ):
        eligible_mask = (
            eligible_transaction_detail["incluse_synthese"]
            .astype("boolean")
            .fillna(False)
            .astype(bool)
        )
        eligible_transaction_detail = eligible_transaction_detail.loc[eligible_mask].copy()
    if not isinstance(transactions_by_day, pd.DataFrame):
        transactions_by_day = pd.DataFrame()
    if not isinstance(transactions_by_weekday, pd.DataFrame):
        transactions_by_weekday = pd.DataFrame()
    if not isinstance(transactions_by_hour, pd.DataFrame):
        transactions_by_hour = pd.DataFrame()
    if not isinstance(status_summary, pd.DataFrame):
        status_summary = pd.DataFrame()
    if status_summary.empty and not transaction_detail.empty:
        status_summary = build_g2_transaction_status_summary(transaction_detail)
    if (
        transactions_by_day.empty
        or transactions_by_weekday.empty
        or transactions_by_hour.empty
    ) and not transaction_detail.empty:
        time_report = build_g2_transaction_time_analysis(transaction_detail)
        transactions_by_day = time_report["par_jour"]
        transactions_by_weekday = time_report["par_jour_semaine"]
        transactions_by_hour = time_report["par_heure"]

    active_items: list[str] = []
    retention_items: list[str] = []
    latest_retention_rows: list[dict[str, object]] = []
    chart_blocks: list[pd.DataFrame] = []
    if not eligible_transaction_detail.empty:
        activity = eligible_transaction_detail.copy()
        activity["currency_code"] = clean_text(
            activity.get("currency_code", pd.Series("", index=activity.index))
        ).str.upper().replace("", "SANS DEVISE")
        phone_values = normalize_phone(
            activity.get("phone_prefixe", pd.Series(pd.NA, index=activity.index, dtype="string"))
        )
        if phone_values.notna().sum() == 0 and "opposite_party" in activity.columns:
            phone_values = normalize_phone(
                _extract_phone_from_opposite_party(activity["opposite_party"])
            )
        activity["__client_phone"] = phone_values
        for currency, frame in activity.groupby("currency_code", dropna=False, sort=True):
            transaction_count = int(len(frame))
            client_count = int(frame["__client_phone"].dropna().nunique())
            operation_status = (
                "operation(s) comptabilisee(s) dans la Solution Numérique"
                if turbo_only
                else "transaction(s) Completed"
            )
            active_items.append(
                f"{currency} : {transaction_count} {operation_status}, "
                f"{client_count} client(s) distinct(s)"
            )
    if not monthly.empty:
        for currency, frame in monthly.groupby("currency_code", dropna=False):
            frame = frame.sort_values("periode")
            eligible_m1 = frame.dropna(subset=["retention_m1_pct"])
            eligible_90 = frame.dropna(subset=["retention_90j_pct"])
            m1_text = f"{eligible_m1.iloc[-1]['retention_m1_pct']:.1f}%" if not eligible_m1.empty else "non calculable"
            day90_text = f"{eligible_90.iloc[-1]['retention_90j_pct']:.1f}%" if not eligible_90.empty else "non calculable"
            retention_items.append(f"{currency} : M+1 {m1_text}, 90 jours {day90_text}")
            latest_retention_rows.append(
                {
                    "Devise": currency,
                    "Retention M+1": m1_text,
                    "Retention 90 jours": day90_text,
                }
            )
            eligible_periods = int(frame[["retention_m1_pct", "retention_90j_pct"]].notna().any(axis=1).sum())
            if eligible_periods >= 6:
                chart_blocks.append(frame)

    flow_items: list[str] = []
    if not daily_pivot.empty:
        for _, row in daily_pivot.iterrows():
            currency = row.get("currency_code", "-")
            flow_items.append(
                f"{currency} : entrees {_pdf_number(row.get('montant_total_entrees'), decimals=2)}, "
                f"sorties {_pdf_number(row.get('montant_total_sorties'), decimals=2)}, "
                f"net {_pdf_number(row.get('solde_net_flux'), decimals=2)}"
            )

    status_text = ""
    if not status_summary.empty and "nombre_transactions" in status_summary.columns:
        status_counts = pd.to_numeric(status_summary["nombre_transactions"], errors="coerce").fillna(0)
        included = clean_text(
            status_summary.get("prise_en_compte_analyse", pd.Series("", index=status_summary.index))
        ).eq("Oui")
        completed_count = int(status_counts.loc[included].sum())
        control_only_count = int(status_counts.loc[~included].sum())
        if turbo_only:
            status_text = (
                f"{completed_count} operation(s) comptabilisee(s) dans la Solution Numérique incluse(s) dans les analyses; "
                f"{control_only_count} operation(s) exclue(s) du perimetre analytique. "
                "Le statut de transaction G2 n'est pas disponible."
            )
        else:
            status_text = (
                f"{completed_count} transaction(s) Completed incluse(s) dans les analyses; "
                f"{control_only_count} transaction(s) d'autres statuts conservee(s) pour controle uniquement."
            )

    time_items: list[str] = []
    total_transactions = 0
    if not transactions_by_hour.empty and "nombre_transactions" in transactions_by_hour.columns:
        hourly_totals = (
            transactions_by_hour.groupby(["heure_num", "heure"], as_index=False, dropna=False)["nombre_transactions"]
            .sum()
            .sort_values("heure_num")
            .reset_index(drop=True)
        )
        hourly_totals["nombre_transactions"] = pd.to_numeric(
            hourly_totals["nombre_transactions"], errors="coerce"
        ).fillna(0)
        total_transactions = int(hourly_totals["nombre_transactions"].sum())
        if total_transactions > 0:
            busiest_hour = hourly_totals.loc[hourly_totals["nombre_transactions"].idxmax()]
            busiest_hour_count = int(busiest_hour["nombre_transactions"])
            busiest_hour_share = 100 * busiest_hour_count / total_transactions
            time_items.append(
                f"Heure la plus fréquente : {busiest_hour.get('heure', '-')}, "
                f"avec {busiest_hour_count} transaction(s), soit {busiest_hour_share:.1f}% du volume"
            )

    analysis_start = pd.to_datetime(report.get("analysis_date_start"), errors="coerce")
    analysis_end = pd.to_datetime(report.get("analysis_date_end"), errors="coerce")
    if pd.notna(analysis_start) and pd.notna(analysis_end):
        spans_multiple_days = analysis_end.normalize() > analysis_start.normalize()
    else:
        detail_dates = pd.to_datetime(
            eligible_transaction_detail.get("date", pd.Series(dtype="datetime64[ns]")), errors="coerce"
        ).dropna()
        spans_multiple_days = detail_dates.dt.normalize().nunique() > 1
        if not spans_multiple_days and not transactions_by_day.empty:
            reported_dates = pd.to_datetime(
                transactions_by_day.get(
                    "date_transaction", pd.Series(dtype="datetime64[ns]")
                ),
                errors="coerce",
            ).dropna()
            spans_multiple_days = reported_dates.dt.normalize().nunique() > 1

    if (
        spans_multiple_days
        and not transactions_by_weekday.empty
        and "nombre_transactions" in transactions_by_weekday.columns
    ):
        weekday_totals = (
            transactions_by_weekday.groupby(
                ["jour_semaine_num", "jour_semaine"], as_index=False, dropna=False
            )["nombre_transactions"]
            .sum()
            .sort_values("jour_semaine_num")
            .reset_index(drop=True)
        )
        weekday_totals["nombre_transactions"] = pd.to_numeric(
            weekday_totals["nombre_transactions"], errors="coerce"
        ).fillna(0)
        weekday_total = int(weekday_totals["nombre_transactions"].sum())
        if weekday_total > 0:
            busiest_weekday = weekday_totals.loc[weekday_totals["nombre_transactions"].idxmax()]
            busiest_weekday_count = int(busiest_weekday["nombre_transactions"])
            busiest_weekday_share = 100 * busiest_weekday_count / weekday_total
            time_items.append(
                f"Jour de semaine le plus actif : {busiest_weekday.get('jour_semaine', '-')}, "
                f"avec {busiest_weekday_count} transaction(s), soit {busiest_weekday_share:.1f}% du volume"
            )

    control_text = ""
    if turbo_only:
        if solution_numeric_with_g2:
            control_prefix = (
                "Mode Solution Numérique + rapport G2 : les montants et la periode restent pilotes par la Solution Numérique. "
                "G2 enrichit l'identite client et sert de preuve de controle lorsque la couverture temporelle le permet."
            )
            if not g2_dat.empty:
                counts = _solution_numeric_g2_reconciliation_counts(g2_dat)
                total = int(counts["total"])
                matched = int(counts["matched"])
                exact = int(counts["exact"])
                with_gap = int(counts["with_gap"])
                unmatched = int(counts["unmatched"])
                anomalies = int(counts["anomalies"])
                rate = float(counts["rate"])
                control_text = (
                    f"{matched}/{total} operation(s) rapprochee(s), soit {rate:.1f}%; "
                    f"{exact} exact(s), {with_gap} avec ecart, "
                    f"{unmatched} non rapprochee(s), {anomalies} anomalie(s). "
                    f"{control_prefix}"
                )
            else:
                control_text = (
                    f"{control_prefix} Aucun mouvement eligible n'a ete trouve dans le perimetre analyse."
                )
        else:
            control_text = (
                "Mode Solution Numérique seule : les controles croises rapport G2/Solution Numérique sont non applicables. "
                "Les depots sont regroupes par ref_no et les retraits M-PESA par reference_id + created_at."
            )
    elif not g2_dat.empty:
        if "statut_rapprochement" in g2_dat.columns:
            reference_status = g2_dat["statut_rapprochement"].astype("string").fillna("")
            exact = int(reference_status.eq("Rapproche exact").sum())
            with_gap = int(reference_status.eq("Rapproche avec ecart").sum())
            unmatched = int(reference_status.eq("Non rapproche").sum())
            anomalies = int(
                g2_dat.get("est_anomalie", pd.Series(False, index=g2_dat.index))
                .fillna(False)
                .astype(bool)
                .sum()
            )
            total = int(len(g2_dat))
            rate = 100 * exact / total if total else 0
            control_text = (
                f"Rapprochement Receipt No/ref_no : {exact}/{total} exact(s), soit {rate:.1f}%; "
                f"{with_gap} avec ecart, {unmatched} non rapproche(s), {anomalies} anomalie(s) au total."
            )
        else:
            status = g2_dat.get("statut_rapprochement_dat", pd.Series("", index=g2_dat.index)).astype("string")
            dat_absent = bool(status.str.contains("Fichier DAT absent", case=False, na=False).all())
            if dat_absent:
                control_text = "Rapprochement G2/DAT non evalue : fichier DAT non charge."
            else:
                matched = int(
                    g2_dat.get("customer_id_dat", pd.Series(dtype="string"))
                    .astype("string").fillna("").ne("").sum()
                )
                total = int(len(g2_dat))
                rate = 100 * matched / total if total else 0
                control_text = f"Rapprochement G2/DAT : {matched}/{total} entree(s), soit {rate:.1f}%."

    has_retention = bool(
        not monthly.empty
        and monthly[["retention_m1_pct", "retention_90j_pct"]].notna().any().any()
    )
    attention_text = (
        "Les mois les plus recents restent provisoires tant que leur fenetre de suivi n'est pas terminee."
        if has_retention
        else "La fidelisation M+1 et a 90 jours exige un historique couvrant les mois suivants."
    )
    return {
        "active_text": "; ".join(active_items) or "Aucune transaction Completed dans le perimetre filtre.",
        "flow_text": "; ".join(flow_items) or "Aucun flux disponible.",
        "status_text": status_text,
        "time_text": "; ".join(time_items),
        "retention_text": "; ".join(retention_items) or "Non calculable sur la periode chargee.",
        "control_text": control_text,
        "attention_text": attention_text,
        "has_retention": has_retention,
        "latest_retention": pd.DataFrame(latest_retention_rows),
        "chart_monthly": concat_frames_stable(chart_blocks) if chart_blocks else pd.DataFrame(),
    }


def _g2_report_period_boundary_texts(report: dict[str, Any]) -> tuple[str, str]:
    """Formate séparément les bornes de début et de fin du rapport G2/DAT."""
    start = pd.to_datetime(report.get("analysis_date_start"), errors="coerce")
    end = pd.to_datetime(report.get("analysis_date_end"), errors="coerce")
    detail = report.get("rapport_journalier_detail", pd.DataFrame())
    if (
        (pd.isna(start) or pd.isna(end))
        and isinstance(detail, pd.DataFrame)
        and not detail.empty
    ):
        observed = pd.to_datetime(
            detail.get("date", pd.Series(pd.NaT, index=detail.index)),
            errors="coerce",
        ).dropna()
        if not observed.empty:
            if pd.isna(start):
                start = observed.min()
            if pd.isna(end):
                end = observed.max()

    def format_boundary(value: object) -> str:
        parsed = pd.to_datetime(value, errors="coerce")
        return (
            f"{parsed:%d/%m/%Y %H:%M:%S}"
            if pd.notna(parsed)
            else "Non disponible"
        )

    return format_boundary(start), format_boundary(end)


