def _find_pdf_browser() -> Path | None:
    candidates = [
        shutil.which("msedge"),
        shutil.which("chrome"),
        shutil.which("chromium"),
        r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
        r"C:\Program Files\Microsoft\Edge\Application\msedge.exe",
        r"C:\Program Files\Google\Chrome\Application\chrome.exe",
        r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe",
        "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
        "/usr/bin/google-chrome",
        "/usr/bin/chromium",
    ]
    for candidate in candidates:
        if candidate and Path(candidate).is_file():
            return Path(candidate)
    return None


def create_g2_dat_pdf(
    report: dict[str, Any],
    *,
    period_text: str,
    direction_label: str,
) -> bytes:
    """Convertit le rapport G2/DAT statique en PDF via Edge/Chrome headless."""
    browser = _find_pdf_browser()
    if browser is None:
        raise RuntimeError("Microsoft Edge, Google Chrome ou Chromium est requis pour generer le PDF.")
    html_content = build_g2_dat_pdf_html(
        report,
        period_text=period_text,
        direction_label=direction_label,
    )
    with tempfile.TemporaryDirectory(prefix="mpesa_g2_pdf_") as temp_dir:
        temp_path = Path(temp_dir)
        html_path = temp_path / "rapport_g2_dat.html"
        pdf_path = temp_path / "rapport_g2_dat.pdf"
        html_path.write_text(html_content, encoding="utf-8")
        command = [
            str(browser),
            "--headless=new",
            "--disable-gpu",
            "--no-first-run",
            "--no-default-browser-check",
            "--no-pdf-header-footer",
            "--run-all-compositor-stages-before-draw",
            f"--user-data-dir={temp_path / 'browser_profile'}",
            f"--print-to-pdf={pdf_path}",
            html_path.as_uri(),
        ]
        creation_flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        completed = subprocess.run(
            command,
            capture_output=True,
            text=True,
            timeout=90,
            creationflags=creation_flags,
            check=False,
        )
        if completed.returncode != 0 or not pdf_path.exists() or pdf_path.stat().st_size == 0:
            message = completed.stderr.strip() or completed.stdout.strip() or "conversion sans fichier de sortie"
            raise RuntimeError(f"Impossible de generer le PDF G2/DAT : {message[:300]}")
        return pdf_path.read_bytes()


def create_customer_statement_word(
    statement: pd.DataFrame,
    *,
    analysis_report: dict[str, pd.DataFrame] | None = None,
    customer_id: object,
    customer_name: object = "",
    telephone: object = "",
    currency: object,
    account_number: object = "",
    entry_account_number: object | None = None,
    output_account_number: object | None = None,
    period_start: object | None = None,
    period_end: object | None = None,
    generated_at: pd.Timestamp | None = None,
    minimal: bool = False,
) -> bytes:
    """Genere un extrait Word CDF, USD ou ALL sans sommer les devises."""
    try:
        from docx import Document
        from docx.enum.table import WD_CELL_VERTICAL_ALIGNMENT, WD_TABLE_ALIGNMENT
        from docx.enum.text import WD_ALIGN_PARAGRAPH
        from docx.oxml import OxmlElement
        from docx.oxml.ns import qn
        from docx.shared import Cm, Pt, RGBColor
    except ImportError as exc:
        raise RuntimeError("La dependance python-docx est requise pour generer l'extrait Word.") from exc

    if not isinstance(statement, pd.DataFrame) or statement.empty:
        raise ValueError("Aucune operation filtree n'est disponible pour l'extrait Word.")
    currency_text = str(currency).strip().upper()
    all_currencies = currency_text in {"ALL", "TOUTES", "TOUS", "CDF + USD"}
    frame = statement.copy()
    frame_currency = clean_text(
        frame.get("currency_code", pd.Series("", index=frame.index))
    ).str.upper()
    if not all_currencies:
        frame = frame.loc[frame_currency.eq(currency_text)].copy()
    if frame.empty:
        raise ValueError(f"Aucune operation {currency_text or 'sans devise'} n'est disponible pour l'extrait Word.")

    view = build_customer_statement_view(
        frame,
        account_number=account_number,
        entry_account_number=entry_account_number,
        output_account_number=output_account_number,
        allow_multiple_currencies=all_currencies,
    )
    transactions = view["transactions"]
    detail_transactions = _customer_statement_export_detail(
        transactions,
        frame,
        view["summary_by_currency"],
        entry_account_number=entry_account_number,
        output_account_number=output_account_number,
    )
    customer_id_text = str(customer_id).strip() or view["customer_id"] or "Non disponible"
    customer_name_text = str(customer_name).strip() or view["customer_name"] or "Nom non disponible"
    telephone_text = str(telephone).strip() or view["telephone"] or "Non disponible"
    observed_currencies = sorted(
        value for value in transactions["devise"].dropna().astype(str).unique().tolist() if value
    )
    currency_label = (
        f"ALL ({', '.join(observed_currencies)})"
        if all_currencies
        else currency_text or view["currency"]
    )
    generated_at = generated_at if generated_at is not None else pd.Timestamp.now()
    analysis_report = analysis_report or {}
    detail_transactions = build_customer_statement_detail_with_covered_operations(
        detail_transactions,
        analysis_report,
        customer_id=customer_id_text,
        currency=currency_text,
        entry_account_number=entry_account_number,
        all_currencies=all_currencies,
    )
    view_for_summary = dict(view)
    view_for_summary["detail_transactions"] = detail_transactions
    dat_rate_label = _customer_statement_dat_rate_label(
        analysis_report,
        customer_id=customer_id_text,
        currency=currency_text,
        all_currencies=all_currencies,
    )

    observed_dates = pd.to_datetime(transactions["date"], errors="coerce").dropna()

    def report_date(value: object | None, fallback: pd.Timestamp | None) -> str:
        parsed = pd.to_datetime(value, errors="coerce") if value is not None else pd.NaT
        if pd.isna(parsed):
            parsed = fallback
        return f"{parsed:%d/%m/%Y}" if parsed is not None and pd.notna(parsed) else "Non disponible"

    first_observed = observed_dates.min() if not observed_dates.empty else None
    last_observed = observed_dates.max() if not observed_dates.empty else None
    start_text = report_date(period_start, first_observed)
    end_text = report_date(period_end, last_observed)
    decimals = 0 if currency_text == "CDF" else 2

    document = Document()
    section = document.sections[0]
    section.top_margin = Cm(1.0)
    section.bottom_margin = Cm(1.0)
    section.left_margin = Cm(2.0)
    section.right_margin = Cm(2.0)

    styles = document.styles
    styles["Normal"].font.name = "Aptos"
    styles["Normal"].font.size = Pt(8.5)
    styles["Title"].font.name = "Aptos Display"
    styles["Title"].font.size = Pt(16)
    styles["Title"].font.color.rgb = RGBColor(24, 41, 58)

    def set_cell_shading(cell: Any, fill: str) -> None:
        cell_properties = cell._tc.get_or_add_tcPr()
        shading = OxmlElement("w:shd")
        shading.set(qn("w:fill"), fill)
        cell_properties.append(shading)

    def set_repeat_header(row: Any) -> None:
        row_properties = row._tr.get_or_add_trPr()
        repeat_header = OxmlElement("w:tblHeader")
        repeat_header.set(qn("w:val"), "true")
        row_properties.append(repeat_header)

    header = document.add_table(rows=2, cols=2)
    header.alignment = WD_TABLE_ALIGNMENT.CENTER
    header.autofit = False
    brand_cell = header.cell(0, 0).merge(header.cell(1, 0))
    brand_cell.width = Cm(9.5)
    brand_cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
    brand_paragraph = brand_cell.paragraphs[0]
    brand_paragraph.paragraph_format.space_after = Pt(0)
    if CUSTOMER_STATEMENT_LOGO_PATH.is_file():
        try:
            brand_paragraph.add_run().add_picture(
                str(CUSTOMER_STATEMENT_LOGO_PATH), width=Cm(4.6)
            )
        except (OSError, ValueError):
            brand_run = brand_paragraph.add_run("IMF Microfinance Bisou Bisou")
            brand_run.bold = True
            brand_run.font.size = Pt(16)
    else:
        brand_run = brand_paragraph.add_run("IMF Microfinance Bisou Bisou")
        brand_run.bold = True
        brand_run.font.size = Pt(16)

    criteria_title = header.cell(0, 1)
    criteria_title.width = Cm(8.5)
    criteria_title.text = "Critères"
    criteria_title.paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
    set_cell_shading(criteria_title, "1F2937")
    for run in criteria_title.paragraphs[0].runs:
        run.bold = True
        run.font.size = Pt(10)
        run.font.color.rgb = RGBColor(255, 255, 255)

    criteria_cell = header.cell(1, 1)
    criteria_cell.width = Cm(8.5)
    criteria = criteria_cell.add_table(rows=6, cols=2)
    criteria.autofit = False
    criteria_rows = [
        ("Date du :", start_text),
        ("Au :", end_text),
        ("Numéro du client :", customer_id_text),
        ("Téléphone :", telephone_text),
        ("Devise :", currency_label),
        ("Taux annuel DAT :", dat_rate_label),
    ]
    for row_index, (label, value) in enumerate(criteria_rows):
        criteria.cell(row_index, 0).text = label
        criteria.cell(row_index, 1).text = value
        criteria.cell(row_index, 0).width = Cm(3.8)
        criteria.cell(row_index, 1).width = Cm(4.7)
        for run in criteria.cell(row_index, 0).paragraphs[0].runs:
            run.bold = True
            run.font.size = Pt(8)
        for run in criteria.cell(row_index, 1).paragraphs[0].runs:
            run.font.size = Pt(8)
    criteria_cell.paragraphs[0].paragraph_format.space_after = Pt(0)

    title = document.add_paragraph(style="Title")
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER
    title.paragraph_format.space_before = Pt(5)
    title.paragraph_format.space_after = Pt(6)
    customer_name_available = (
        not _is_empty_text(customer_name_text)
        and normalize_label(customer_name_text)
        not in {"non disponible", "nom non disponible"}
    )
    title_parts = [
        "Extrait minimal de compte" if minimal else "Extrait de compte",
        telephone_text,
    ]
    if customer_name_available:
        title_parts.append(customer_name_text.upper())
    title_parts.append(currency_label)
    title.add_run(" - ".join(title_parts))

    financial_title = document.add_paragraph()
    financial_title.paragraph_format.space_before = Pt(5)
    financial_title.paragraph_format.space_after = Pt(2)
    financial_title_run = financial_title.add_run("Synthèse financière par devise")
    financial_title_run.bold = True
    financial_title_run.font.size = Pt(10)
    financial_title_run.font.color.rgb = RGBColor(24, 63, 91)
    financial_summary = build_customer_statement_financial_summary(
        view_for_summary,
        analysis_report,
        customer_id=customer_id_text,
        currency=currency_text,
        all_currencies=all_currencies,
    )
    detail_transactions = build_customer_statement_detail_with_opening_balance(
        detail_transactions,
        financial_summary,
    )
    financial_headers = [
        "Devise",
        "Ouverture",
        "Entrée",
        "Sorties",
        "Cloture",
        "Compte ouvert",
        "Compte bloqué",
    ]
    summary = document.add_table(rows=1, cols=len(financial_headers))
    summary.style = "Table Grid"
    summary.alignment = WD_TABLE_ALIGNMENT.CENTER
    summary.autofit = False
    set_repeat_header(summary.rows[0])
    for index, label in enumerate(financial_headers):
        summary.cell(0, index).text = label
        summary.cell(0, index).width = Cm(
            [1.7, 2.2, 2.2, 2.2, 2.2, 2.3, 2.3][index]
        )
        set_cell_shading(summary.cell(0, index), "DCE6F1")
        summary.cell(0, index).paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
        for run in summary.cell(0, index).paragraphs[0].runs:
            run.bold = True
            run.font.size = Pt(7.2)
    for _, summary_row in financial_summary.iterrows():
        cells = summary.add_row().cells
        row_currency = str(summary_row.get("currency_code", ""))
        row_decimals = 0 if row_currency == "CDF" else 2
        values = [
            row_currency,
            _pdf_number(summary_row.get("opening_amount"), decimals=row_decimals),
            _pdf_number(summary_row.get("total_entries"), decimals=row_decimals),
            _pdf_number(summary_row.get("total_outputs"), decimals=row_decimals),
            _pdf_number(summary_row.get("closing_amount"), decimals=row_decimals),
            _pdf_number(summary_row.get("compte_ouvert"), decimals=row_decimals),
            _pdf_number(summary_row.get("compte_bloque"), decimals=row_decimals),
        ]
        for index, value in enumerate(values):
            cells[index].text = value
            cells[index].width = Cm(
                [1.7, 2.2, 2.2, 2.2, 2.2, 2.3, 2.3][index]
            )
            cells[index].paragraphs[0].alignment = (
                WD_ALIGN_PARAGRAPH.CENTER if index == 0 else WD_ALIGN_PARAGRAPH.RIGHT
            )
            for run in cells[index].paragraphs[0].runs:
                run.font.size = Pt(6.8)

    def analysis_frame(key: str) -> pd.DataFrame:
        return _customer_statement_analysis_frame(
            analysis_report,
            key,
            customer_id=customer_id_text,
            currency=currency_text,
            all_currencies=all_currencies,
        )

    def add_analysis_title(text: str) -> None:
        paragraph = document.add_paragraph()
        paragraph.paragraph_format.space_before = Pt(5)
        paragraph.paragraph_format.space_after = Pt(2)
        run = paragraph.add_run(text)
        run.bold = True
        run.font.size = Pt(10)
        run.font.color.rgb = RGBColor(24, 63, 91)

    def add_analysis_table(
        source: pd.DataFrame,
        columns: list[str],
        labels: dict[str, str],
        widths: list[float] | None = None,
    ) -> None:
        present = [column for column in columns if column in source.columns]
        if source.empty or not present:
            return
        selected_widths = {
            column: widths[columns.index(column)]
            for column in present
        } if widths is not None else {}
        analysis_table = document.add_table(rows=1, cols=len(present))
        analysis_table.style = "Table Grid"
        analysis_table.alignment = WD_TABLE_ALIGNMENT.CENTER
        analysis_table.autofit = widths is None
        set_repeat_header(analysis_table.rows[0])
        for index, column in enumerate(present):
            cell = analysis_table.rows[0].cells[index]
            cell.text = labels.get(column, column)
            if column in selected_widths:
                cell.width = Cm(selected_widths[column])
            set_cell_shading(cell, "DCE6F1")
            cell.paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
            for run in cell.paragraphs[0].runs:
                run.bold = True
                run.font.size = Pt(7.2)
        for _, analysis_row in source.iterrows():
            cells = analysis_table.add_row().cells
            row_currency = str(analysis_row.get("currency_code", currency_text)).upper()
            row_decimals = 0 if row_currency == "CDF" else 2
            for index, column in enumerate(present):
                value = analysis_row.get(column)
                if column in {
                    "created_at",
                    "premiere_operation",
                    "derniere_operation",
                    "date_derniere_ecriture",
                    "date_approved",
                    "maturity_date",
                    "date_situation",
                    "date_ecriture_turbo",
                    "date_creation_dat",
                    "date_fin_dat",
                    "due_date",
                }:
                    parsed = pd.to_datetime(value, errors="coerce")
                    text = f"{parsed:%d/%m/%Y %H:%M}" if pd.notna(parsed) else "-"
                elif column.endswith("_pct"):
                    numeric_value = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
                    text = f"{numeric_value:.1f}%" if pd.notna(numeric_value) else "-"
                elif any(
                    token in column
                    for token in [
                        "montant", "solde", "balance", "ecart", "interet", "principal",
                        "penalite", "dette", "revenu", "intervalle", "inactivite",
                    ]
                ):
                    text = _pdf_number(value, decimals=row_decimals)
                else:
                    text = "-" if _is_empty_text(value) else str(value)
                cells[index].text = text
                if column in selected_widths:
                    cells[index].width = Cm(selected_widths[column])
                cells[index].vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
                for paragraph in cells[index].paragraphs:
                    paragraph.paragraph_format.space_after = Pt(0)
                    if any(
                        token in column
                        for token in ["montant", "solde", "balance", "ecart", "interet", "principal", "penalite", "dette", "revenu"]
                    ):
                        paragraph.alignment = WD_ALIGN_PARAGRAPH.RIGHT
                    for run in paragraph.runs:
                        run.font.size = Pt(6.8)

    statement_element_summary = analysis_frame("elements_extrait_client_synthese")
    if not minimal and not statement_element_summary.empty:
        add_analysis_title("Éléments couverts par l'extrait client")
        add_analysis_table(
            statement_element_summary,
            [
                "type_element_extrait",
                "currency_code",
                "nombre_operations",
                "montant_total_observe",
                "statut_periode",
            ],
            {
                "type_element_extrait": "Élément",
                "currency_code": "Devise",
                "nombre_operations": "Opérations",
                "montant_total_observe": "Montant observé",
                "statut_periode": "Situation sur la période",
            },
            [7.5, 1.5, 1.8, 3.0, 4.2],
        )

    active_dat = analysis_frame("dat_en_cours_client")
    if not minimal and not active_dat.empty:
        situation_dates = pd.to_datetime(active_dat.get("date_situation"), errors="coerce").dropna()
        dat_title = "DAT en cours"
        if not situation_dates.empty:
            dat_title += f" - situation au {situation_dates.max():%d/%m/%Y}"
        add_analysis_title(dat_title)
        add_analysis_table(
            active_dat,
            [
                "savings_id",
                "date_approved",
                "maturity_date",
                "jours_avant_echeance",
                "currency_code",
                "balance",
                "situation_dat_client",
                "capital_plus_interet_estime",
            ],
            {
                "savings_id": "DAT",
                "date_approved": "Souscription",
                "maturity_date": "Échéance",
                "jours_avant_echeance": "Jours restants",
                "currency_code": "Devise",
                "balance": "Capital bloqué",
                "situation_dat_client": "Situation",
                "capital_plus_interet_estime": "Capital + intérêt estimé",
            },
            [2.2, 2.1, 2.1, 1.4, 1.3, 2.3, 3.0, 3.2],
        )

    repayments = analysis_frame("remboursements_turbo_detail_client")
    if not minimal and not repayments.empty:
        add_analysis_title("Remboursements observés")
        add_analysis_table(
            repayments,
            [
                "created_at", "event_reference", "currency_code", "montant_paye_observe",
                "interet_observe", "origine_remboursement_observee",
                "penalite_observee",
            ],
            {
                "created_at": "Date",
                "event_reference": "Référence",
                "currency_code": "Devise",
                "montant_paye_observe": "Montant payé",
                "interet_observe": "Intérêts",
                "origine_remboursement_observee": "Origine du paiement",
                "penalite_observee": "Pénalités",
            },
            [2.7, 3.0, 1.3, 2.4, 2.2, 4.4, 2.2],
        )

    upcoming_repayments = analysis_frame("prochains_remboursements_client")
    if not minimal and not upcoming_repayments.empty:
        add_analysis_title("Prochains remboursements sur la période")
        add_analysis_table(
            upcoming_repayments,
            [
                "due_date",
                "loan_id",
                "currency_code",
                "montant_a_rembourser",
                "outstanding_principle",
                "outstanding_interest",
                "outstanding_penalty_fees",
                "status_name",
            ],
            {
                "due_date": "Date prévue",
                "loan_id": "Crédit",
                "currency_code": "Devise",
                "montant_a_rembourser": "Montant à rembourser",
                "outstanding_principle": "Principal",
                "outstanding_interest": "Intérêts",
                "outstanding_penalty_fees": "Pénalités",
                "status_name": "Statut",
            },
            [2.5, 2.6, 1.2, 2.6, 2.2, 2.0, 2.0, 3.0],
        )

    internal = analysis_frame("mouvements_internes_turbo")
    if not minimal and not internal.empty:
        add_analysis_title("Retours du capital mis en DAT")
        add_analysis_table(
            internal,
            [
                "date_creation_dat",
                "date_fin_dat",
                "event_reference",
                "currency_code",
                "transfert_dat_sortie",
                "transfert_epargne_entree",
                "descriptions",
            ],
            {
                "date_creation_dat": "Création du DAT",
                "date_fin_dat": "Fin du DAT",
                "event_reference": "Référence",
                "currency_code": "Devise",
                "transfert_dat_sortie": "Capital DAT restitué",
                "transfert_epargne_entree": "Entrée compte ouvert",
                "descriptions": "Description",
            },
            [2.4, 2.4, 2.4, 1.1, 2.3, 2.3, 5.2],
        )

    dat_interest_entries = analysis_frame("interets_dat_credites_client")
    if not minimal and not dat_interest_entries.empty:
        add_analysis_title("Entrées des intérêts du capital mis en DAT")
        add_analysis_table(
            dat_interest_entries,
            [
                "maturity_date",
                "savings_id",
                "currency_code",
                "capital_place",
                "interet_client_constate",
                "montant_echeance_client",
            ],
            {
                "maturity_date": "Échéance",
                "savings_id": "DAT",
                "currency_code": "Devise",
                "capital_place": "Capital placé",
                "interet_client_constate": "Intérêt client",
                "montant_echeance_client": "Capital + intérêt",
            },
            [2.6, 3.2, 1.2, 3.2, 3.4, 3.8],
        )

    add_analysis_title("Detail des transactions")
    table = document.add_table(rows=1, cols=len(CUSTOMER_STATEMENT_COLUMNS))
    table.style = "Table Grid"
    table.alignment = WD_TABLE_ALIGNMENT.CENTER
    table.autofit = False
    labels = {
        "date": "Date",
        "compte": "Compte",
        "receipt_no": "Référence",
        "devise": "Devise",
        "description": "Description",
        "entree": "Entrées",
        "sortie": "Sorties",
        "solde": "Solde",
    }
    widths = {
        "date": 1.8,
        "compte": 1.1,
        "receipt_no": 2.3,
        "devise": 1.1,
        "description": 5.4,
        "entree": 1.7,
        "sortie": 1.7,
        "solde": 2.4,
    }
    set_repeat_header(table.rows[0])
    for index, column in enumerate(CUSTOMER_STATEMENT_COLUMNS):
        cell = table.rows[0].cells[index]
        cell.text = labels[column]
        cell.width = Cm(widths[column])
        cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
        cell.paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
        set_cell_shading(cell, "1F2937")
        for run in cell.paragraphs[0].runs:
            run.bold = True
            run.font.size = Pt(6.8)
            run.font.color.rgb = RGBColor(255, 255, 255)

    for _, row in detail_transactions.iterrows():
        cells = table.add_row().cells
        for index, column in enumerate(CUSTOMER_STATEMENT_COLUMNS):
            value = row.get(column)
            row_currency = str(row.get("devise", currency_text)).upper()
            row_decimals = 0 if row_currency == "CDF" else 2
            if column == "date":
                parsed = pd.to_datetime(value, errors="coerce")
                text = f"{parsed:%d/%m/%Y}" if pd.notna(parsed) else "-"
            elif column in {"entree", "sortie"}:
                numeric_value = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
                text = "" if pd.isna(numeric_value) or float(numeric_value) == 0 else _pdf_number(numeric_value, decimals=row_decimals)
            elif column == "solde":
                text = _pdf_number(value, decimals=row_decimals)
            else:
                text = "-" if _is_empty_text(value) else str(value)
            cells[index].text = text
            cells[index].width = Cm(widths[column])
            cells[index].vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
            for paragraph in cells[index].paragraphs:
                paragraph.paragraph_format.space_after = Pt(0)
                if column in {"entree", "sortie", "solde"}:
                    paragraph.alignment = WD_ALIGN_PARAGRAPH.RIGHT
                for run in paragraph.runs:
                    run.font.size = Pt(6.8)

    footer = section.footer.paragraphs[0]
    footer.alignment = WD_ALIGN_PARAGRAPH.CENTER
    footer_run = footer.add_run(f"Extrait genere le {generated_at:%d/%m/%Y %H:%M} - Solution Bisou Bisou Digital")
    footer_run.font.size = Pt(7.5)
    footer_run.font.color.rgb = RGBColor(110, 125, 140)

    document.core_properties.title = f"Extrait de compte {customer_id_text} - {currency_label}"
    document.core_properties.subject = "Extrait client Solution Numérique"
    document.core_properties.author = "Solution Controle Interne"
    buffer = BytesIO()
    document.save(buffer)
    buffer.seek(0)
    return buffer.getvalue()


def create_customer_statement_pdf(
    statement: pd.DataFrame,
    *,
    analysis_report: dict[str, pd.DataFrame] | None = None,
    customer_id: object,
    customer_name: object = "",
    telephone: object = "",
    currency: object,
    account_number: object = "",
    entry_account_number: object | None = None,
    output_account_number: object | None = None,
    period_start: object | None = None,
    period_end: object | None = None,
    generated_at: pd.Timestamp | None = None,
    minimal: bool = False,
) -> bytes:
    """Genere la version PDF de l'extrait officiel, sans conversion externe."""
    try:
        from reportlab.lib import colors
        from reportlab.lib.enums import TA_CENTER, TA_RIGHT
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
        from reportlab.lib.units import cm
        from reportlab.platypus import (
            Image,
            Paragraph,
            SimpleDocTemplate,
            Spacer,
            Table,
            TableStyle,
        )
    except ImportError as exc:
        raise RuntimeError("La dependance reportlab est requise pour generer l'extrait PDF.") from exc

    if not isinstance(statement, pd.DataFrame) or statement.empty:
        raise ValueError("Aucune operation filtree n'est disponible pour l'extrait PDF.")
    currency_text = str(currency).strip().upper()
    all_currencies = currency_text in {"ALL", "TOUTES", "TOUS", "CDF + USD"}
    frame = statement.copy()
    frame_currency = clean_text(
        frame.get("currency_code", pd.Series("", index=frame.index))
    ).str.upper()
    if not all_currencies:
        frame = frame.loc[frame_currency.eq(currency_text)].copy()
    if frame.empty:
        raise ValueError(f"Aucune operation {currency_text or 'sans devise'} n'est disponible pour l'extrait PDF.")

    view = build_customer_statement_view(
        frame,
        account_number=account_number,
        entry_account_number=entry_account_number,
        output_account_number=output_account_number,
        allow_multiple_currencies=all_currencies,
    )
    transactions = view["transactions"]
    detail_transactions = _customer_statement_export_detail(
        transactions,
        frame,
        view["summary_by_currency"],
        entry_account_number=entry_account_number,
        output_account_number=output_account_number,
    )
    customer_id_text = str(customer_id).strip() or view["customer_id"] or "Non disponible"
    customer_name_text = str(customer_name).strip() or view["customer_name"] or "Nom non disponible"
    telephone_text = str(telephone).strip() or view["telephone"] or "Non disponible"
    observed_currencies = sorted(
        value for value in transactions["devise"].dropna().astype(str).unique() if value
    )
    currency_label = (
        f"ALL ({', '.join(observed_currencies)})"
        if all_currencies
        else currency_text or view["currency"]
    )
    analysis_report = analysis_report or {}
    detail_transactions = build_customer_statement_detail_with_covered_operations(
        detail_transactions,
        analysis_report,
        customer_id=customer_id_text,
        currency=currency_text,
        entry_account_number=entry_account_number,
        all_currencies=all_currencies,
    )
    view_for_summary = dict(view)
    view_for_summary["detail_transactions"] = detail_transactions
    dat_rate_label = _customer_statement_dat_rate_label(
        analysis_report,
        customer_id=customer_id_text,
        currency=currency_text,
        all_currencies=all_currencies,
    )
    observed_dates = pd.to_datetime(transactions["date"], errors="coerce").dropna()

    def report_date(value: object | None, fallback: pd.Timestamp | None) -> str:
        parsed = pd.to_datetime(value, errors="coerce") if value is not None else pd.NaT
        if pd.isna(parsed):
            parsed = fallback
        return f"{parsed:%d/%m/%Y}" if parsed is not None and pd.notna(parsed) else "Non disponible"

    start_text = report_date(period_start, observed_dates.min() if not observed_dates.empty else None)
    end_text = report_date(period_end, observed_dates.max() if not observed_dates.empty else None)
    generated_at = generated_at if generated_at is not None else pd.Timestamp.now()
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle(
        "CustomerStatementTitle", parent=styles["Title"], fontName="Helvetica-Bold",
        fontSize=13, leading=16, textColor=colors.HexColor("#18293A"), alignment=TA_CENTER,
        spaceAfter=8,
    )
    body_style = ParagraphStyle(
        "CustomerStatementBody", parent=styles["BodyText"], fontName="Helvetica",
        fontSize=6.6, leading=8.0,
    )
    header_style = ParagraphStyle(
        "CustomerStatementHeader", parent=body_style, fontName="Helvetica-Bold",
        fontSize=6.1, leading=7.2, textColor=colors.white, alignment=TA_CENTER,
    )
    amount_style = ParagraphStyle(
        "CustomerStatementAmount", parent=body_style, alignment=TA_RIGHT,
    )
    section_style = ParagraphStyle(
        "CustomerStatementSection", parent=styles["Heading3"], fontName="Helvetica-Bold",
        fontSize=10, textColor=colors.HexColor("#183F5B"), spaceBefore=7, spaceAfter=4,
    )
    buffer = BytesIO()
    document = SimpleDocTemplate(
        buffer, pagesize=A4, leftMargin=1 * cm, rightMargin=1 * cm,
        topMargin=0.8 * cm, bottomMargin=1.1 * cm,
        title=f"Extrait de compte {customer_id_text} - {currency_label}",
        author="Solution Controle Interne",
    )
    story: list[Any] = []
    if CUSTOMER_STATEMENT_LOGO_PATH.is_file():
        logo: Any = Image(str(CUSTOMER_STATEMENT_LOGO_PATH), width=3.1 * cm, height=3.1 * cm)
    else:
        logo = Paragraph("<b>IMF Microfinance Bisou Bisou</b>", styles["Heading2"])
    criteria = Table(
        [
            [Paragraph("<b>Critères</b>", header_style), ""],
            ["Date du :", start_text], ["Au :", end_text],
            ["Numéro du client :", customer_id_text], ["Téléphone :", telephone_text],
            ["Devise :", currency_label],
            ["Taux annuel DAT :", dat_rate_label],
        ],
        colWidths=[3.8 * cm, 4.7 * cm],
    )
    criteria.setStyle(TableStyle([
        ("SPAN", (0, 0), (1, 0)), ("BACKGROUND", (0, 0), (1, 0), colors.HexColor("#1F2937")),
        ("FONTNAME", (0, 1), (0, -1), "Helvetica-Bold"), ("FONTSIZE", (0, 1), (-1, -1), 7.5),
        ("GRID", (0, 1), (-1, -1), 0.25, colors.HexColor("#CBD5E1")),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"), ("LEFTPADDING", (0, 0), (-1, -1), 4),
        ("RIGHTPADDING", (0, 0), (-1, -1), 4), ("TOPPADDING", (0, 0), (-1, -1), 3),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
    ]))
    masthead = Table([[logo, criteria]], colWidths=[9.5 * cm, 8.5 * cm])
    masthead.setStyle(TableStyle([("VALIGN", (0, 0), (-1, -1), "MIDDLE")]))
    story.extend([masthead, Spacer(1, 0.15 * cm)])
    name_available = normalize_label(customer_name_text) not in {"", "non disponible", "nom non disponible"}
    title_parts = ["Extrait de compte", telephone_text]
    if minimal:
        title_parts = ["Extrait minimal de compte", telephone_text]
    if name_available:
        title_parts.append(customer_name_text.upper())
    title_parts.append(currency_label)
    story.append(Paragraph(" - ".join(escape(part) for part in title_parts), title_style))

    story.append(Paragraph("Synthèse financière par devise", section_style))
    financial_rows = [[
        Paragraph("Devise", header_style),
        Paragraph("Ouverture", header_style),
        Paragraph("Entrée", header_style),
        Paragraph("Sorties", header_style),
        Paragraph("Cloture", header_style),
        Paragraph("Compte ouvert", header_style),
        Paragraph("Compte bloqué", header_style),
    ]]
    financial_summary = build_customer_statement_financial_summary(
        view_for_summary,
        analysis_report,
        customer_id=customer_id_text,
        currency=currency_text,
        all_currencies=all_currencies,
    )
    detail_transactions = build_customer_statement_detail_with_opening_balance(
        detail_transactions,
        financial_summary,
    )
    for _, row in financial_summary.iterrows():
        row_currency = str(row.get("currency_code", ""))
        decimals = 0 if row_currency == "CDF" else 2
        financial_values = [
            row_currency,
            _pdf_number(row.get("opening_amount"), decimals=decimals),
            _pdf_number(row.get("total_entries"), decimals=decimals),
            _pdf_number(row.get("total_outputs"), decimals=decimals),
            _pdf_number(row.get("closing_amount"), decimals=decimals),
            _pdf_number(row.get("compte_ouvert"), decimals=decimals),
            _pdf_number(row.get("compte_bloque"), decimals=decimals),
        ]
        financial_rows.append([
            Paragraph(escape("-" if _is_empty_text(value) else str(value)), body_style)
            for value in financial_values
        ])
    summary_table = Table(
        financial_rows,
        colWidths=[
            1.7 * cm,
            2.2 * cm,
            2.2 * cm,
            2.2 * cm,
            2.2 * cm,
            2.3 * cm,
            2.3 * cm,
        ],
        repeatRows=1,
    )
    summary_table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1F2937")),
        ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#B7C1CC")),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("ALIGN", (1, 1), (-1, -1), "RIGHT"),
        ("ALIGN", (0, 0), (-1, 0), "CENTER"),
        ("LEFTPADDING", (0, 0), (-1, -1), 2.2),
        ("RIGHTPADDING", (0, 0), (-1, -1), 2.2),
        ("TOPPADDING", (0, 0), (-1, -1), 2.5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 2.5),
    ]))
    story.append(summary_table)

    def analysis_frame(key: str) -> pd.DataFrame:
        return _customer_statement_analysis_frame(
            analysis_report,
            key,
            customer_id=customer_id_text,
            currency=currency_text,
            all_currencies=all_currencies,
        )

    def append_analysis_table(
        title: str,
        source: pd.DataFrame,
        columns: list[str],
        labels: dict[str, str],
        widths: list[float],
    ) -> None:
        present = [column for column in columns if column in source.columns]
        if source.empty or not present:
            return
        selected_widths = [widths[columns.index(column)] * cm for column in present]
        rows: list[list[Any]] = [
            [Paragraph(escape(labels.get(column, column)), header_style) for column in present]
        ]
        for _, source_row in source.iterrows():
            row_currency = str(source_row.get("currency_code", currency_text)).upper()
            row_decimals = 0 if row_currency == "CDF" else 2
            values: list[Any] = []
            for column in present:
                value = source_row.get(column)
                if column in {
                    "created_at",
                    "maturity_date",
                    "date_ecriture_turbo",
                    "date_approved",
                    "date_creation_dat",
                    "date_fin_dat",
                    "due_date",
                }:
                    parsed = pd.to_datetime(value, errors="coerce")
                    text_value = f"{parsed:%d/%m/%Y %H:%M}" if pd.notna(parsed) else "-"
                elif column.endswith("_pct"):
                    numeric_value = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
                    text_value = f"{numeric_value:.1f}%" if pd.notna(numeric_value) else "-"
                elif any(
                    token in column
                    for token in [
                        "montant",
                        "solde",
                        "balance",
                        "interet",
                        "principal",
                        "penalite",
                        "transfert",
                    ]
                ):
                    text_value = _pdf_number(value, decimals=row_decimals)
                else:
                    text_value = "-" if _is_empty_text(value) else str(value)
                values.append(Paragraph(escape(text_value), body_style))
            rows.append(values)
        story.append(Paragraph(title, section_style))
        report_table = Table(rows, colWidths=selected_widths, repeatRows=1)
        report_table.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1F2937")),
            ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#B7C1CC")),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("LEFTPADDING", (0, 0), (-1, -1), 2.2),
            ("RIGHTPADDING", (0, 0), (-1, -1), 2.2),
            ("TOPPADDING", (0, 0), (-1, -1), 2.5),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 2.5),
        ]))
        story.append(report_table)

    if not minimal:
        statement_element_summary = analysis_frame("elements_extrait_client_synthese")
        append_analysis_table(
            "Éléments couverts par l'extrait client",
            statement_element_summary,
            [
                "type_element_extrait",
                "currency_code",
                "nombre_operations",
                "montant_total_observe",
                "statut_periode",
            ],
            {
                "type_element_extrait": "Élément",
                "currency_code": "Devise",
                "nombre_operations": "Opérations",
                "montant_total_observe": "Montant observé",
                "statut_periode": "Situation sur la période",
            },
            [7.5, 1.3, 1.7, 2.8, 5.2],
        )

    active_dat = analysis_frame("dat_en_cours_client")
    if not minimal and not active_dat.empty:
        situation_dates = pd.to_datetime(active_dat.get("date_situation"), errors="coerce").dropna()
        dat_title = "DAT en cours"
        if not situation_dates.empty:
            dat_title += f" - situation au {situation_dates.max():%d/%m/%Y}"
        story.append(Paragraph(dat_title, section_style))
        dat_headers = [
            "DAT",
            "Souscription",
            "Échéance",
            "Jours restants",
            "Devise",
            "Capital bloqué",
            "Situation",
            "Capital + intérêt estimé",
        ]
        dat_rows: list[list[Any]] = [
            [Paragraph(label, header_style) for label in dat_headers]
        ]
        for _, dat_row in active_dat.iterrows():
            row_currency = str(dat_row.get("currency_code", currency_text)).upper()
            row_decimals = 0 if row_currency == "CDF" else 2
            approved = pd.to_datetime(dat_row.get("date_approved"), errors="coerce")
            maturity = pd.to_datetime(dat_row.get("maturity_date"), errors="coerce")
            values = [
                dat_row.get("savings_id", "-"),
                f"{approved:%d/%m/%Y}" if pd.notna(approved) else "-",
                f"{maturity:%d/%m/%Y}" if pd.notna(maturity) else "-",
                _pdf_number(dat_row.get("jours_avant_echeance"), decimals=0),
                row_currency,
                _pdf_number(dat_row.get("balance"), decimals=row_decimals),
                dat_row.get("situation_dat_client", "-"),
                _pdf_number(
                    dat_row.get("capital_plus_interet_estime"),
                    decimals=row_decimals,
                ),
            ]
            dat_rows.append(
                [
                    Paragraph(escape("-" if _is_empty_text(value) else str(value)), body_style)
                    for value in values
                ]
            )
        dat_table = Table(
            dat_rows,
            colWidths=[
                2.2 * cm,
                2.0 * cm,
                2.0 * cm,
                1.2 * cm,
                1.1 * cm,
                2.1 * cm,
                3.2 * cm,
                3.0 * cm,
            ],
            repeatRows=1,
        )
        dat_table.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1F2937")),
            ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#B7C1CC")),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("ALIGN", (3, 1), (5, -1), "RIGHT"),
            ("ALIGN", (7, 1), (7, -1), "RIGHT"),
            ("LEFTPADDING", (0, 0), (-1, -1), 2.2),
            ("RIGHTPADDING", (0, 0), (-1, -1), 2.2),
            ("TOPPADDING", (0, 0), (-1, -1), 2.5),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 2.5),
        ]))
        story.append(dat_table)

    repayments = analysis_frame("remboursements_turbo_detail_client")
    if not minimal and not repayments.empty:
        story.append(Paragraph("Remboursements observés", section_style))
        repayment_headers = [
            "Date",
            "Référence",
            "Devise",
            "Montant payé",
            "Intérêts",
            "Origine du paiement",
            "Pénalités",
        ]
        repayment_rows: list[list[Any]] = [
            [Paragraph(label, header_style) for label in repayment_headers]
        ]
        for _, repayment_row in repayments.iterrows():
            row_currency = str(repayment_row.get("currency_code", currency_text)).upper()
            row_decimals = 0 if row_currency == "CDF" else 2
            repayment_date = pd.to_datetime(repayment_row.get("created_at"), errors="coerce")
            values = [
                f"{repayment_date:%d/%m/%Y %H:%M}" if pd.notna(repayment_date) else "-",
                repayment_row.get("event_reference", "-"),
                row_currency,
                _pdf_number(repayment_row.get("montant_paye_observe"), decimals=row_decimals),
                _pdf_number(repayment_row.get("interet_observe"), decimals=row_decimals),
                repayment_row.get("origine_remboursement_observee", "-"),
                _pdf_number(repayment_row.get("penalite_observee"), decimals=row_decimals),
            ]
            repayment_rows.append(
                [
                    Paragraph(escape("-" if _is_empty_text(value) else str(value)), body_style)
                    for value in values
                ]
            )
        repayment_table = Table(
            repayment_rows,
            colWidths=[
                2.6 * cm,
                2.8 * cm,
                1.1 * cm,
                2.2 * cm,
                2.0 * cm,
                4.0 * cm,
                2.1 * cm,
            ],
            repeatRows=1,
        )
        repayment_table.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1F2937")),
            ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#B7C1CC")),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("ALIGN", (3, 1), (4, -1), "RIGHT"),
            ("ALIGN", (6, 1), (6, -1), "RIGHT"),
            ("LEFTPADDING", (0, 0), (-1, -1), 2.2),
            ("RIGHTPADDING", (0, 0), (-1, -1), 2.2),
            ("TOPPADDING", (0, 0), (-1, -1), 2.5),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 2.5),
        ]))
        story.append(repayment_table)

    upcoming_repayments = analysis_frame("prochains_remboursements_client")
    if not minimal:
        append_analysis_table(
            "Prochains remboursements sur la période",
            upcoming_repayments,
            [
                "due_date",
                "loan_id",
                "currency_code",
                "montant_a_rembourser",
                "outstanding_principle",
                "outstanding_interest",
                "outstanding_penalty_fees",
                "status_name",
            ],
            {
                "due_date": "Date prévue",
                "loan_id": "Crédit",
                "currency_code": "Devise",
                "montant_a_rembourser": "Montant à rembourser",
                "outstanding_principle": "Principal",
                "outstanding_interest": "Intérêts",
                "outstanding_penalty_fees": "Pénalités",
                "status_name": "Statut",
            },
            [2.3, 2.4, 1.0, 2.5, 2.0, 1.8, 1.8, 3.0],
        )

    if not minimal:
        internal = analysis_frame("mouvements_internes_turbo")
        append_analysis_table(
            "Retours du capital mis en DAT",
            internal,
            [
                "date_creation_dat",
                "date_fin_dat",
                "event_reference",
                "currency_code",
                "transfert_dat_sortie",
                "transfert_epargne_entree",
                "descriptions",
            ],
            {
                "date_creation_dat": "Création du DAT",
                "date_fin_dat": "Fin du DAT",
                "event_reference": "Référence",
                "currency_code": "Devise",
                "transfert_dat_sortie": "Capital DAT restitué",
                "transfert_epargne_entree": "Entrée compte ouvert",
                "descriptions": "Description",
            },
            [2.3, 2.3, 2.4, 1.1, 2.3, 2.3, 5.5],
        )

        dat_interest_entries = analysis_frame("interets_dat_credites_client")
        append_analysis_table(
            "Entrées des intérêts du capital mis en DAT",
            dat_interest_entries,
            [
                "maturity_date",
                "savings_id",
                "currency_code",
                "capital_place",
                "interet_client_constate",
                "montant_echeance_client",
            ],
            {
                "maturity_date": "Échéance",
                "savings_id": "DAT",
                "currency_code": "Devise",
                "capital_place": "Capital placé",
                "interet_client_constate": "Intérêt client",
                "montant_echeance_client": "Capital + intérêt",
            },
            [2.5, 3.0, 1.2, 3.2, 3.5, 4.0],
        )

    story.append(Paragraph("Détail des transactions", section_style))

    labels = [
        "Date",
        "Compte",
        "Référence",
        "Devise",
        "Description",
        "Entrées",
        "Sorties",
        "Solde",
    ]
    detail_rows: list[list[Any]] = [[Paragraph(label, header_style) for label in labels]]
    for _, row in detail_transactions.iterrows():
        row_currency = str(row.get("devise", currency_text)).upper()
        decimals = 0 if row_currency == "CDF" else 2
        date_value = pd.to_datetime(row.get("date"), errors="coerce")
        values = [
            f"{date_value:%d/%m/%Y}" if pd.notna(date_value) else "-",
            row.get("compte", "-"), row.get("receipt_no", "-"), row_currency,
            row.get("description", "-"), row.get("entree"), row.get("sortie"), row.get("solde"),
        ]
        formatted: list[Any] = []
        for index, value in enumerate(values):
            if index in {5, 6}:
                numeric = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
                text_value = "" if pd.isna(numeric) or float(numeric) == 0 else _pdf_number(numeric, decimals=decimals)
                formatted.append(Paragraph(text_value, amount_style))
            elif index == 7:
                formatted.append(Paragraph(_pdf_number(value, decimals=decimals), amount_style))
            else:
                formatted.append(Paragraph(escape("-" if _is_empty_text(value) else str(value)), body_style))
        detail_rows.append(formatted)
    detail = Table(
        detail_rows,
        colWidths=[
            1.7 * cm,
            1.0 * cm,
            2.3 * cm,
            1.0 * cm,
            6.3 * cm,
            1.6 * cm,
            1.6 * cm,
            2.7 * cm,
        ],
        repeatRows=1,
    )
    detail.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1F2937")),
        ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#B7C1CC")),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("LEFTPADDING", (0, 0), (-1, -1), 2.5), ("RIGHTPADDING", (0, 0), (-1, -1), 2.5),
        ("TOPPADDING", (0, 0), (-1, -1), 2.5), ("BOTTOMPADDING", (0, 0), (-1, -1), 2.5),
    ]))
    story.append(detail)

    def draw_footer(canvas: Any, doc: Any) -> None:
        canvas.saveState()
        canvas.setFont("Helvetica", 7)
        canvas.setFillColor(colors.HexColor("#6E7D8C"))
        footer = f"Extrait généré le {generated_at:%d/%m/%Y %H:%M} - Solution Bisou Bisou Digital - Page {doc.page}"
        canvas.drawCentredString(A4[0] / 2, 0.45 * cm, footer)
        canvas.restoreState()

    document.build(story, onFirstPage=draw_footer, onLaterPages=draw_footer)
    return buffer.getvalue()


def create_customer_client_statement_word(
    statement: pd.DataFrame,
    *,
    analysis_report: dict[str, pd.DataFrame] | None = None,
    customer_id: object,
    customer_name: object = "",
    telephone: object = "",
    currency: object,
    account_number: object = "",
    entry_account_number: object | None = None,
    output_account_number: object | None = None,
    period_start: object | None = None,
    period_end: object | None = None,
    generated_at: pd.Timestamp | None = None,
    minimal: bool = False,
) -> bytes:
    """Genere l'extrait Word du point de vue client."""
    try:
        from docx import Document
        from docx.enum.table import WD_CELL_VERTICAL_ALIGNMENT, WD_TABLE_ALIGNMENT
        from docx.enum.text import WD_ALIGN_PARAGRAPH
        from docx.oxml import OxmlElement
        from docx.oxml.ns import qn
        from docx.shared import Cm, Pt, RGBColor
    except ImportError as exc:
        raise RuntimeError("La dependance python-docx est requise pour generer l'extrait Word client.") from exc

    frame, currency_text, all_currencies = _filter_customer_statement_for_export(
        statement,
        currency,
        error_label="l'extrait Word client",
    )
    analysis_report = analysis_report or {}
    customer_id_text = str(customer_id).strip() or "Non disponible"
    customer_name_text = str(customer_name).strip() or "Nom non disponible"
    telephone_text = str(telephone).strip() or "Non disponible"
    view = build_customer_client_statement_view(
        frame,
        analysis_report=analysis_report,
        customer_id=customer_id_text,
        currency=currency_text,
        account_number=account_number,
        entry_account_number=entry_account_number,
        output_account_number=output_account_number,
        all_currencies=all_currencies,
    )
    detail = view["detail"]
    if detail.empty:
        raise ValueError("Aucune ligne exploitable n'est disponible pour l'extrait Word client.")
    currency_label = _customer_statement_currency_label(
        detail.rename(columns={"reference": "receipt_no"}),
        currency_text,
        all_currencies,
    )
    observed_dates = pd.to_datetime(detail["date"], errors="coerce").dropna()

    def report_date(value: object | None, fallback: pd.Timestamp | None) -> str:
        parsed = pd.to_datetime(value, errors="coerce") if value is not None else pd.NaT
        if pd.isna(parsed):
            parsed = fallback
        return f"{parsed:%d/%m/%Y}" if parsed is not None and pd.notna(parsed) else "Non disponible"

    start_text = report_date(period_start, observed_dates.min() if not observed_dates.empty else None)
    end_text = report_date(period_end, observed_dates.max() if not observed_dates.empty else None)
    generated_at = generated_at if generated_at is not None else pd.Timestamp.now()
    dat_rate_label = _customer_statement_dat_rate_label(
        analysis_report,
        customer_id=customer_id_text,
        currency=currency_text,
        all_currencies=all_currencies,
    )

    document = Document()
    section = document.sections[0]
    section.top_margin = Cm(1.0)
    section.bottom_margin = Cm(1.0)
    section.left_margin = Cm(2.0)
    section.right_margin = Cm(2.0)
    styles = document.styles
    styles["Normal"].font.name = "Aptos"
    styles["Normal"].font.size = Pt(8.5)
    styles["Title"].font.name = "Aptos Display"
    styles["Title"].font.size = Pt(15)
    styles["Title"].font.color.rgb = RGBColor(24, 41, 58)

    def set_cell_shading(cell: Any, fill: str) -> None:
        cell_properties = cell._tc.get_or_add_tcPr()
        shading = OxmlElement("w:shd")
        shading.set(qn("w:fill"), fill)
        cell_properties.append(shading)

    def set_repeat_header(row: Any) -> None:
        row_properties = row._tr.get_or_add_trPr()
        repeat_header = OxmlElement("w:tblHeader")
        repeat_header.set(qn("w:val"), "true")
        row_properties.append(repeat_header)

    header = document.add_table(rows=2, cols=2)
    header.alignment = WD_TABLE_ALIGNMENT.CENTER
    header.autofit = False
    brand_cell = header.cell(0, 0).merge(header.cell(1, 0))
    brand_cell.width = Cm(9.5)
    brand_paragraph = brand_cell.paragraphs[0]
    if CUSTOMER_STATEMENT_LOGO_PATH.is_file():
        try:
            brand_paragraph.add_run().add_picture(str(CUSTOMER_STATEMENT_LOGO_PATH), width=Cm(4.6))
        except (OSError, ValueError):
            brand_paragraph.add_run("IMF Microfinance Bisou Bisou").bold = True
    else:
        brand_paragraph.add_run("IMF Microfinance Bisou Bisou").bold = True
    criteria_title = header.cell(0, 1)
    criteria_title.text = "Critères"
    criteria_title.paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
    set_cell_shading(criteria_title, "1F2937")
    for run in criteria_title.paragraphs[0].runs:
        run.bold = True
        run.font.color.rgb = RGBColor(255, 255, 255)
    criteria = header.cell(1, 1).add_table(rows=6, cols=2)
    criteria_rows = [
        ("Date du :", start_text),
        ("Au :", end_text),
        ("Numéro du client :", customer_id_text),
        ("Téléphone :", telephone_text),
        ("Devise :", currency_label),
        ("Taux annuel DAT :", dat_rate_label),
    ]
    for row_index, (label, value) in enumerate(criteria_rows):
        criteria.cell(row_index, 0).text = label
        criteria.cell(row_index, 1).text = value
        for run in criteria.cell(row_index, 0).paragraphs[0].runs:
            run.bold = True
            run.font.size = Pt(8)
        for run in criteria.cell(row_index, 1).paragraphs[0].runs:
            run.font.size = Pt(8)

    title = document.add_paragraph(style="Title")
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER
    title.paragraph_format.space_before = Pt(5)
    title.paragraph_format.space_after = Pt(6)
    title_text = "Extrait de compte"
    if minimal:
        title_text = "Extrait minimal de compte"
    name_available = normalize_label(customer_name_text) not in {"", "non disponible", "nom non disponible"}
    title_parts = [title_text, telephone_text]
    if name_available:
        title_parts.append(customer_name_text.upper())
    title_parts.append(currency_label)
    title.add_run(" - ".join(title_parts))

    def add_title(text: str) -> None:
        paragraph = document.add_paragraph()
        paragraph.paragraph_format.space_before = Pt(5)
        paragraph.paragraph_format.space_after = Pt(2)
        run = paragraph.add_run(text)
        run.bold = True
        run.font.size = Pt(10)
        run.font.color.rgb = RGBColor(24, 63, 91)

    def add_table(source: pd.DataFrame, labels: dict[str, str], widths: dict[str, float]) -> None:
        columns = [column for column in labels if column in source.columns]
        table = document.add_table(rows=1, cols=len(columns))
        table.style = "Table Grid"
        table.alignment = WD_TABLE_ALIGNMENT.CENTER
        table.autofit = False
        set_repeat_header(table.rows[0])
        for index, column in enumerate(columns):
            cell = table.rows[0].cells[index]
            cell.text = labels[column]
            cell.width = Cm(widths.get(column, 2.0))
            set_cell_shading(cell, "DCE6F1")
            cell.paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
            for run in cell.paragraphs[0].runs:
                run.bold = True
                run.font.size = Pt(7.0)
        for _, source_row in source.iterrows():
            row_currency = str(source_row.get("currency_code", source_row.get("devise", currency_text))).upper()
            decimals = 0 if row_currency == "CDF" else 2
            cells = table.add_row().cells
            for index, column in enumerate(columns):
                value = source_row.get(column)
                if column == "date":
                    parsed = pd.to_datetime(value, errors="coerce")
                    text = f"{parsed:%d/%m/%Y}" if pd.notna(parsed) else "-"
                elif any(token in column for token in ["compte", "position", "pret", "remboursement", "frais", "epargne"]):
                    numeric = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
                    text = "" if pd.isna(numeric) or (column != "position_epargne" and float(numeric) == 0) else _pdf_number(numeric, decimals=decimals)
                else:
                    text = "-" if _is_empty_text(value) else str(value)
                cells[index].text = text
                cells[index].width = Cm(widths.get(column, 2.0))
                cells[index].vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
                for paragraph in cells[index].paragraphs:
                    paragraph.paragraph_format.space_after = Pt(0)
                    if any(token in column for token in ["compte", "position", "pret", "remboursement", "frais", "epargne"]):
                        paragraph.alignment = WD_ALIGN_PARAGRAPH.RIGHT
                    for run in paragraph.runs:
                        run.font.size = Pt(6.7)

    add_title("Synthèse financière par devise")
    add_table(
        view["summary"],
        {
            "currency_code": "Devise",
            "compte_ouvert": "Compte ouvert",
            "compte_bloque": "Compte bloqué",
            "position_epargne_finale": "Position épargne",
            "pret_net_recu": "Prêt net reçu",
            "remboursements_observes": "Remboursements",
            "frais_interets_credit": "Frais/intérêts crédit",
        },
        {
            "currency_code": 1.4,
            "compte_ouvert": 2.1,
            "compte_bloque": 2.1,
            "position_epargne_finale": 2.4,
            "pret_net_recu": 2.2,
            "remboursements_observes": 2.4,
            "frais_interets_credit": 2.7,
        },
    )

    if not minimal:
        active_dat = _customer_statement_analysis_frame(
            analysis_report,
            "dat_en_cours_client",
            customer_id=customer_id_text,
            currency=currency_text,
            all_currencies=all_currencies,
        )
        if not active_dat.empty:
            add_title("DAT en cours")
            add_table(
                active_dat,
                {
                    "savings_id": "DAT",
                    "date_approved": "Souscription",
                    "maturity_date": "Échéance",
                    "jours_avant_echeance": "Jours restants",
                    "currency_code": "Devise",
                    "balance": "Capital bloqué",
                    "capital_plus_interet_estime": "Capital + intérêt estimé",
                },
                {
                    "savings_id": 2.6,
                    "date_approved": 2.2,
                    "maturity_date": 2.2,
                    "jours_avant_echeance": 1.5,
                    "currency_code": 1.2,
                    "balance": 2.5,
                    "capital_plus_interet_estime": 3.2,
                },
            )

    add_title("Détail des transactions")
    add_table(
        detail,
        {
            "date": "Date",
            "reference": "Référence",
            "devise": "Devise",
            "operation": "Opération",
            "entree_epargne": "Entrée épargne",
            "sortie_epargne": "Sortie épargne",
            "pret_net_recu": "Prêt net reçu",
            "remboursement_paye": "Remboursement payé",
            "frais_interets": "Frais/intérêts",
            "position_epargne": "Position épargne",
        },
        {
            "date": 1.7,
            "reference": 2.2,
            "devise": 1.0,
            "operation": 4.2,
            "entree_epargne": 1.8,
            "sortie_epargne": 1.8,
            "pret_net_recu": 1.8,
            "remboursement_paye": 2.0,
            "frais_interets": 1.8,
            "position_epargne": 2.0,
        },
    )

    footer = section.footer.paragraphs[0]
    footer.alignment = WD_ALIGN_PARAGRAPH.CENTER
    footer_run = footer.add_run(f"Extrait généré le {generated_at:%d/%m/%Y %H:%M} - Solution Bisou Bisou Digital")
    footer_run.font.size = Pt(7.5)
    footer_run.font.color.rgb = RGBColor(110, 125, 140)
    document.core_properties.title = f"Extrait de compte {customer_id_text} - {currency_label}"
    document.core_properties.subject = "Extrait client M-PESA"
    document.core_properties.author = "Solution Controle Interne"
    buffer = BytesIO()
    document.save(buffer)
    buffer.seek(0)
    return buffer.getvalue()


def create_customer_client_statement_pdf(
    statement: pd.DataFrame,
    *,
    analysis_report: dict[str, pd.DataFrame] | None = None,
    customer_id: object,
    customer_name: object = "",
    telephone: object = "",
    currency: object,
    account_number: object = "",
    entry_account_number: object | None = None,
    output_account_number: object | None = None,
    period_start: object | None = None,
    period_end: object | None = None,
    generated_at: pd.Timestamp | None = None,
    minimal: bool = False,
) -> bytes:
    """Genere l'extrait PDF du point de vue client."""
    try:
        from reportlab.lib import colors
        from reportlab.lib.enums import TA_CENTER, TA_RIGHT
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
        from reportlab.lib.units import cm
        from reportlab.platypus import Image, Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle
    except ImportError as exc:
        raise RuntimeError("La dependance reportlab est requise pour generer l'extrait PDF client.") from exc

    frame, currency_text, all_currencies = _filter_customer_statement_for_export(
        statement,
        currency,
        error_label="l'extrait PDF client",
    )
    analysis_report = analysis_report or {}
    customer_id_text = str(customer_id).strip() or "Non disponible"
    customer_name_text = str(customer_name).strip() or "Nom non disponible"
    telephone_text = str(telephone).strip() or "Non disponible"
    view = build_customer_client_statement_view(
        frame,
        analysis_report=analysis_report,
        customer_id=customer_id_text,
        currency=currency_text,
        account_number=account_number,
        entry_account_number=entry_account_number,
        output_account_number=output_account_number,
        all_currencies=all_currencies,
    )
    detail = view["detail"]
    if detail.empty:
        raise ValueError("Aucune ligne exploitable n'est disponible pour l'extrait PDF client.")
    currency_label = _customer_statement_currency_label(
        detail.rename(columns={"reference": "receipt_no"}),
        currency_text,
        all_currencies,
    )
    observed_dates = pd.to_datetime(detail["date"], errors="coerce").dropna()

    def report_date(value: object | None, fallback: pd.Timestamp | None) -> str:
        parsed = pd.to_datetime(value, errors="coerce") if value is not None else pd.NaT
        if pd.isna(parsed):
            parsed = fallback
        return f"{parsed:%d/%m/%Y}" if parsed is not None and pd.notna(parsed) else "Non disponible"

    start_text = report_date(period_start, observed_dates.min() if not observed_dates.empty else None)
    end_text = report_date(period_end, observed_dates.max() if not observed_dates.empty else None)
    generated_at = generated_at if generated_at is not None else pd.Timestamp.now()
    dat_rate_label = _customer_statement_dat_rate_label(
        analysis_report,
        customer_id=customer_id_text,
        currency=currency_text,
        all_currencies=all_currencies,
    )

    styles = getSampleStyleSheet()
    title_style = ParagraphStyle(
        "ClientStatementTitle",
        parent=styles["Title"],
        fontName="Helvetica-Bold",
        fontSize=13,
        leading=16,
        textColor=colors.HexColor("#18293A"),
        alignment=TA_CENTER,
        spaceAfter=8,
    )
    body_style = ParagraphStyle("ClientStatementBody", parent=styles["BodyText"], fontName="Helvetica", fontSize=6.3, leading=7.7)
    header_style = ParagraphStyle("ClientStatementHeader", parent=body_style, fontName="Helvetica-Bold", fontSize=5.8, leading=7.0, textColor=colors.white, alignment=TA_CENTER)
    amount_style = ParagraphStyle("ClientStatementAmount", parent=body_style, alignment=TA_RIGHT)
    section_style = ParagraphStyle("ClientStatementSection", parent=styles["Heading3"], fontName="Helvetica-Bold", fontSize=10, textColor=colors.HexColor("#183F5B"), spaceBefore=7, spaceAfter=4)

    buffer = BytesIO()
    document = SimpleDocTemplate(
        buffer,
        pagesize=A4,
        leftMargin=0.8 * cm,
        rightMargin=0.8 * cm,
        topMargin=0.8 * cm,
        bottomMargin=1.1 * cm,
        title=f"Extrait de compte {customer_id_text} - {currency_label}",
        author="Solution Controle Interne",
    )
    story: list[Any] = []
    logo: Any
    if CUSTOMER_STATEMENT_LOGO_PATH.is_file():
        logo = Image(str(CUSTOMER_STATEMENT_LOGO_PATH), width=3.0 * cm, height=3.0 * cm)
    else:
        logo = Paragraph("<b>IMF Microfinance Bisou Bisou</b>", styles["Heading2"])
    criteria = Table(
        [
            [Paragraph("<b>Critères</b>", header_style), ""],
            ["Date du :", start_text],
            ["Au :", end_text],
            ["Numéro du client :", customer_id_text],
            ["Téléphone :", telephone_text],
            ["Devise :", currency_label],
            ["Taux annuel DAT :", dat_rate_label],
        ],
        colWidths=[3.8 * cm, 4.7 * cm],
    )
    criteria.setStyle(TableStyle([
        ("SPAN", (0, 0), (1, 0)),
        ("BACKGROUND", (0, 0), (1, 0), colors.HexColor("#1F2937")),
        ("FONTNAME", (0, 1), (0, -1), "Helvetica-Bold"),
        ("FONTSIZE", (0, 1), (-1, -1), 7.2),
        ("GRID", (0, 1), (-1, -1), 0.25, colors.HexColor("#CBD5E1")),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("LEFTPADDING", (0, 0), (-1, -1), 4),
        ("RIGHTPADDING", (0, 0), (-1, -1), 4),
        ("TOPPADDING", (0, 0), (-1, -1), 3),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
    ]))
    story.extend([Table([[logo, criteria]], colWidths=[9.5 * cm, 8.5 * cm]), Spacer(1, 0.15 * cm)])

    name_available = normalize_label(customer_name_text) not in {"", "non disponible", "nom non disponible"}
    title_text = "Extrait de compte"
    if minimal:
        title_text = "Extrait minimal de compte"
    title_parts = [title_text, telephone_text]
    if name_available:
        title_parts.append(customer_name_text.upper())
    title_parts.append(currency_label)
    story.append(Paragraph(" - ".join(escape(part) for part in title_parts), title_style))

    def append_table(title: str, source: pd.DataFrame, labels: dict[str, str], widths: list[float]) -> None:
        columns = [column for column in labels if column in source.columns]
        if source.empty or not columns:
            return
        rows: list[list[Any]] = [[Paragraph(escape(labels[column]), header_style) for column in columns]]
        for _, source_row in source.iterrows():
            row_currency = str(source_row.get("currency_code", source_row.get("devise", currency_text))).upper()
            decimals = 0 if row_currency == "CDF" else 2
            values: list[Any] = []
            for column in columns:
                value = source_row.get(column)
                if column == "date":
                    parsed = pd.to_datetime(value, errors="coerce")
                    text = f"{parsed:%d/%m/%Y}" if pd.notna(parsed) else "-"
                    values.append(Paragraph(text, body_style))
                elif any(token in column for token in ["compte", "position", "pret", "remboursement", "frais", "epargne"]):
                    numeric = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
                    text = "" if pd.isna(numeric) or (column != "position_epargne" and float(numeric) == 0) else _pdf_number(numeric, decimals=decimals)
                    values.append(Paragraph(text, amount_style))
                else:
                    values.append(Paragraph(escape("-" if _is_empty_text(value) else str(value)), body_style))
            rows.append(values)
        story.append(Paragraph(title, section_style))
        table = Table(rows, colWidths=[width * cm for width in widths[: len(columns)]], repeatRows=1)
        table.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1F2937")),
            ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#B7C1CC")),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("LEFTPADDING", (0, 0), (-1, -1), 2.0),
            ("RIGHTPADDING", (0, 0), (-1, -1), 2.0),
            ("TOPPADDING", (0, 0), (-1, -1), 2.3),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 2.3),
        ]))
        story.append(table)

    append_table(
        "Synthèse financière par devise",
        view["summary"],
        {
            "currency_code": "Devise",
            "compte_ouvert": "Compte ouvert",
            "compte_bloque": "Compte bloqué",
            "position_epargne_finale": "Position épargne",
            "pret_net_recu": "Prêt net reçu",
            "remboursements_observes": "Remboursements",
            "frais_interets_credit": "Frais/intérêts crédit",
        },
        [1.3, 2.2, 2.2, 2.4, 2.2, 2.5, 2.8],
    )

    if not minimal:
        active_dat = _customer_statement_analysis_frame(
            analysis_report,
            "dat_en_cours_client",
            customer_id=customer_id_text,
            currency=currency_text,
            all_currencies=all_currencies,
        )
        append_table(
            "DAT en cours",
            active_dat,
            {
                "savings_id": "DAT",
                "date_approved": "Souscription",
                "maturity_date": "Échéance",
                "jours_avant_echeance": "Jours restants",
                "currency_code": "Devise",
                "balance": "Capital bloqué",
                "capital_plus_interet_estime": "Capital + intérêt estimé",
            },
            [2.7, 2.3, 2.3, 2.2, 1.2, 2.8, 3.6],
        )

    append_table(
        "Détail des transactions",
        detail,
        {
            "date": "Date",
            "reference": "Référence",
            "devise": "Devise",
            "operation": "Opération",
            "entree_epargne": "Entrée épargne",
            "sortie_epargne": "Sortie épargne",
            "pret_net_recu": "Prêt net reçu",
            "remboursement_paye": "Remboursement payé",
            "frais_interets": "Frais/intérêts",
            "position_epargne": "Position épargne",
        },
        [1.5, 2.0, 0.9, 4.0, 1.6, 1.6, 1.5, 1.8, 1.5, 1.8],
    )

    def draw_footer(canvas: Any, doc: Any) -> None:
        canvas.saveState()
        canvas.setFont("Helvetica", 7)
        canvas.setFillColor(colors.HexColor("#6E7D8C"))
        footer = f"Extrait généré le {generated_at:%d/%m/%Y %H:%M} - Solution Bisou Bisou Digital - Page {doc.page}"
        canvas.drawCentredString(A4[0] / 2, 0.45 * cm, footer)
        canvas.restoreState()

    document.build(story, onFirstPage=draw_footer, onLaterPages=draw_footer)
    return buffer.getvalue()


def build_filtered_turbo_balance_report(
    report: dict[str, Any],
    filtered_client_balance: pd.DataFrame,
) -> dict[str, pd.DataFrame]:
    """Construit le périmètre d'export depuis la balance client filtrée.

    Les totaux et la balance par type de compte sont recalculés sur les seuls
    couples ``customer_id x devise`` visibles à l'écran. Cette fonction évite
    qu'un Word ou un PDF filtré conserve silencieusement les autres clients.
    """
    selected = (
        filtered_client_balance.copy()
        if isinstance(filtered_client_balance, pd.DataFrame)
        else pd.DataFrame()
    )
    period = report.get("periode", pd.DataFrame())
    period = period.copy() if isinstance(period, pd.DataFrame) else pd.DataFrame()
    if selected.empty:
        return {
            "periode": period,
            "synthese": pd.DataFrame(),
            "balance_clients": pd.DataFrame(),
            "balance_comptes": pd.DataFrame(),
            "selection": pd.DataFrame(),
        }

    for column in ["customer_id", "currency_code"]:
        if column not in selected.columns:
            raise ValueError(
                f"La colonne {column} est requise pour exporter la balance client filtrée."
            )

    monetary_columns = [
        "total_debit",
        "total_credit",
        "solde_debiteur_mouvement",
        "solde_crediteur_mouvement",
        "depots_epargne_observes",
        "retraits_epargne_observes",
        "mouvement_net_epargne_observe",
        "avoirs_epargne_observes",
        "encours_principal_observe",
    ]
    count_columns = ["nombre_lignes", "nombre_operations", "operations_a_verifier"]
    for column in monetary_columns + count_columns:
        if column not in selected.columns:
            selected[column] = 0.0
        selected[column] = pd.to_numeric(selected[column], errors="coerce").fillna(0.0)

    summary_rows: list[dict[str, object]] = []
    for currency, group in selected.groupby("currency_code", sort=True, dropna=False):
        operations = int(group["nombre_operations"].sum())
        operations_to_review = int(group["operations_a_verifier"].sum())
        summary_rows.append(
            {
                "currency_code": currency,
                "nombre_clients": int(group["customer_id"].astype("string").nunique()),
                "nombre_lignes": int(group["nombre_lignes"].sum()),
                "nombre_operations": operations,
                "operations_a_verifier": operations_to_review,
                "operations_symetriques": max(operations - operations_to_review, 0),
                "taux_operations_symetriques_pct": (
                    100 * max(operations - operations_to_review, 0) / operations
                    if operations
                    else np.nan
                ),
                **{
                    column: float(group[column].sum())
                    for column in monetary_columns
                },
                "source_mouvements": "Transactions",
                "role_g2": "Nom client et controle uniquement",
            }
        )
    summary = pd.DataFrame(summary_rows)
    if not period.empty:
        for column in ["date_debut", "date_fin"]:
            if column in period.columns:
                summary[column] = period.iloc[0].get(column)

    selected_keys = selected[["customer_id", "currency_code"]].drop_duplicates().copy()
    selected_keys["__customer_key"] = clean_identifier(selected_keys["customer_id"])
    selected_keys["__currency_key"] = clean_text(selected_keys["currency_code"]).str.upper()
    selected_keys = selected_keys[["__customer_key", "__currency_key"]].drop_duplicates()

    entries = report.get("journal_ecritures", pd.DataFrame())
    entries = entries.copy() if isinstance(entries, pd.DataFrame) else pd.DataFrame()
    account_balance = pd.DataFrame()
    if not entries.empty and {"customer_id", "currency_code", "account_type", "dr", "cr"}.issubset(entries.columns):
        entries["__customer_key"] = clean_identifier(entries["customer_id"])
        entries["__currency_key"] = clean_text(entries["currency_code"]).str.upper()
        entries = entries.merge(
            selected_keys.assign(__selected=True),
            on=["__customer_key", "__currency_key"],
            how="inner",
        )
        if not entries.empty:
            entries["dr"] = numeric_column(entries, "dr")
            entries["cr"] = numeric_column(entries, "cr")
            entries["created_at"] = pd.to_datetime(
                entries.get("created_at", pd.Series(pd.NaT, index=entries.index)),
                errors="coerce",
            )
            entries["__line_id"] = np.arange(len(entries))
            if "cle_operation_turbo" not in entries.columns:
                entries["cle_operation_turbo"] = clean_identifier(
                    entries.get("ref_no", pd.Series("", index=entries.index))
                )
                missing_operation = entries["cle_operation_turbo"].eq("")
                entries.loc[missing_operation, "cle_operation_turbo"] = (
                    "LIGNE-" + entries.loc[missing_operation, "__line_id"].astype("string")
                )
            account_balance = (
                entries.groupby(
                    ["currency_code", "account_type"],
                    as_index=False,
                    dropna=False,
                )
                .agg(
                    total_debit=("dr", "sum"),
                    total_credit=("cr", "sum"),
                    nombre_lignes=("__line_id", "size"),
                    nombre_operations=("cle_operation_turbo", "nunique"),
                    nombre_clients=("customer_id", "nunique"),
                    premiere_ecriture=("created_at", "min"),
                    derniere_ecriture=("created_at", "max"),
                )
            )
            account_balance["ecart_debit_credit"] = (
                account_balance["total_debit"] - account_balance["total_credit"]
            )
            account_balance["solde_debiteur_mouvement"] = account_balance[
                "ecart_debit_credit"
            ].clip(lower=0)
            account_balance["solde_crediteur_mouvement"] = (
                -account_balance["ecart_debit_credit"]
            ).clip(lower=0)
            account_balance = account_balance.sort_values(
                ["currency_code", "account_type"]
            ).reset_index(drop=True)

    selection = pd.DataFrame(
        [
            {
                "nombre_lignes_client_devise": int(len(selected)),
                "nombre_clients": int(selected["customer_id"].astype("string").nunique()),
                "devises": concat_unique(selected["currency_code"]),
            }
        ]
    )
    return {
        "periode": period,
        "synthese": summary,
        "balance_clients": selected.reset_index(drop=True),
        "balance_comptes": account_balance,
        "selection": selection,
    }


def build_filtered_turbo_daily_balance_report(
    report: dict[str, Any],
    filtered_client_balance: pd.DataFrame,
) -> dict[str, pd.DataFrame]:
    """Construit la balance journalière sur les clients et devises filtrés.

    Le grain de restitution est ``date x customer_id x devise``. Les montants
    sont les mouvements Turbo du jour et ne sont jamais additionnés entre
    devises.
    """
    selected = (
        filtered_client_balance.copy()
        if isinstance(filtered_client_balance, pd.DataFrame)
        else pd.DataFrame()
    )
    daily = report.get("balance_clients_par_date", pd.DataFrame())
    daily = daily.copy() if isinstance(daily, pd.DataFrame) else pd.DataFrame()
    period = report.get("periode", pd.DataFrame())
    period = period.copy() if isinstance(period, pd.DataFrame) else pd.DataFrame()
    empty_result = {
        "periode": period,
        "synthese": pd.DataFrame(),
        "balance_clients": pd.DataFrame(),
        "balance_clients_par_date": pd.DataFrame(),
        "selection": pd.DataFrame(),
    }
    if selected.empty or daily.empty:
        return empty_result

    required_keys = {"customer_id", "currency_code"}
    if not required_keys.issubset(selected.columns):
        missing = ", ".join(sorted(required_keys.difference(selected.columns)))
        raise ValueError(
            f"Colonne(s) requise(s) absente(s) pour la balance par date : {missing}."
        )
    if not required_keys.union({"date_operation"}).issubset(daily.columns):
        return empty_result

    selected_keys = selected[["customer_id", "currency_code"]].drop_duplicates()
    selected_keys["__customer_key"] = clean_identifier(
        selected_keys["customer_id"]
    )
    selected_keys["__currency_key"] = clean_text(
        selected_keys["currency_code"]
    ).str.upper()
    selected_keys = selected_keys[
        ["__customer_key", "__currency_key"]
    ].drop_duplicates()

    daily["__customer_key"] = clean_identifier(daily["customer_id"])
    daily["__currency_key"] = clean_text(daily["currency_code"]).str.upper()
    daily = daily.merge(
        selected_keys.assign(__selected=True),
        on=["__customer_key", "__currency_key"],
        how="inner",
    ).drop(columns=["__customer_key", "__currency_key", "__selected"])
    if daily.empty:
        return empty_result

    daily["date_operation"] = pd.to_datetime(
        daily["date_operation"], errors="coerce"
    ).dt.normalize()
    daily = daily.dropna(subset=["date_operation"]).copy()
    if daily.empty:
        return empty_result

    monetary_columns = [
        "depots_epargne_observes",
        "retraits_epargne_observes",
        "mouvement_net_epargne_observe",
        "depots_dat_observes",
        "retraits_dat_observes",
        "mouvement_net_dat_observe",
        "total_debit",
        "total_credit",
        "solde_debiteur_mouvement",
        "solde_crediteur_mouvement",
    ]
    count_columns = [
        "nombre_operations",
        "nombre_lignes",
        "operations_a_verifier",
        "nombre_depots_dat_observes",
        "nombre_retraits_dat_observes",
    ]
    for column in monetary_columns + count_columns:
        if column not in daily.columns:
            daily[column] = 0.0
        daily[column] = pd.to_numeric(
            daily[column], errors="coerce"
        ).fillna(0.0)

    summary_rows: list[dict[str, object]] = []
    for currency, group in daily.groupby(
        "currency_code", sort=True, dropna=False
    ):
        summary_rows.append(
            {
                "currency_code": currency,
                "nombre_dates": int(group["date_operation"].nunique()),
                "nombre_clients": int(
                    clean_identifier(group["customer_id"]).nunique()
                ),
                "nombre_operations": int(group["nombre_operations"].sum()),
                "nombre_lignes": int(group["nombre_lignes"].sum()),
                **{
                    column: float(group[column].sum())
                    for column in monetary_columns
                },
                "source_mouvements": "Transactions",
                "role_g2": "Nom client et controle uniquement",
            }
        )
    summary = pd.DataFrame(summary_rows)
    if not period.empty:
        for column in ["date_debut", "date_fin"]:
            if column in period.columns:
                summary[column] = period.iloc[0].get(column)

    daily = daily.sort_values(
        ["date_operation", "currency_code", "customer_id"]
    ).reset_index(drop=True)
    selection = pd.DataFrame(
        [
            {
                "nombre_lignes_date_client_devise": int(len(daily)),
                "nombre_dates": int(daily["date_operation"].nunique()),
                "nombre_clients": int(
                    clean_identifier(daily["customer_id"]).nunique()
                ),
                "devises": concat_unique(daily["currency_code"]),
            }
        ]
    )
    return {
        "periode": period,
        "synthese": summary,
        "balance_clients": daily,
        "balance_clients_par_date": daily,
        "selection": selection,
    }


def build_filtered_turbo_deposit_withdrawal_pivot_report(
    report: dict[str, Any],
    filtered_client_balance: pd.DataFrame,
    *,
    account_family: str = "compte_ouvert",
) -> dict[str, pd.DataFrame]:
    """Construit le suivi pivot depots/retraits inspire du releve Vodacom.

    Le tableau conserve une ligne par client, operation et devise. Les colonnes
    journalieres affichent les montants observes sur le compte choisi; le score
    mesure la frequence de l'operation sur le nombre de jours couverts par la
    periode filtree.
    """
    normalized_family = normalize_label(account_family)
    is_dat_follow_up = normalized_family in {"dat", "fixed savings", "compte bloque"}
    amount_columns = (
        {
            "depot": "depots_dat_observes",
            "retrait": "retraits_dat_observes",
            "nombre_depot": "nombre_depots_dat_observes",
            "nombre_retrait": "nombre_retraits_dat_observes",
            "solde": "solde_dat_observe",
            "result_key": "suivi_depots_retraits_dat_pivot",
            "famille": "DAT",
            "source_mouvements": "Transactions - FIXED SAVINGS",
        }
        if is_dat_follow_up
        else {
            "depot": "depots_epargne_observes",
            "retrait": "retraits_epargne_observes",
            "nombre_depot": "nombre_depots_epargne_observes",
            "nombre_retrait": "nombre_retraits_epargne_observes",
            "solde": "solde_epargne_courante_observe",
            "result_key": "suivi_depots_retraits_pivot",
            "famille": "Compte ouvert",
            "source_mouvements": "Transactions - NORMAL SAVINGS",
        }
    )
    daily_report = build_filtered_turbo_daily_balance_report(
        report,
        filtered_client_balance,
    )
    daily = daily_report.get("balance_clients_par_date", pd.DataFrame())
    daily = daily.copy() if isinstance(daily, pd.DataFrame) else pd.DataFrame()
    period = daily_report.get("periode", pd.DataFrame())
    period = period.copy() if isinstance(period, pd.DataFrame) else pd.DataFrame()
    empty_result = {
        "periode": period,
        "synthese": pd.DataFrame(),
        "balance_clients": pd.DataFrame(),
        "balance_clients_par_date": daily,
        "suivi_depots_retraits_pivot": pd.DataFrame(),
        "suivi_depots_retraits_dat_pivot": pd.DataFrame(),
        "selection": pd.DataFrame(),
    }
    if daily.empty or not {"date_operation", "customer_id", "currency_code"}.issubset(daily.columns):
        return empty_result

    daily["date_operation"] = pd.to_datetime(
        daily["date_operation"], errors="coerce"
    ).dt.normalize()
    daily = daily.dropna(subset=["date_operation"]).copy()
    if daily.empty:
        return empty_result

    start = pd.NaT
    end = pd.NaT
    if not period.empty:
        if "date_debut" in period.columns:
            start = pd.to_datetime(period.iloc[0].get("date_debut"), errors="coerce")
        if "date_fin" in period.columns:
            end = pd.to_datetime(period.iloc[0].get("date_fin"), errors="coerce")
    if pd.isna(start):
        start = daily["date_operation"].min()
    if pd.isna(end):
        end = daily["date_operation"].max()
    start = pd.Timestamp(start).normalize()
    end = pd.Timestamp(end).normalize()
    if start > end:
        start, end = end, start
    date_index = pd.date_range(start, end, freq="D")
    if date_index.empty:
        return empty_result
    date_columns = [f"{date:%d/%m/%Y}" for date in date_index]
    day_count = max(int(len(date_index)), 1)

    selected_positions = (
        filtered_client_balance.copy()
        if isinstance(filtered_client_balance, pd.DataFrame)
        else pd.DataFrame()
    )
    position_lookup: dict[tuple[str, str], float] = {}
    if not selected_positions.empty and {
        "customer_id",
        "currency_code",
        amount_columns["solde"],
    }.issubset(selected_positions.columns):
        selected_positions["__customer_key"] = clean_identifier(
            selected_positions["customer_id"]
        )
        selected_positions["__currency_key"] = clean_text(
            selected_positions["currency_code"]
        ).str.upper()
        selected_positions[amount_columns["solde"]] = pd.to_numeric(
            selected_positions[amount_columns["solde"]],
            errors="coerce",
        ).fillna(0.0)
        position_lookup = {
            (row["__customer_key"], row["__currency_key"]): float(
                row[amount_columns["solde"]]
            )
            for _, row in selected_positions.iterrows()
        }

    for column in [
        amount_columns["depot"],
        amount_columns["retrait"],
        amount_columns["nombre_depot"],
        amount_columns["nombre_retrait"],
    ]:
        if column not in daily.columns:
            daily[column] = 0.0
        daily[column] = pd.to_numeric(daily[column], errors="coerce").fillna(0.0)

    rows: list[dict[str, object]] = []
    group_keys = ["customer_id", "currency_code"]
    for (customer_id, currency_code), group in daily.groupby(group_keys, sort=True, dropna=False):
        group = group.copy()
        name_text = concat_unique(group.get("Nom_client", pd.Series("", index=group.index)))
        phone_text = concat_unique(group.get("telephone", pd.Series("", index=group.index)))
        customer_text = str(customer_id)
        client_label = (
            f"{customer_text} - {name_text}"
            if not _is_empty_text(name_text)
            else customer_text
        )
        deposit_total = float(group[amount_columns["depot"]].sum())
        withdrawal_total = float(group[amount_columns["retrait"]].sum())
        period_balance = deposit_total - withdrawal_total
        client_key = clean_identifier(pd.Series([customer_id])).iloc[0]
        currency_key = clean_text(pd.Series([currency_code])).str.upper().iloc[0]
        client_position_balance = position_lookup.get(
            (client_key, currency_key),
            period_balance,
        )
        for operation, amount_column, count_column in [
            ("Depot", amount_columns["depot"], amount_columns["nombre_depot"]),
            ("Retrait", amount_columns["retrait"], amount_columns["nombre_retrait"]),
        ]:
            operation_count = int(group[count_column].sum())
            score_pct = 100 * operation_count / day_count if day_count else np.nan
            row: dict[str, object] = {
                "customer_id": customer_id,
                "Nom_client": name_text,
                "telephone": phone_text,
                "client": client_label,
                "operation": operation,
                "famille_compte": amount_columns["famille"],
                "currency_code": currency_code,
                "nombre_operations_suivi": operation_count,
                "nombre_jours_periode": day_count,
                "score_pct": score_pct,
                "score": (
                    f"{operation_count} / {day_count} jour(s)"
                    + (f" ({score_pct:.1f}%)" if pd.notna(score_pct) else "")
                ),
                "total": float(group[amount_column].sum()),
                "solde": client_position_balance,
            }
            daily_amounts = (
                group.groupby("date_operation", dropna=False)[amount_column]
                .sum()
                .to_dict()
            )
            for date_value, column_label in zip(date_index, date_columns):
                row[column_label] = float(daily_amounts.get(date_value, 0.0))
            rows.append(row)

    pivot = pd.DataFrame(rows)
    if not pivot.empty:
        pivot = pivot[
            [
                "client",
                "operation",
                "famille_compte",
                "currency_code",
                *date_columns,
                "total",
                "solde",
                "score",
                "customer_id",
                "Nom_client",
                "telephone",
                "nombre_operations_suivi",
                "nombre_jours_periode",
                "score_pct",
            ]
        ].sort_values(["currency_code", "client", "operation"]).reset_index(drop=True)

    summary_rows: list[dict[str, object]] = []
    for currency_code, group in pivot.groupby("currency_code", sort=True, dropna=False):
        deposits = group.loc[group["operation"].eq("Depot")]
        withdrawals = group.loc[group["operation"].eq("Retrait")]
        total_deposits = float(deposits["total"].sum()) if not deposits.empty else 0.0
        total_withdrawals = float(withdrawals["total"].sum()) if not withdrawals.empty else 0.0
        summary_rows.append(
            {
                "currency_code": currency_code,
                "nombre_clients": int(clean_identifier(group["customer_id"]).nunique()),
                "nombre_jours_periode": day_count,
                "total_depots": total_deposits,
                "total_retraits": total_withdrawals,
                "solde_net_periode": total_deposits - total_withdrawals,
                "nombre_depots": int(deposits["nombre_operations_suivi"].sum()) if not deposits.empty else 0,
                "nombre_retraits": int(withdrawals["nombre_operations_suivi"].sum()) if not withdrawals.empty else 0,
                "famille_compte": amount_columns["famille"],
                "source_mouvements": amount_columns["source_mouvements"],
            }
        )
    summary = pd.DataFrame(summary_rows)
    if not period.empty:
        for column in ["date_debut", "date_fin"]:
            if column in period.columns:
                summary[column] = period.iloc[0].get(column)
    selection = pd.DataFrame(
        [
            {
                "nombre_lignes_pivot": int(len(pivot)),
                "nombre_clients": int(clean_identifier(pivot["customer_id"]).nunique()) if not pivot.empty else 0,
                "nombre_jours_periode": day_count,
                "devises": concat_unique(pivot.get("currency_code", pd.Series(dtype="string"))),
            }
        ]
    )
    return {
        "periode": period,
        "synthese": summary,
        "balance_clients": pivot,
        "balance_clients_par_date": daily,
        amount_columns["result_key"]: pivot,
        "suivi_depots_retraits_pivot": (
            pd.DataFrame() if is_dat_follow_up else pivot
        ),
        "suivi_depots_retraits_dat_pivot": (
            pivot if is_dat_follow_up else pd.DataFrame()
        ),
        "selection": selection,
    }


def _turbo_balance_export_frames(
    report: dict[str, Any],
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Normalise les deux tables retenues dans la balance exportée."""
    summary = report.get("synthese", pd.DataFrame())
    client_balance = report.get("balance_clients", pd.DataFrame())
    summary = summary.copy() if isinstance(summary, pd.DataFrame) else pd.DataFrame()
    client_balance = (
        client_balance.copy()
        if isinstance(client_balance, pd.DataFrame)
        else pd.DataFrame()
    )
    if client_balance.empty:
        raise ValueError("Aucune balance client n'est disponible pour l'export.")
    return summary, client_balance


def _turbo_balance_period_text(
    report: dict[str, Any],
    period_start: object | None,
    period_end: object | None,
) -> tuple[str, str]:
    period = report.get("periode", pd.DataFrame())
    start = pd.to_datetime(period_start, errors="coerce")
    end = pd.to_datetime(period_end, errors="coerce")
    if isinstance(period, pd.DataFrame) and not period.empty:
        if pd.isna(start) and "date_debut" in period.columns:
            start = pd.to_datetime(period.iloc[0].get("date_debut"), errors="coerce")
        if pd.isna(end) and "date_fin" in period.columns:
            end = pd.to_datetime(period.iloc[0].get("date_fin"), errors="coerce")
    start_text = f"{start:%d/%m/%Y}" if pd.notna(start) else "Non disponible"
    end_text = f"{end:%d/%m/%Y}" if pd.notna(end) else "Non disponible"
    return start_text, end_text


def _turbo_balance_criteria_rows(
    client_balance: pd.DataFrame,
    *,
    start_text: str,
    end_text: str,
    balance_by_date: bool = False,
) -> list[tuple[str, str]]:
    """Présente le périmètre filtré comme dans l'extrait client officiel."""
    customer_count = (
        int(clean_identifier(client_balance["customer_id"]).nunique())
        if "customer_id" in client_balance.columns
        else 0
    )
    if "currency_code" in client_balance.columns:
        currencies = sorted(
            value
            for value in clean_text(client_balance["currency_code"])
            .str.upper()
            .dropna()
            .unique()
            if value
        )
    else:
        currencies = []
    currency_text = ", ".join(currencies) or "Non disponible"
    perimeter_text = (
        f"{len(client_balance)} ligne(s) client × opération × devise"
        if balance_by_date
        else f"{len(client_balance)} ligne(s) client × devise"
    )
    rows = [
        ("Date du :", start_text),
        ("Au :", end_text),
        ("Clients :", f"{customer_count} client(s)"),
        ("Périmètre :", perimeter_text),
        ("Devise(s) :", currency_text),
    ]
    if balance_by_date and "date_operation" in client_balance.columns:
        date_count = int(
            pd.to_datetime(
                client_balance["date_operation"], errors="coerce"
            ).dt.normalize().nunique()
        )
        rows.insert(3, ("Dates avec mouvements :", f"{date_count} date(s)"))
    elif balance_by_date and "nombre_jours_periode" in client_balance.columns:
        date_count = int(
            pd.to_numeric(client_balance["nombre_jours_periode"], errors="coerce")
            .fillna(0)
            .max()
        )
        rows.insert(3, ("Jours couverts :", f"{date_count} jour(s)"))
    return rows


def create_turbo_balance_word(
    report: dict[str, Any],
    *,
    period_start: object | None = None,
    period_end: object | None = None,
    generated_at: pd.Timestamp | None = None,
    balance_by_date: bool = False,
) -> bytes:
    """Génère la balance observée en Word pour la Direction."""
    try:
        from docx import Document
        from docx.enum.table import WD_CELL_VERTICAL_ALIGNMENT, WD_TABLE_ALIGNMENT
        from docx.enum.text import WD_ALIGN_PARAGRAPH
        from docx.oxml import OxmlElement
        from docx.oxml.ns import qn
        from docx.shared import Cm, Pt, RGBColor
    except ImportError as exc:
        raise RuntimeError("La dépendance python-docx est requise pour générer la balance Word.") from exc

    summary, client_balance = _turbo_balance_export_frames(report)
    start_text, end_text = _turbo_balance_period_text(
        report, period_start, period_end
    )
    criteria_rows = _turbo_balance_criteria_rows(
        client_balance,
        start_text=start_text,
        end_text=end_text,
        balance_by_date=balance_by_date,
    )
    generated_at = generated_at if generated_at is not None else pd.Timestamp.now()

    document = Document()
    section = document.sections[0]
    section.top_margin = Cm(0.9)
    section.bottom_margin = Cm(1.0)
    section.left_margin = Cm(2.0)
    section.right_margin = Cm(2.0)
    document.styles["Normal"].font.name = "Aptos"
    document.styles["Normal"].font.size = Pt(7.5)

    def shade(cell: Any, fill: str) -> None:
        properties = cell._tc.get_or_add_tcPr()
        shading = OxmlElement("w:shd")
        shading.set(qn("w:fill"), fill)
        properties.append(shading)

    def repeat_header(row: Any) -> None:
        properties = row._tr.get_or_add_trPr()
        repeat = OxmlElement("w:tblHeader")
        repeat.set(qn("w:val"), "true")
        properties.append(repeat)

    header = document.add_table(rows=2, cols=2)
    header.alignment = WD_TABLE_ALIGNMENT.CENTER
    header.autofit = False
    logo_cell = header.cell(0, 0).merge(header.cell(1, 0))
    logo_cell.width = Cm(10.2)
    logo_cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
    logo_cell.paragraphs[0].paragraph_format.space_after = Pt(0)
    if CUSTOMER_STATEMENT_LOGO_PATH.is_file():
        try:
            logo_cell.paragraphs[0].add_run().add_picture(
                str(CUSTOMER_STATEMENT_LOGO_PATH), width=Cm(4.6)
            )
        except (OSError, ValueError):
            logo_cell.text = "IMF Microfinance Bisou Bisou"
    else:
        logo_cell.text = "IMF Microfinance Bisou Bisou"

    criteria_title = header.cell(0, 1)
    criteria_title.width = Cm(8.0)
    criteria_title.text = "Critères"
    criteria_title.paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
    shade(criteria_title, "1F2937")
    for run in criteria_title.paragraphs[0].runs:
        run.bold = True
        run.font.size = Pt(10)
        run.font.color.rgb = RGBColor(255, 255, 255)

    criteria_cell = header.cell(1, 1)
    criteria_cell.width = Cm(8.0)
    criteria = criteria_cell.add_table(rows=len(criteria_rows), cols=2)
    criteria.style = "Table Grid"
    criteria.autofit = False
    for row_index, (label, value) in enumerate(criteria_rows):
        criteria.cell(row_index, 0).text = label
        criteria.cell(row_index, 1).text = value
        criteria.cell(row_index, 0).width = Cm(3.4)
        criteria.cell(row_index, 1).width = Cm(4.6)
        for run in criteria.cell(row_index, 0).paragraphs[0].runs:
            run.bold = True
            run.font.size = Pt(8)
        for run in criteria.cell(row_index, 1).paragraphs[0].runs:
            run.font.size = Pt(8)
    criteria_cell.paragraphs[0].paragraph_format.space_after = Pt(0)

    title = document.add_paragraph()
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER
    title.paragraph_format.space_after = Pt(2)
    title_run = title.add_run(
        (
            "Suivi des dépôts et retraits - Solution M_PESA"
            if balance_by_date
            else "Balance auxiliaire observée - Solution M_PESA"
        )
    )
    title_run.bold = True
    title_run.font.size = Pt(16)
    title_run.font.color.rgb = RGBColor(18, 56, 95)

    def add_heading(text: str) -> None:
        paragraph = document.add_paragraph()
        paragraph.paragraph_format.space_before = Pt(5)
        paragraph.paragraph_format.space_after = Pt(2)
        run = paragraph.add_run(text)
        run.bold = True
        run.font.size = Pt(10.5)
        run.font.color.rgb = RGBColor(18, 56, 95)

    def add_table(
        frame: pd.DataFrame,
        columns: list[str],
        labels: dict[str, str],
    ) -> None:
        present = [column for column in columns if column in frame.columns]
        if frame.empty or not present:
            document.add_paragraph("Aucune donnée disponible.")
            return
        table = document.add_table(rows=1, cols=len(present))
        table.style = "Table Grid"
        table.alignment = WD_TABLE_ALIGNMENT.CENTER
        table.autofit = True
        repeat_header(table.rows[0])
        for index, column in enumerate(present):
            cell = table.rows[0].cells[index]
            cell.text = labels.get(column, column)
            shade(cell, "1F4E78")
            cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
            for run in cell.paragraphs[0].runs:
                run.bold = True
                run.font.size = Pt(6.7)
                run.font.color.rgb = RGBColor(255, 255, 255)
        for _, row in frame.iterrows():
            cells = table.add_row().cells
            row_currency = str(row.get("currency_code", "")).upper()
            row_decimals = 0 if row_currency == "CDF" else 2
            for index, column in enumerate(present):
                value = row.get(column)
                if column in {
                    "date_operation",
                    "premiere_ecriture",
                    "derniere_ecriture",
                }:
                    parsed = pd.to_datetime(value, errors="coerce")
                    text = f"{parsed:%d/%m/%Y}" if pd.notna(parsed) else "-"
                elif column.endswith("_pct"):
                    number = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
                    text = f"{number:.1f}%" if pd.notna(number) else "-"
                elif any(
                    token in column
                    for token in [
                        "total", "solde", "avoirs", "encours", "ecart",
                        "depot", "retrait", "mouvement",
                    ]
                ) or re.fullmatch(r"\d{2}/\d{2}/\d{4}", str(column)):
                    text = _pdf_number(value, decimals=row_decimals)
                else:
                    text = "-" if _is_empty_text(value) else str(value)
                cells[index].text = text
                cells[index].vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
                for paragraph in cells[index].paragraphs:
                    paragraph.paragraph_format.space_after = Pt(0)
                    for run in paragraph.runs:
                        run.font.size = Pt(6.2)

    add_heading("Synthèse par devise")
    if balance_by_date:
        date_columns = [
            column
            for column in client_balance.columns
            if re.fullmatch(r"\d{2}/\d{2}/\d{4}", str(column))
        ]
        add_table(
            summary,
            [
                "currency_code",
                "nombre_clients",
                "nombre_jours_periode",
                "total_depots",
                "total_retraits",
                "solde_net_periode",
                "nombre_depots",
                "nombre_retraits",
            ],
            {
                "currency_code": "Devise",
                "nombre_clients": "Clients",
                "nombre_jours_periode": "Jours",
                "total_depots": "Total dépôts",
                "total_retraits": "Total retraits",
                "solde_net_periode": "Solde",
                "nombre_depots": "Nb dépôts",
                "nombre_retraits": "Nb retraits",
            },
        )
        add_heading("Tableau croisé dépôts et retraits par client")
        add_table(
            client_balance,
            [
                "client",
                "operation",
                "currency_code",
                *date_columns,
                "total",
                "solde",
                "score",
            ],
            {
                "client": "Client",
                "operation": "Opération",
                "currency_code": "Devise",
                **{column: column[:5] for column in date_columns},
                "total": "Total",
                "solde": "Solde",
                "score": "Score",
            },
        )
    else:
        add_table(
            summary,
            [
                "currency_code", "nombre_clients",
                "depots_epargne_observes", "retraits_epargne_observes",
                "mouvement_net_epargne_observe", "avoirs_epargne_observes",
                "encours_principal_observe",
            ],
            {
                "currency_code": "Devise",
                "nombre_clients": "Clients",
                "depots_epargne_observes": "Dépôts épargne",
                "retraits_epargne_observes": "Retraits épargne",
                "mouvement_net_epargne_observe": "Mouvement net épargne",
                "avoirs_epargne_observes": "Avoirs épargne observés",
                "encours_principal_observe": "Encours principal observé",
            },
        )
        add_heading("Balance par client")
        add_table(
            client_balance,
            [
                "customer_id", "Nom_client", "telephone", "currency_code",
                "depots_epargne_observes", "retraits_epargne_observes",
                "mouvement_net_epargne_observe",
                "solde_epargne_courante_observe", "solde_dat_observe",
                "encours_principal_observe",
            ],
            {
                "customer_id": "Client",
                "Nom_client": "Nom du client",
                "telephone": "Téléphone",
                "currency_code": "Devise",
                "depots_epargne_observes": "Dépôts épargne",
                "retraits_epargne_observes": "Retraits épargne",
                "mouvement_net_epargne_observe": "Mouvement net épargne",
                "solde_epargne_courante_observe": "Épargne courante",
                "solde_dat_observe": "DAT",
                "encours_principal_observe": "Principal crédit",
            },
        )
    footer = section.footer.paragraphs[0]
    footer.alignment = WD_ALIGN_PARAGRAPH.CENTER
    footer_run = footer.add_run(
        f"Balance générée le {generated_at:%d/%m/%Y %H:%M} - "
        "Solution Bisou Bisou Digital"
    )
    footer_run.font.size = Pt(7)
    footer_run.font.color.rgb = RGBColor(110, 125, 140)
    document.core_properties.title = (
        (
            f"Suivi depots retraits - {start_text} au {end_text}"
            if balance_by_date
            else f"Balance observée - {start_text} au {end_text}"
        )
    )
    document.core_properties.subject = "Balance auxiliaire observée destinée à la Direction"
    document.core_properties.author = "Solution Controle Interne"
    buffer = BytesIO()
    document.save(buffer)
    buffer.seek(0)
    return buffer.getvalue()


def create_turbo_balance_pdf(
    report: dict[str, Any],
    *,
    period_start: object | None = None,
    period_end: object | None = None,
    generated_at: pd.Timestamp | None = None,
    balance_by_date: bool = False,
) -> bytes:
    """Génère la balance observée en PDF natif pour la Direction."""
    try:
        from reportlab.lib import colors
        from reportlab.lib.enums import TA_CENTER, TA_RIGHT
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
        from reportlab.lib.units import cm
        from reportlab.platypus import Image, Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle
    except ImportError as exc:
        raise RuntimeError("La dépendance reportlab est requise pour générer la balance PDF.") from exc

    summary, client_balance = _turbo_balance_export_frames(report)
    start_text, end_text = _turbo_balance_period_text(
        report, period_start, period_end
    )
    criteria_rows = _turbo_balance_criteria_rows(
        client_balance,
        start_text=start_text,
        end_text=end_text,
        balance_by_date=balance_by_date,
    )
    generated_at = generated_at if generated_at is not None else pd.Timestamp.now()
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle(
        "TurboBalanceTitle",
        parent=styles["Title"],
        fontName="Helvetica-Bold",
        fontSize=15,
        textColor=colors.HexColor("#12385F"),
        alignment=TA_CENTER,
        spaceAfter=5,
    )
    section_style = ParagraphStyle(
        "TurboBalanceSection",
        parent=styles["Heading3"],
        fontName="Helvetica-Bold",
        fontSize=9.5,
        textColor=colors.HexColor("#12385F"),
        spaceBefore=6,
        spaceAfter=3,
    )
    body_style = ParagraphStyle(
        "TurboBalanceBody",
        parent=styles["BodyText"],
        fontName="Helvetica",
        fontSize=5.7,
        leading=6.8,
    )
    header_style = ParagraphStyle(
        "TurboBalanceHeader",
        parent=body_style,
        fontName="Helvetica-Bold",
        textColor=colors.white,
        alignment=TA_CENTER,
    )
    criteria_header_style = ParagraphStyle(
        "TurboBalanceCriteriaHeader",
        parent=styles["BodyText"],
        fontName="Helvetica-Bold",
        fontSize=8,
        leading=9.5,
        textColor=colors.white,
        alignment=TA_CENTER,
    )
    amount_style = ParagraphStyle(
        "TurboBalanceAmount", parent=body_style, alignment=TA_RIGHT
    )
    buffer = BytesIO()
    document = SimpleDocTemplate(
        buffer,
        pagesize=A4,
        leftMargin=0.8 * cm,
        rightMargin=0.8 * cm,
        topMargin=0.7 * cm,
        bottomMargin=1.0 * cm,
        title=(
            f"Suivi depots retraits - {start_text} au {end_text}"
            if balance_by_date
            else f"Balance observée - {start_text} au {end_text}"
        ),
        author="Solution Controle Interne",
    )
    story: list[Any] = []
    if CUSTOMER_STATEMENT_LOGO_PATH.is_file():
        logo: Any = Image(str(CUSTOMER_STATEMENT_LOGO_PATH), width=3.1 * cm, height=3.1 * cm)
    else:
        logo = Paragraph("<b>IMF Microfinance Bisou Bisou</b>", styles["Heading3"])
    criteria_data: list[list[Any]] = [
        [Paragraph("<b>Critères</b>", criteria_header_style), ""]
    ]
    criteria_data.extend(
        [Paragraph(f"<b>{escape(label)}</b>", body_style), Paragraph(escape(value), body_style)]
        for label, value in criteria_rows
    )
    criteria = Table(criteria_data, colWidths=[3.5 * cm, 4.5 * cm])
    criteria.setStyle(TableStyle([
        ("SPAN", (0, 0), (1, 0)),
        ("BACKGROUND", (0, 0), (1, 0), colors.HexColor("#1F2937")),
        ("GRID", (0, 1), (-1, -1), 0.25, colors.HexColor("#CBD5E1")),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("LEFTPADDING", (0, 0), (-1, -1), 4),
        ("RIGHTPADDING", (0, 0), (-1, -1), 4),
        ("TOPPADDING", (0, 0), (-1, -1), 3),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
    ]))
    masthead = Table([[logo, criteria]], colWidths=[10.0 * cm, 8.0 * cm])
    masthead.setStyle(TableStyle([("VALIGN", (0, 0), (-1, -1), "MIDDLE")]))
    story.extend([masthead, Spacer(1, 0.15 * cm)])
    story.append(
        Paragraph(
            (
                "Suivi des dépôts et retraits - Solution M_PESA"
                if balance_by_date
                else "Balance auxiliaire observée - Solution M_PESA"
            ),
            title_style,
        )
    )

    def append_table(
        title: str,
        frame: pd.DataFrame,
        columns: list[str],
        labels: dict[str, str],
        widths: list[float],
    ) -> None:
        present = [column for column in columns if column in frame.columns]
        if frame.empty or not present:
            return
        rows: list[list[Any]] = [[Paragraph(escape(labels.get(column, column)), header_style) for column in present]]
        for _, row in frame.iterrows():
            row_currency = str(row.get("currency_code", "")).upper()
            decimals = 0 if row_currency == "CDF" else 2
            cells: list[Any] = []
            for column in present:
                value = row.get(column)
                monetary = any(
                    token in column
                    for token in [
                        "total", "solde", "avoirs", "encours", "ecart",
                        "depot", "retrait", "mouvement",
                    ]
                ) or re.fullmatch(r"\d{2}/\d{2}/\d{4}", str(column)) is not None
                if column in {
                    "date_operation",
                    "premiere_ecriture",
                    "derniere_ecriture",
                }:
                    parsed = pd.to_datetime(value, errors="coerce")
                    text_value = (
                        f"{parsed:%d/%m/%Y}" if pd.notna(parsed) else "-"
                    )
                elif column.endswith("_pct"):
                    numeric_value = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
                    text_value = f"{numeric_value:.1f}%" if pd.notna(numeric_value) else "-"
                elif monetary:
                    text_value = _pdf_number(value, decimals=decimals)
                else:
                    text_value = "-" if _is_empty_text(value) else str(value)
                cells.append(
                    Paragraph(
                        escape(text_value), amount_style if monetary else body_style
                    )
                )
            rows.append(cells)
        story.append(Paragraph(title, section_style))
        selected_widths = [widths[columns.index(column)] * cm for column in present]
        table = Table(rows, colWidths=selected_widths, repeatRows=1)
        table.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1F4E78")),
            ("GRID", (0, 0), (-1, -1), 0.22, colors.HexColor("#B7C1CC")),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("LEFTPADDING", (0, 0), (-1, -1), 1.8),
            ("RIGHTPADDING", (0, 0), (-1, -1), 1.8),
            ("TOPPADDING", (0, 0), (-1, -1), 2.1),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 2.1),
        ]))
        story.append(table)

    if balance_by_date:
        date_columns = [
            column
            for column in client_balance.columns
            if re.fullmatch(r"\d{2}/\d{2}/\d{4}", str(column))
        ]
        append_table(
            "Synthèse par devise",
            summary,
            [
                "currency_code",
                "nombre_clients",
                "nombre_jours_periode",
                "total_depots",
                "total_retraits",
                "solde_net_periode",
                "nombre_depots",
                "nombre_retraits",
            ],
            {
                "currency_code": "Devise",
                "nombre_clients": "Clients",
                "nombre_jours_periode": "Jours",
                "total_depots": "Total dépôts",
                "total_retraits": "Total retraits",
                "solde_net_periode": "Solde",
                "nombre_depots": "Nb dépôts",
                "nombre_retraits": "Nb retraits",
            },
            [1.0, 1.0, 0.8, 2.0, 2.0, 1.8, 1.3, 1.3],
        )
        append_table(
            "Tableau croisé dépôts et retraits par client",
            client_balance,
            [
                "client",
                "operation",
                "currency_code",
                *date_columns,
                "total",
                "solde",
                "score",
            ],
            {
                "client": "Client",
                "operation": "Op.",
                "currency_code": "Devise",
                **{column: column[:5] for column in date_columns},
                "total": "Total",
                "solde": "Solde",
                "score": "Score",
            },
            [2.9, 1.1, 0.8, *([0.62] * len(date_columns)), 1.2, 1.2, 1.9],
        )
    else:
        append_table(
            "Synthèse par devise",
            summary,
            [
                "currency_code", "nombre_clients",
                "depots_epargne_observes", "retraits_epargne_observes",
                "mouvement_net_epargne_observe", "avoirs_epargne_observes",
                "encours_principal_observe",
            ],
            {
                "currency_code": "Devise", "nombre_clients": "Clients",
                "depots_epargne_observes": "Dépôts épargne",
                "retraits_epargne_observes": "Retraits épargne",
                "mouvement_net_epargne_observe": "Mouvement net épargne",
                "avoirs_epargne_observes": "Avoirs épargne",
                "encours_principal_observe": "Encours principal",
            },
            [1.2, 1.2, 2.5, 2.5, 2.7, 3.1, 3.1],
        )
        append_table(
            "Balance par client",
            client_balance,
            [
                "customer_id", "Nom_client", "telephone", "currency_code",
                "depots_epargne_observes", "retraits_epargne_observes",
                "mouvement_net_epargne_observe",
                "solde_epargne_courante_observe", "solde_dat_observe",
                "encours_principal_observe",
            ],
            {
                "customer_id": "Client", "Nom_client": "Nom du client", "telephone": "Téléphone",
                "currency_code": "Devise",
                "depots_epargne_observes": "Dépôts épargne",
                "retraits_epargne_observes": "Retraits épargne",
                "mouvement_net_epargne_observe": "Mouvement net épargne",
                "solde_epargne_courante_observe": "Épargne courante",
                "solde_dat_observe": "DAT", "encours_principal_observe": "Principal crédit",
            },
            [1.2, 2.4, 2.0, 0.9, 1.5, 1.5, 1.6, 1.7, 1.3, 1.7],
        )
    def draw_footer(canvas: Any, doc: Any) -> None:
        canvas.saveState()
        canvas.setFont("Helvetica", 7)
        canvas.setFillColor(colors.HexColor("#6E7D8C"))
        canvas.drawCentredString(
            A4[0] / 2,
            0.4 * cm,
            f"Balance générée le {generated_at:%d/%m/%Y %H:%M} - "
            f"Solution Bisou Bisou Digital - Page {doc.page}",
        )
        canvas.restoreState()

    document.build(story, onFirstPage=draw_footer, onLaterPages=draw_footer)
    return buffer.getvalue()


def create_g2_dat_word(
    report: dict[str, Any],
    *,
    period_text: str,
    direction_label: str,
    generated_at: pd.Timestamp | None = None,
) -> bytes:
    """Genere la version Word courte et editable destinee a la Direction generale."""
    try:
        from docx import Document
        from docx.enum.section import WD_ORIENT, WD_SECTION
        from docx.enum.table import WD_CELL_VERTICAL_ALIGNMENT, WD_TABLE_ALIGNMENT
        from docx.enum.text import WD_ALIGN_PARAGRAPH
        from docx.oxml import OxmlElement
        from docx.oxml.ns import qn
        from docx.shared import Cm, Pt, RGBColor
    except ImportError as exc:
        raise RuntimeError("La dependance python-docx est requise pour generer le rapport Word.") from exc

    source_label = str(report.get("analysis_source_label", "G2") or "G2")
    analysis_mode_label = str(report.get("analysis_mode_label", "") or "")
    source_label_normalized = normalize_label(source_label)
    turbo_only = (
        source_label_normalized == "turbo"
        or source_label.casefold().startswith("solution num")
    )
    source_display_label = (
        analysis_mode_label
        if turbo_only and analysis_mode_label
        else "Solution Bisou Bisou Digital"
        if turbo_only
        else "Solution Numérique/G2"
    )
    flow_display_label = "Solution Numérique" if turbo_only else source_display_label
    report_scope = "Solution Numérique / M-Pesa"
    daily_pivot = report.get("rapport_journalier_pivot", pd.DataFrame())
    daily_synthese = report.get("rapport_journalier_synthese", pd.DataFrame())
    transaction_detail = report.get("rapport_journalier_detail", pd.DataFrame())
    eligible_transaction_detail = transaction_detail
    if isinstance(transaction_detail, pd.DataFrame):
        eligible_transaction_detail = transaction_detail.copy()
        if (
            not eligible_transaction_detail.empty
            and "incluse_synthese" in eligible_transaction_detail.columns
        ):
            eligible_word_detail = (
                eligible_transaction_detail["incluse_synthese"]
                .astype("boolean")
                .fillna(False)
                .astype(bool)
            )
            eligible_transaction_detail = eligible_transaction_detail.loc[eligible_word_detail].copy()
    if not isinstance(daily_pivot, pd.DataFrame) or daily_pivot.empty:
        daily_pivot = build_entry_pivot(eligible_transaction_detail)
    generated_at = generated_at if generated_at is not None else pd.Timestamp.now()
    word_report = dict(report)
    word_report["rapport_journalier_pivot"] = daily_pivot
    context = _g2_executive_context(word_report)
    period_start_text, period_end_text = _g2_report_period_boundary_texts(word_report)
    transaction_detail = eligible_transaction_detail

    classified = daily_synthese.copy()
    if not classified.empty and "details_rapport" in classified.columns:
        classified = classified.loc[
            ~classified["details_rapport"].astype("string").str.startswith("Total ", na=False)
        ]

    document = Document()
    section = document.sections[0]
    section.orientation = WD_ORIENT.PORTRAIT
    section.page_width = Cm(21.0)
    section.page_height = Cm(29.7)
    section.top_margin = Cm(1.2)
    section.bottom_margin = Cm(1.2)
    section.left_margin = Cm(2.0)
    section.right_margin = Cm(2.0)
    section.start_type = WD_SECTION.NEW_PAGE

    styles = document.styles
    styles["Normal"].font.name = "Aptos"
    styles["Normal"].font.size = Pt(9)
    for style_name in ["Title", "Heading 1", "Heading 2"]:
        styles[style_name].font.name = "Aptos Display"
        styles[style_name].font.color.rgb = RGBColor(18, 56, 95)
    styles["Title"].font.size = Pt(22)
    styles["Heading 1"].font.size = Pt(14)
    styles["Heading 2"].font.size = Pt(11)

    def set_cell_shading(cell: Any, fill: str) -> None:
        cell_properties = cell._tc.get_or_add_tcPr()
        shading = OxmlElement("w:shd")
        shading.set(qn("w:fill"), fill)
        cell_properties.append(shading)

    header = document.add_table(rows=2, cols=2)
    header.alignment = WD_TABLE_ALIGNMENT.CENTER
    header.autofit = False
    brand_cell = header.cell(0, 0).merge(header.cell(1, 0))
    brand_cell.width = Cm(9.5)
    brand_cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
    brand_paragraph = brand_cell.paragraphs[0]
    brand_paragraph.paragraph_format.space_after = Pt(0)
    if CUSTOMER_STATEMENT_LOGO_PATH.is_file():
        try:
            brand_paragraph.add_run().add_picture(
                str(CUSTOMER_STATEMENT_LOGO_PATH), width=Cm(4.6)
            )
        except (OSError, ValueError):
            brand_run = brand_paragraph.add_run("IMF Microfinance Bisou Bisou")
            brand_run.bold = True
            brand_run.font.size = Pt(16)
    else:
        brand_run = brand_paragraph.add_run("IMF Microfinance Bisou Bisou")
        brand_run.bold = True
        brand_run.font.size = Pt(16)

    criteria_title = header.cell(0, 1)
    criteria_title.width = Cm(8.5)
    criteria_title.text = "Critères"
    criteria_title.paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
    set_cell_shading(criteria_title, "1F2937")
    for run in criteria_title.paragraphs[0].runs:
        run.bold = True
        run.font.size = Pt(10)
        run.font.color.rgb = RGBColor(255, 255, 255)

    criteria_cell = header.cell(1, 1)
    criteria_cell.width = Cm(8.5)
    criteria = criteria_cell.add_table(rows=5, cols=2)
    criteria.autofit = False
    criteria_rows = [
        ("Date du :", period_start_text),
        ("Au :", period_end_text),
        ("Sens :", direction_label),
        ("Source :", source_display_label),
        ("Généré le :", f"{generated_at:%d/%m/%Y}"),
    ]
    for row_index, (label, value) in enumerate(criteria_rows):
        criteria.cell(row_index, 0).text = label
        criteria.cell(row_index, 1).text = str(value)
        criteria.cell(row_index, 0).width = Cm(3.1)
        criteria.cell(row_index, 1).width = Cm(5.4)
        for run in criteria.cell(row_index, 0).paragraphs[0].runs:
            run.bold = True
            run.font.size = Pt(8)
        for run in criteria.cell(row_index, 1).paragraphs[0].runs:
            run.font.size = Pt(8)
    criteria_cell.paragraphs[0].paragraph_format.space_after = Pt(0)

    title = document.add_paragraph(style="Title")
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER
    title.paragraph_format.space_before = Pt(5)
    title.paragraph_format.space_after = Pt(2)
    title.add_run(f"Rapport - {report_scope}")
    meta = document.add_paragraph()
    meta.alignment = WD_ALIGN_PARAGRAPH.CENTER
    meta.paragraph_format.space_after = Pt(7)
    meta_run = meta.add_run(
        f"Rapport d'analyse des flux et contrôles DAT | Sens : {direction_label} | Source : {source_display_label}"
    )
    meta_run.font.size = Pt(8.5)
    meta_run.font.color.rgb = RGBColor(93, 113, 135)

    document.add_heading("Synthese executive", level=1)

    def add_summary_bullet(label: str, text: str) -> None:
        paragraph = document.add_paragraph(style="List Bullet")
        paragraph.paragraph_format.space_after = Pt(2)
        bold_run = paragraph.add_run(f"{label}. ")
        bold_run.bold = True
        paragraph.add_run(text)

    add_summary_bullet("Activite", context["active_text"])
    if context["status_text"]:
        add_summary_bullet("Perimetre des statuts", context["status_text"])
    if context["time_text"]:
        add_summary_bullet("Fréquence temporelle", context["time_text"])
    add_summary_bullet("Flux financiers", context["flow_text"])
    if context["control_text"]:
        add_summary_bullet("Controle", context["control_text"])

    def add_table(
        frame: pd.DataFrame,
        columns: list[str],
        labels: dict[str, str],
        *,
        font_size: float = 8,
        amount_decimals: int = 2,
        column_widths_cm: dict[str, float] | None = None,
    ) -> Any | None:
        present = [column for column in columns if column in frame.columns]
        if frame.empty or not present:
            document.add_paragraph("Aucune donnee disponible.")
            return None
        table = document.add_table(rows=1, cols=len(present))
        table.style = "Table Grid"
        table.alignment = WD_TABLE_ALIGNMENT.CENTER
        table.autofit = column_widths_cm is None
        header_properties = table.rows[0]._tr.get_or_add_trPr()
        repeat_header = OxmlElement("w:tblHeader")
        repeat_header.set(qn("w:val"), "true")
        header_properties.append(repeat_header)
        for index, column in enumerate(present):
            cell = table.rows[0].cells[index]
            cell.text = labels.get(column, column)
            if column_widths_cm and column in column_widths_cm:
                cell.width = Cm(column_widths_cm[column])
            cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
            set_cell_shading(cell, "1F4E78")
            for run in cell.paragraphs[0].runs:
                run.bold = True
                run.font.color.rgb = RGBColor(255, 255, 255)
                run.font.size = Pt(font_size)
        for _, row in frame[present].iterrows():
            cells = table.add_row().cells
            for index, column in enumerate(present):
                value = row.get(column)
                if any(token in column for token in ["montant", "solde", "volume"]):
                    text = _pdf_number(value, decimals=amount_decimals)
                elif str(column).endswith("_pct"):
                    text = f"{float(value):.1f}%" if pd.notna(value) else "-"
                elif column in {"retenu_m1", "retenu_90j"}:
                    text = "-" if pd.isna(value) else "Oui" if bool(value) else "Non"
                elif column in {"date", "compte_cree"}:
                    date_value = pd.to_datetime(value, errors="coerce")
                    text = f"{date_value:%d/%m/%Y %H:%M:%S}" if pd.notna(date_value) else "-"
                elif column == "premier_retour":
                    date_value = pd.to_datetime(value, errors="coerce")
                    text = f"{date_value:%d/%m/%Y}" if pd.notna(date_value) else "-"
                else:
                    text = "-" if pd.isna(value) else str(value)
                cells[index].text = text
                if column_widths_cm and column in column_widths_cm:
                    cells[index].width = Cm(column_widths_cm[column])
                cells[index].vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
                for paragraph in cells[index].paragraphs:
                    paragraph.paragraph_format.space_after = Pt(0)
                    for run in paragraph.runs:
                        run.font.size = Pt(font_size)
        document.add_paragraph().paragraph_format.space_after = Pt(0)
        return table

    document.add_heading(f"Synthese des flux {flow_display_label} par devise", level=1)
    add_table(
        daily_pivot,
        ["currency_code", "nombre_entrees", "montant_total_entrees", "nombre_sorties", "montant_total_sorties", "solde_net_flux"],
        {
            "currency_code": "Devise", "nombre_entrees": "Nb entrees", "montant_total_entrees": "Montant entrees",
            "nombre_sorties": "Nb sorties", "montant_total_sorties": "Montant sorties", "solde_net_flux": "Solde net",
        },
    )
    document.add_heading("Principales operations", level=2)
    add_table(
        classified,
        ["currency_code", "sens_flux", "details_rapport", "nombre", "montant"],
        {"currency_code": "Devise", "sens_flux": "Sens", "details_rapport": "Operation", "nombre": "Nombre", "montant": "Montant"},
    )

    if context["has_retention"]:
        document.add_heading("Fidelisation", level=1)
        paragraph = document.add_paragraph(context["retention_text"])
        paragraph.paragraph_format.space_after = Pt(4)
        add_table(
            context["latest_retention"],
            ["Devise", "Retention M+1", "Retention 90 jours"],
            {},
        )

    if isinstance(transaction_detail, pd.DataFrame) and not transaction_detail.empty:
        detail = transaction_detail.copy()
        detail["currency_code"] = clean_text(
            detail.get("currency_code", pd.Series("", index=detail.index))
        ).str.upper().replace("", "SANS DEVISE")
        detail["date"] = pd.to_datetime(
            detail.get("date", pd.Series(pd.NaT, index=detail.index)), errors="coerce"
        )
        detail = detail.sort_values(
            ["currency_code", "date"], ascending=[True, False], na_position="last"
        ).reset_index(drop=True)
        detail_section = document.add_section(WD_SECTION.NEW_PAGE)
        detail_section.orientation = WD_ORIENT.PORTRAIT
        detail_section.page_width = Cm(21.0)
        detail_section.page_height = Cm(29.7)
        detail_section.top_margin = Cm(1.0)
        detail_section.bottom_margin = Cm(1.0)
        detail_section.left_margin = Cm(2.0)
        detail_section.right_margin = Cm(2.0)
        document.add_heading("Transactions", level=1)
        # detail_caption.paragraph_format.space_after = Pt(4)
        add_table(
            detail,
            G2_CLASSIFIED_TRANSACTION_COLUMNS,
            {column: column for column in G2_CLASSIFIED_TRANSACTION_COLUMNS},
            font_size=4.8,
            amount_decimals=2,
            column_widths_cm={
                "date": 2.1,
                "receipt_no": 1.55,
                "currency_code": 1.05,
                "details_rapport": 1.65,
                "opposite_party": 4.0,
                "duree": 1.05,
                "compte_cree": 1.9,
                "montant": 1.25,
                "montant_entree": 1.25,
                "montant_sortie": 1.25,
                "balance_numeric": 1.35,
            },
        )

    source = document.add_paragraph()
    source.paragraph_format.space_before = Pt(4)
    # source_run.italic = True
    # source_run.font.size = Pt(8)
    # source_run.font.color.rgb = RGBColor(96, 117, 138)

    footer = section.footer.paragraphs[0]
    footer.alignment = WD_ALIGN_PARAGRAPH.CENTER
    footer_run = footer.add_run(
        f"Rapport genere le {generated_at:%d/%m/%Y %H:%M} - Solution Bisou Bisou Digital"
    )
    footer_run.font.size = Pt(8)
    footer_run.font.color.rgb = RGBColor(110, 125, 140)

    document.core_properties.title = f"Rapport - {report_scope}"
    document.core_properties.subject = "Synthese destinee a la Direction generale"
    document.core_properties.author = "Solution Controle Interne"
    buffer = BytesIO()
    document.save(buffer)
    buffer.seek(0)
    return buffer.getvalue()


