def _normalize_export_column_key(column: Any) -> str:
    text = normalize_label(column)
    text = re.sub(r"[^a-z0-9]+", "_", text)
    return re.sub(r"_+", "_", text).strip("_")


def _sanitize_excel_sheet_name(name: Any, fallback: str = "Feuille") -> str:
    """Retourne un nom de feuille Excel valide et compact."""
    text = str(name or "").strip() or fallback
    text = re.sub(r"[\[\]\:\*\?\/\\]", "_", text)
    text = re.sub(r"\s+", " ", text).strip("' ").strip()
    return (text or fallback)[:31]


def _make_unique_excel_sheet_name(
    requested_name: Any,
    used_names: set[str],
    fallback: str = "Feuille",
) -> str:
    base_name = _sanitize_excel_sheet_name(requested_name, fallback=fallback)
    candidate = base_name
    counter = 2
    while candidate in used_names:
        suffix = f"_{counter}"
        candidate = f"{base_name[: 31 - len(suffix)]}{suffix}"
        counter += 1
    used_names.add(candidate)
    return candidate


def _is_operational_technical_column(column: Any) -> bool:
    key = _normalize_export_column_key(column)
    if key in MPESA_OPERATIONAL_TECHNICAL_COLUMN_EXACT_KEYS:
        return True
    if key.startswith(MPESA_OPERATIONAL_TECHNICAL_COLUMN_PREFIXES):
        return True
    if key.endswith(MPESA_OPERATIONAL_TECHNICAL_COLUMN_SUFFIXES):
        return True
    return any(token in key for token in MPESA_OPERATIONAL_TECHNICAL_COLUMN_CONTAINS)


